int max_rect(VI a){
    int n = a.size();
    VI l(n), r(n);

    stack<int> st;
    REP(i,n){
        while (!st.empty() && a[st.top()] >= a[i]) st.pop();
        l[i] = (st.empty() ? 0 : st.top() + 1);
        st.push(i);
    }

    while (!st.empty()) st.pop();
    FORR(i,n-1,0){
        while (!st.empty() && a[st.top()] >= a[i]) st.pop();
        r[i] = (st.empty() ? n : st.top());
        st.push(i);
    }

    int ret = 0;
    REP(i,n){
        ret = max(ret, a[i] * (r[i] - l[i] + 1));
    }
    return ret;
}

