int a[maxn][maxn];
int far[maxn][maxn];
int b[maxn];

pair<int,int> S[maxn];
int posn[maxn];

double insx(int a, int b) {
	if (b == 0) return -10000;
	return (double)(S[b].second - S[a].second)/(S[a].first - S[b].first);
}

int solve(int n) {
	fill(S, S+maxn, mp(0,0)); int hd = 0; int ans = -20;
	for (int i = 1; i <= n; i++) {
		int pos = i;
		while (hd > 0 && S[hd].first >= b[i]) { pos = min(pos, posn[hd]); hd--; }
		hd++; posn[hd] = pos; S[hd] = mp(b[i], -(pos-2)*b[i]);
		int l = 1, r = hd;
		while (l < r) {
			int mid = (l+r+1)>>1;
			if (insx(mid,mid-1) < i) {
				l = mid;
			} else {
				r = mid-1;
			}
		}
		ans = max(ans, S[l].first * i + S[l].second);
		ans = max(ans, S[l-1].first*i + S[l-1].second);
		ans = max(ans, S[l+1].first*i + S[l+1].second);
	}
	return ans;
}


