typedef long long li;

vector<int> closest_less(const vector<int> &xs) {
    vector<int> res;
    vector<int> stack;
    for (int i = 0; i < xs.size(); ++i) {
        while (not stack.empty() and xs[stack.back()] >= xs[i]) {
            stack.pop_back();
        }
        if (stack.empty()) {
            res.push_back(0);
        } else {
            res.push_back(stack.back());
        }
        stack.push_back(i);
    }
    return res;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int h, w;
    cin >> h >> w;
    vector<vector<bool>> board(h, vector<bool>(w));
    for (int i = 0; i < h; ++i) {
        string s;
        cin >> s;
        for (int j = 0; j < w; ++j) {
            board[i][j] = s[j] == '#';
        }
    }

    vector<vector<bool>> dots(h + 1, vector<bool>(w + 1));
    for (int i = 1; i < h; ++i) {
        for (int j = 1; j < w; ++j) {
            dots[i][j] = board[i - 1][j - 1] != board[i - 1][j] != board[i][j - 1] != board[i][j];
        }
    }

    vector<vector<int>> widths(h + 1, vector<int>(w + 1));
    for (int i = 0; i < h + 1; ++i) {
        int next = w;
        for (int j = w; j >= 0; --j) {
            widths[i][j] = next - j;
            if (dots[i][j]) {
                next = j;
            }
        }
    }

    int ans = 0;
    for (int col = 0; col < w + 1; ++col) {
        vector<int> hist;
        for (int row = 0; row < h + 1; ++row) {
            hist.push_back(widths[row][col]);
        }
        vector<int> l = closest_less(hist);
        reverse(hist.begin(), hist.end());
        vector<int> r = closest_less(hist);
        reverse(hist.begin(), hist.end());
        for (int i = 0; i < h + 1; ++i) {
            int height = hist[i];
            int width = (i - l[i]) + ((h - i) - r[h - i]);
            ans = max(ans, height * width);
        }
    }

    cout << ans << endl;
    return 0;
}

