#include<bits/stdc++.h>
using namespace std;

typedef pair<int, int> pii;

struct CHT {
    vector<int> M, B;
    vector<vector<pii> > R;
    void init() {
        M.clear();
        B.clear();
        R.clear();
    }
    bool bad(int l1, int l2, int l3) {
        return 1LL * (M[l1] - M[l2]) * (B[l3] - B[l1]) <= 1LL * (M[l1] - M[l3]) * (B[l2] - B[l1]);
    }
    void add(int m, int b) {
        while(M.size() && M.back() <= m) {
            b = B.back() / M.back() * m;
            M.pop_back();
            B.pop_back();
            for(int i = (int)R.back().size() - 1; i >= 0; i--) {
                add(R.back()[i].first, R.back()[i].second);
            }
            R.pop_back();
        }
        M.push_back(m);
        B.push_back(b);
        R.push_back(vector<pii>());
        while(M.size() >= 3 && bad(M.size() - 3, M.size() - 2, M.size() - 1)) {
            R.back().push_back(pii(M[M.size() - 2], B[B.size() - 2]));
            M.erase(M.end() - 2);
            B.erase(B.end() - 2);
            R.erase(R.end() - 2);
        }
        if(M.size() == 2 && M[M.size() - 2] == M.back()) {
            R.back().push_back(pii(M[M.size() - 2], B[B.size() - 2]));
            M.erase(M.end() - 2);
            B.erase(B.end() - 2);
            R.erase(R.end() - 2);
        }
    }
    int query(int x) {
        if(M.size() == 0) return 0;
        int s = 0, e = (int)M.size() - 2;
        int pos = 0;
        while(s <= e) {
            int m = (s + e)>>1;
            if((M[m] - M[m + 1]) * x >= B[m + 1] - B[m]) {
                pos = m + 1;
                s = m + 1;
            }
            else e = m - 1;
        }
        return M[pos] * x + B[pos];
    }
} cht;

