    int ret = 0;
    for(int i = 0; i < H; i++) {
        cht.init();
        for(int j = W - 1; j >= 0; j--) {
            if(Gp[i][j]) {
                cht.init();
                continue;
            }
            cht.add(-dp[i][j] - 1, -(j + 2) * (dp[i][j] + 1));
            ret = max(ret, -cht.query(-j));
        }
    }
    return ret;
}

