	vector<string> S(H); cin >> S;
	vector<vint> diff(H, vint(W));
	vector<vint> sum(H, vint(W, 1));
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W-1; j++) {
			diff[i][j] = S[i][j+1] != S[i][j];
		}
	}

	for (int i = 1; i < H; i++) {
		for (int j = 0; j < W-1; j++) {
			if (diff[i-1][j] == diff[i][j]) sum[i][j] += sum[i-1][j];
		}
		sum[i][W-1] = 0;
	}
	sum[0][W-1] = 0;

	int maxv = 0;
