				auto dat = st.top(); st.pop();
				chmax(maxv, dat.first * (j - dat.second + 1));
				chmin(minv, dat.second);
			}
			if (st.empty() || st.top().first < sum[i][j]) st.emplace(sum[i][j], minv);
		}
	}
