const int MAX_N = 2048;
int N, M;
char a[MAX_N][MAX_N];
int ne[MAX_N][MAX_N], spom[MAX_N];
string s;
stack < pair <int, int> > st;
int main()
{
    ios_base :: sync_with_stdio(0);
    cin.tie(0);
	cin >> N >> M;
	for(int i = 1; i <= N; ++ i)
    {
        cin >> s;
        for(int j = 0; j < M; ++ j)   a[i][j + 1] = s[j];
    }
    int ans = max(N, M);
    for(int i = 1; i < N; ++ i)
    {
        for(int j = 1; j < M; ++ j)
        {
            int brb = 0;
            for(int k = 0; k < 2; ++ k)
            {
                for(int p = 0; p < 2; ++ p)
                {
                    if(a[i + k][j + p] == '#')   ++ brb;
                }
            }
            if(brb % 2)   ne[i][j] = 0;
            else   ne[i][j] = 1;
        }
    }
    for(int i = 2; i < N; ++ i)
    {
        for(int j = 1; j < M; ++ j)
        {
            if(ne[i][j] == 0)   continue;
            ne[i][j] += ne[i - 1][j];
        }
    }
    for(int i = 1; i < N; ++ i)
    {
        for(int j = 1; j < M; ++ j)
        {
            if(ne[i][j] == 0)
            {
                while(!st.empty())   st.pop();
                continue;
            }
            pair <int, int> curr = {ne[i][j], 1};
            while(!st.empty() && (st.top().first >= curr.first))
            {
                curr.second += st.top().second;
                st.pop();
            }
            spom[j] = curr.second;
            st.push(curr);
        }
        while(!st.empty())   st.pop();
        for(int j = M - 1; j >= 1; -- j)
        {
            if(ne[i][j] == 0)
            {
                while(!st.empty())   st.pop();
                continue;
            }
            pair <int, int> curr = {ne[i][j], 1};
            while(!st.empty() && (st.top().first >= curr.first))
            {
                curr.second += st.top().second;
                st.pop();
            }
            int curans = (spom[j] + curr.second) * (curr.first + 1);
            if(curans > ans)   ans = curans;
            st.push(curr);
        }
        while(!st.empty())   st.pop();
    }
    cout << ans << "\n";
	return 0;
}

