#include <bits/stdc++.h>
using namespace std;

const int N = 2010;

int h, w;
char board[N][N];
int g[N][N];

int L[N], R[N];

int calc(vector<int> a) {
    vector<int> st;
    for (int i = 0; i < int(a.size()); i++) {
        while (!st.empty() && a[i] <= a[st.back()]) {
            st.pop_back();
        }
        L[i] = (st.empty() ? 0 : st.back() + 1);
        st.push_back(i);
    }

    st.clear();
    for (int i = int(a.size()) - 1; i >= 0; i--) {
        while (!st.empty() && a[i] <= a[st.back()]) {
            st.pop_back();
        }
        R[i] = (st.empty() ? int(a.size()) - 1 : st.back() - 1);
        st.push_back(i);
    }

    int res = 0;
    for (int i = 0; i < int(a.size()); i++) {
        res = max(res, a[i] * (R[i] - L[i] + 2));
    }

    return res;
}

int main() {
    scanf("%d %d", &h, &w);
    for (int i = 0; i < h; i++) {
        scanf("%s", board[i]);
    }
    for (int i = 0; i < h - 1; i++) {
        for (int j = 0; j < w; j++) {
            g[i][j] = (board[i][j] != board[i + 1][j]);
        }
    }

    vector<int> f(h - 1);
    int ans = 0;
    for (int j = w - 1; j >= 0; j--) {
        vector<int> nf(h - 1);
        for (int i = 0; i < h - 1; i++) {
            nf[i] = 1;
            if (j < w - 1 && g[i][j] == g[i][j + 1]) {
                nf[i] += f[i];
            }
        }
        swap(f, nf);
        ans = max(ans, calc(f));
    }

    printf("%d\n", ans);
}

