#include <bits/stdc++.h>
using namespace std;

const int N = 2005;

int arr[N][N];
int suff[N][N][2];
vector<int> hist;

int getMaxArea()
{
    stack<int> s;
    int max_area = 0,tp,area_with_top,i = 0,n = hist.size();
    while (i < n)
    {
        if (s.empty() || hist[s.top()] <= hist[i])
            s.push(i++);
        else
        {
            tp = s.top();  
            s.pop();  
            area_with_top = hist[tp] * (s.empty() ? i + 1 : i - s.top());
            if (max_area < area_with_top)
                max_area = area_with_top;
        }
    }
    while (s.empty() == false)
    {
        tp = s.top();
        s.pop();
        area_with_top = hist[tp] * (s.empty() ? i + 1 : i - s.top());
        if (max_area < area_with_top)
            max_area = area_with_top;
    }
    return max_area;
}

