const int N = 2100;
int a[N][N], b[N][N], l[N];
ll hh1[N][N], hh2[N][N], pwr[N];
int ans;
int mod = 1e9 + 7;
main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    //freopen("input.txt",  "r", stdin);
    //freopen("output.txt", "w", stdout);
    int h, w;
    cin >> h >> w;
    for (int i = 1; i <= h; i++){
        string s;
        cin >> s;
        for (int j = 1; j <= w; j++){
            if (s[j - 1] == '#') a[i][j] = 1; else
            b[i][j] = 1;
        }
    }
    pwr[0] = 1;
    for (int i = 1; i <= w; i++){
        for (int j = 1; j <= h; j++){
            hh1[i][j] = (hh1[i][j - 1] * 10 + a[j][i] + 5) % mod;
            hh2[i][j] = (hh2[i][j - 1] * 10 + b[j][i ] + 5) % mod;
            pwr[j] = pwr[j - 1] * 10 % mod;
        }
    }
    for (int i = 1; i <= 1; i++){
        vector < int > t;
        for (int j = 1; j < w; j++){
            int x = a[i][j];
            int y = a[i][j + 1];
            if (x == y){
                int l = i;
                int r = h + 1;
                while(r - l > 1){
                    int mid = (r + l) / 2;
                    if ((hh1[j][mid] - hh1[j][i - 1] * pwr[mid - i + 1] % mod + mod) % mod
                         == (hh1[j + 1][mid] - hh1[j + 1][i - 1] * pwr[mid - i + 1] % mod + mod) % mod)
                        l = mid; else r = mid;
                }
                t.pb(l - i + 1);
            } else{
                int l = i;
                int r = h + 1;
                while(r - l > 1){
                    int mid = (r + l) / 2;
                    if ((hh1[j][mid] - hh1[j][i - 1] * pwr[mid - i + 1] % mod + mod) % mod
                         == (hh2[j + 1][mid] - hh2[j + 1][i - 1] * pwr[mid - i + 1] % mod + mod) % mod)
                        l = mid; else r = mid;
                }
                t.pb(l - i + 1);
            }
        }
        stack < pair < int, int > > s;
        s.push({-1, 0});
        for (int i = 0; i < t.size(); i++){
            while(s.top().F >= t[i]) s.pop();
            l[i] = s.top().S;
            s.push({t[i], i + 1});
        }
        while(!s.empty()) s.pop();
        s.push({-1, t.size() + 1});
        for (int i = t.size() - 1; i >= 0; i--){
            while(s.top().F >= t[i]) s.pop();
            ans = max(ans, t[i] * (s.top().S - l[i]));
            s.push({t[i], i + 1});
        }
    }
    ans = max(ans, h);
    ans = max(ans, w);
    cout << ans;
}

