				continue;
			}
			if (sum[i][j] == sum[i][j + 1]) {
				r[j] = r[j + 1];
				continue;
			}
			while (!s.empty() && sum[i][s.top()] > sum[i][j]) {
				s.pop();
			}
			if (s.empty()) {
				r[j] = j;
			}
			else {
				if (sum[i][s.top()] == sum[i][j]) {
					r[j] = r[s.top()];
				}
				else {
					r[j] = s.top() - 1;
				}
			}
			//if (!s.empty() && sum[i][s.top()] == sum[i][j])continue;
			s.push(j);
		}
		for (int j = 0; j < W; j++) {
		//	cout << i << " " << j << " " << l[j] << " " << r[j] << " " << sum[i][j] << "  ";
			ans = max(ans, (r[j] - l[j] + 2)*(sum[i][j] + 1));
		}
		//cout << endl;
	}
	cout << ans << endl;
	return 0;
}

