using namespace::std;

struct Rectangle{LL height;int pos;};
void solve(){
	int H,W;
	cin >> H >> W;
	vector< string > RC(H);
	vector< vector<int> > fld(H-1,vector<int>(W-1,0));
	for(int h=0;h<H;++h){
		cin >> RC[h];
	}
	for(int h=0;h<H-1;++h){
		for(int w=0;w<W-1;++w){
			int cnt = 0;
			cnt += (RC[h][w]=='#');
			cnt += (RC[h+1][w]=='#');
			cnt += (RC[h][w+1]=='#');
			cnt += (RC[h+1][w+1]=='#');
			if( cnt % 2 == 0 ){
				//パリティを調べる。偶数なら1
				fld[h][w] = 1;
			}
		}
	}
	vector< vector<int> > fld2(H-1,vector<int>(W-1,0));
	fld2 = fld;
	for(int w=0;w<W-1;++w){
		for(int h=1;h<H-1;++h){
			if( fld2[h][w] == 0 ) continue;
			fld2[h][w] += fld2[h-1][w];
		}
	}
	--H;
	--W;
	int maxV = 0;
	for(int h=0; h<H; ++h){
		stack< Rectangle> S;
		for(int w=0;w<=W;++w){//ヒストグラムの最大長方形と同じ
			Rectangle rect;//高さと位置
			if( w != W ){//
				rect.height = fld2[h][w];
			}else{//
				rect.height = 0;//端の処理
			}
			rect.pos = w;
			if( S.empty() ){//空なら追加
				S.push( rect );
			}else{//空でない
				//高さが同じ時は何もしない。前の情報に任せる
				if( S.top().height < rect.height){//前より高い
					S.push( rect );
				}else if( S.top().height > rect.height ){//前より低い
					int target = w;
					while( !S.empty() && S.top().height >= rect.height){
						Rectangle pre = S.top();S.pop();
						//この問題特有。縦横それぞれに+1する。
						int area = (pre.height+1) * (1+w-pre.pos);
						maxV = max(maxV,area);
						target = pre.pos;
					}
					/*
					rect.heightの新しい指標をstackに積む
					同じ大きさの場合、一旦出してからここで入れなおす。
					同じ大きさがない場合
					rect.heightより大きい部分を削って、
					rect.heightの長方形が作れる一番左のrect.posを
					stackに積む
					*/
					rect.pos = target;
					S.push( rect );
				}
			}
		}
	}
	cout << maxV << endl;
}

