                rep (j, w-1) {
                        V<char> tmpv;
                        tmpv.pb(s[i][j]);
                        tmpv.pb(s[i][j+1]);
                        tmpv.pb(s[i+1][j]);
                        tmpv.pb(s[i+1][j+1]);
                        sort(tmpv);

                        string tmps;
                        tmps.pb(tmpv[0]);
                        tmps.pb(tmpv[1]);
                        tmps.pb(tmpv[2]);
                        tmps.pb(tmpv[3]);
                        if (tmps == "#..." || tmps == "###.") wall[i+1][j] = true;
                }
        }

        rep (i, w-1) hs[0][i] = 1LL;

        rep (i, h-1) {
                rep (j, w-1) {
                        hs[i+1][j] = ((wall[i+1][j]) ? 1LL : (hs[i][j] + 1LL));
                }
        }

        ll ans = max(h, w);

        rep (i, h) {
                deque<t2> stack;
                rep (j, w-1) {
                        for ( ; !(stack.empty()); ) {
                                t2 back = stack.back();
                                ll hs2 = get<0>(back);
                                ll j2 = get<1>(back);
                                if (hs[i][j] >= hs2) break;
                                stack.pop_back();
                                ans = max(ans, hs2 * (j - j2 + 1LL));
                        }

                        if (stack.empty()) {
                                stack.pb(t2(hs[i][j], 0LL));
                                continue;
                        }

                        t2 back = stack.back();
                        ll hs2 = get<0>(back);
                        if (hs[i][j] > hs2) stack.pb(t2(hs[i][j], j));
                }

                for ( ; !(stack.empty()); ) {
                        t2 back = stack.back(); stack.pop_back();
                        ll hs2 = get<0>(back);
                        ll j2 = get<1>(back);
                        ans = max(ans, hs2 * (w - j2));
                }
        }

        cout << ans;

        return 0;
}

