            if(s[j] == '#') S[i][j] = 1;
        }
    }

    mat n_suc(H, vec(W - 1, 0));
    REP(j, W - 1){
        int p = S[0][j] ^ S[0][j + 1], ib = 0;
        REP(i, H){
            if((S[i][j] ^ S[i][j + 1]) != p){
                p = S[i][j] ^ S[i][j + 1];
                FOR(k, ib, i){
                    n_suc[k][j] = k - ib + 1;
                }
                ib = i;
            }
            if(i == H - 1){
                FOR(k, ib, H){
                    n_suc[k][j] = k - ib + 1;
                }
            }
        }
    }

    mat n_right(H, vec(W - 1, 0)), n_left(H, vec(W - 1, 0));
    REP(i, H){
        stack<Pii> st;
        Pii p;
        REP(j, W - 1){

            while(!st.empty()){
                p = st.top();
                if(p.second < n_suc[i][j]){
                    n_left[i][j] = j - p.first - 1;
                    break;
                }else{
                    st.pop();
                }
            }
            if(st.empty()) n_left[i][j] = j;
            st.push(Pii(j, n_suc[i][j]));
        }
    }
    REP(i, H){
        stack<Pii> st;
        Pii p;
        IREP(j, W - 1){

            while(!st.empty()){
                p = st.top();
                if(p.second < n_suc[i][j]){
                    n_right[i][j] = p.first - j - 1;
                    break;
                }else{
                    st.pop();
                }
            }
            if(st.empty()) n_right[i][j] = W - 2 - j;
            st.push(Pii(j, n_suc[i][j]));
        }
    }

    int ans = max(H, W);
    REP(i, H){
        REP(j, W - 1){
            ans = max(ans, n_suc[i][j] * (n_left[i][j] + n_right[i][j] + 2));
        }
    }

    cout << ans;

    return 0;
}


