	cnt += b[x + 1][y];
	cnt += b[x][y + 1];
	cnt += b[x + 1][y + 1];
	return (!(cnt & 1));
}

void Init()
{
	memset(a, 0, sizeof(a));
	memset(b, 0, sizeof(b));
	for (int i = 1; i <= n; i++) {
		scanf("%s", s);
		for (int j = 0; j < m; j++)
			b[i][j + 1] = (int)(s[j] == '#');
	}
	for (int i = 1; i <= n - 1; i++)
		for (int j = 1; j <= m - 1; j++)
			if (Check(i, j)) a[i][j] = 1;
				else a[i][j] = 0;
}

void Solve()
{
	int i = 0, j = 0, lmax = 0, rmax = 0, ans = 1;
	n--; m--;
	memset(l, 0, sizeof(l));
	memset(r, 0, sizeof(r));
