using pil = pair<int, long long>;

long long largestRectangleFromHist(vector<long long> &v) {
  v.push_back(0);
  int n = v.size();
  long long ans = 0;
  vector<pil> stack;
  for (int i = 0; i < n; i++) {
    if (stack.size() == 0) {
      stack.push_back(make_pair(i, v[i]));
      ans = max(ans, v[i]);
    } else {
      if (stack[stack.size() - 1].second <= v[i]) {
        stack.push_back(make_pair(i, v[i]));
      } else {
        int j = i;
        while (stack.size() > 0 && stack[stack.size() - 1].second > v[i]) {
          j = min(j, stack[stack.size() - 1].first);
          ans = max(ans, (i - stack[stack.size() - 1].first) *
                             stack[stack.size() - 1].second);
          stack.pop_back();
        }
        stack.push_back(make_pair(j, v[i]));
      }
    }
  }
  return ans;
}

