vector<int> common(char* s, char* t, int n) {
    vector<int> ans(n);
    int r = 0;
    forn(i, 0, n) {
        if (r < i) r = i;
        while (r < n && s[r] == t[r]) ++r;
        ans[i] = r - i;
    }
    return ans;
