int f(vector <int> &x)
{
	stack < pair<int,int> > S;
	S.push(make_pair(-1,-1));
	int n = x.size();
	vector <int> lp(n), rp(n);
	for (int i = 0; i < n; ++i)
	{
		while(true)
		{
			pair <int,int> top = S.top();
			if(top.first >= x[i])
			{
				rp[top.second] = i;
				S.pop();
				lp[top.second] = (S.top()).second;
			}
			else
			{
				S.push(make_pair(x[i],i));
				break;
			}
		}
	}
	while(true)
	{
		pair <int,int> top = S.top();
		if(top.first >= 0)
		{
			rp[top.second] = n;
			S.pop();
			lp[top.second] = (S.top()).second;
		}
		else
		{
			break;
		}
	}
	int ans = 0;
	for (int i = 0; i < n; ++i)
	{
		ans = max(ans, x[i]*(rp[i] - lp[i]));
	}
	return ans;
}
