                  if(ch[i + 1][j + 1] != '#') a[i][j] ++;
                  a[i][j] %= 2;
                  a[i][j] ^= 1;
                  if(a[i][j]) a[i][j] += a[i - 1][j];
            }

      for(int i = 1; i <= n; i ++)
            build(i);

      for(int i = 1; i < n; i ++)
      {
            for(int j = 1; j < m; j ++)
            {
                  int h, w, l = 1, r = j;
                  if(!a[i][j]) continue;
                  while(r - l > 1)
                  {
                        int md = (l + r) >> 1;
                        if(get(md, j, i) >= a[i][j])
                              r = md;
                        else
                              l = md;
                  }
                  if(get(l, j, i) >= a[i][j])
                        r = l;
                  h = r;

                  l = j, r = m;

                  while(r - l > 1)
                  {
                        int md = (l + r) >> 1;
                        if(get(j, md, i) >= a[i][j])
                              l = md;
                        else
                              r = md;
                  }
                  if(get(j, r, i) >= a[i][j])
                        l = r;
                  w = l;

                  ans = max(ans, (w - h + 2) * (a[i][j] + 1));
            }
      }

      cout << ans << endl;
}

