int main(int argc, char const* argv[])
{
  int h, w;
  cin >> h >> w;
  rep(i, h)cin >> s[i];
  for(int i = 0; i < h; i++){
    for(int j = 0; j < w - 1; j++){
      if(i == 0){c[i][j] = 1; continue;}
      bool p = (s[i][j] == s[i][j+1]) == (s[i-1][j] == s[i-1][j+1]);
      c[i][j] = p ? c[i-1][j] + 1: 1;
    }
    c[i][w - 1] = 0;
  }
  ll res = 0;
  for(int i = 0; i < h; i++){
    stack<P> st;
    for(int j = 0; j < w; j++){
      if(st.empty()){
        st.push(mk(c[i][j], j));
      }else{
        if(st.top().first < c[i][j]){
          st.push(mk(c[i][j], j));
        }else if(st.top().first > c[i][j]){
          int pos = j;
          int target = j;
          while(!st.empty() && st.top().first >= c[i][j]){
            P p = st.top(); st.pop();
            res = max(res, (ll)p.first * (pos - p.second + 1));
            target = p.second;
          }
          st.push(mk(c[i][j], target));
        }
      }
    }
  }
  cout << res << endl;
	return 0;
}

