int biggest[2048];
Pt stk[2048];
int main()
{
  int h, w; scanf("%d %d", &h, &w);
  for (int i = 0; i < h; ++i) scanf("%s", data[i]);
  for (int i = 1; i < h; ++i)
    for (int j = 1; j < w; ++j)
    {
      int c = 0;
      c ^= data[i-1][j-1] == '#';
      c ^= data[i-1][j] == '#';
      c ^= data[i][j-1] == '#';
      c ^= data[i][j] == '#';
      danger[i][j] = c;
    }
  int ans = max(h, w);
  for (int i = 1; i < h; ++i)
  {
    for (int j = 1; j < w; ++j)
    if (danger[i][j]) biggest[j] = i;
    int top = 0;
    int total = 0;
    stk[top++] = {-1, 0};
    for (int j = 0; j < w;)
    {
      int k = j;
      while (k + 1 < w && biggest[k+1] == 0) ++k;
      //cerr << i << " " << j << " " << k << endl;
      int width = k - j + 1;
      int s = width * (i + 1);
      if (s > ans) ans = s;
      int height = i - biggest[j] + 1;
      while (top > 0 && height <= stk[top-1].h)
      {
        int w = j - stk[top-2].w - 1;
        int h = height;
        int s = w * h;
        if (s > ans) ans = s;
        --top;
      }
      stk[top++] = {k, height};
      j = k + 1;
    }
    while (top > 1)
    {
      --top;
      int s = stk[top].h * (stk[top].w - stk[top-1].w);
      if (s > ans) ans = s;
    }
  }
  printf("%d\n", ans);
  return 0;
}

