    int best = max(H, W);
    for (int oy = 0; oy < H; ++oy) {
        if ((H - oy) * W <= best)
            break;

        for (int ox = 0; ox < W; ++ox) {
            if ((H - oy) * (W - ox) <= best)
                break;

            int ex = W;
