#define MAXN 2005

int histogram()
{
	a[0] = a[m] = -1;
	stack < int > st;
	st.push(0);
	for(int i = 1; i <= m - 1; i++)
	{
		while( st.empty() == 0 )
		{
			int id = st.top();
			st.pop();
			if( a[id] < a[i] )
			{
				st.push(id);
				break;
			}
		}
		lft[i] = i - st.top();
		st.push(i);
	}
	while( st.empty() == 0 ) st.pop();
	st.push(m);
	for(int i = m - 1; i >= 1; i--)
	{
		while( st.empty() == 0 )
		{
			int id = st.top();
			st.pop();
			if( a[id] < a[i] )
			{
				st.push(id);
				break;
			}
		}
		rgt[i] = st.top() - i;
		st.push(i);
	}
	int ret = max( n , m );
	for(int i = 1; i <= m - 1; i++) ret = max( ret , (a[i] + 1) * ( rgt[i] + lft[i] ) );
	return ret;
}

int solve()
{
	int ret = 0;
	for(int i = 1; i <= n - 1; i++)
	{
		for(int j = 1; j <= m - 1; j++)
		{
			if( ara[i][j] == 0 )a[j] = 0;
			else a[j]++;
		}
		ret = max( ret , histogram() );
	}
	return ret;
}

