int getMaxRectangleArea(const std::vector<int>& v) {
	int max = 0;
	int w = v.size();
	struct P { int pos, height; };
	std::stack<P> st;
	for (int i = 0; i < w; ++i) {
		if (st.empty()) {
			st.push(P{ i, v[i] });
		}
		else if (st.top().height < v[i]) {
			st.push(P{ i, v[i] });
		}
		else if (st.top().height > v[i]) {
			while (!st.empty() && st.top().height > v[i]) {
				int area = (st.top().height + 1) * (i - st.top().pos + 1);
				CHMAX(max, area);
				st.pop();
			}
			st.push(P{ i, v[i] });
		}
	}
	while (!st.empty()) {
		int area = (st.top().height + 1) * (w - st.top().pos + 1);
		CHMAX(max, area);
		st.pop();
	}
	return max;
}

