int main() {
    int H, W; cin >> H >> W;
    vector<string> S(H); for (auto &s : S) cin >> s;
    vector<vector<int>> A(H - 1, vector<int>(W - 1));
    for (int i = 0; i < H - 1; i++) {
        for (int j = 0; j < W - 1; j++) {
            int a0 = S[i][j] == S[i][j + 1];
            int a1 = S[i + 1][j] == S[i + 1][j + 1];
            int b0 = S[i][j] == S[i + 1][j];
            int b1 = S[i][j + 1] == S[i + 1][j + 1];
            A[i][j] = (a0 == a1) && (b0 == b1);
        }
    }
    vector<vector<int>> B(H - 1, vector<int>(W));
    for (int i = 0; i < H - 1; i++) {
        for (int j = 0; j < W - 1; j++) {
            if (i == 0 && A[i][j]) {
                B[i][j] = 1;
            } else if (A[i][j]) {
                B[i][j] = B[i - 1][j] + 1;
            }
        }
    }
    int ans = max(H, W);
    stack<pair<int, int>> T; // idx, height
    for (int i = 0; i < H - 1; i++) {
        for (int j = 0; j < W; j++) {
            int height = B[i][j];
            while (!T.empty() && T.top().second > height) {
                int idx, hei; tie(idx, hei) = T.top();
                T.pop();
                chmax(ans, (j - idx + 1) * (hei + 1));
            }
            if (height > 0 && (T.empty() || (T.top().second != height))) {
                T.emplace(j, height);
            }
        }
    }
    cout << ans << '\n';
    return 0;
}

