// max Rectangle in Histogram

int calc(vector<int> v) {
  int n = v.size();
  vector<int> L(n), R(n);

  // decreasing from top
  stack<int> st;
  for(int i=0; i < n; i++) {
    L[i] = i;
    while(st.size() && v[st.top()] >= v[i]) {
      L[i] = st.top();
      if(v[st.top()] > v[i]) st.pop();
      else break;
    }
    if(st.empty()) L[i] = 0; /////////////////////
    if(st.empty() || v[st.top()] != v[i]) st.push(i);
  }
  st = stack<int>();
  for(int i=n-1; i >= 0; i--) {
    R[i] = i;
    while(st.size() && v[st.top()] >= v[i]) {
      R[i] = st.top();
      if(v[st.top()] > v[i]) st.pop();
      else break;
    }
    if(st.empty()) R[i] = n-1; /////////////////////
    if(st.empty() || v[st.top()] != v[i]) st.push(i);
  }
  int res = 0;
  for(int i=0; i < n; i++) {
    res = max(res, v[i] * (R[i] - L[i] + 2));
  }
  return res;
}

int main() {
  ios::sync_with_stdio(false), cin.tie(0);
  int h, w; cin >> h >> w;
  string s, t;

  // count from left, right
  vector< vector<int> > cl(w, vector<int>(h - 1, -1) ), cr(w, vector<int>(h - 1, -1) );

  for(int y=0; y < h; y++) {
    cin >> s;
    if(y != 0) {
      int l, r; l = r = 1;
      cl[0][y-1] = 1;
      cr[0][y-1] = 1;
      for(int x=1; x < w; x++) {
        int cnt = 0;
        for(int i=x-1; i <= x; i++) {
          if(s[i] == '.') cnt++;
          if(t[i] == '.') cnt++;
        }
        if(cnt % 2) l = 1;
        else l++;
        cl[x][y-1] = l;
      }
      for(int x=1; x < w; x++) {
        int cnt = 0;
        for(int i=x-1; i <= x; i++) {
          if(s[w-1-i] == '.') cnt++;
          if(t[w-1-i] == '.') cnt++;
        }
        if(cnt % 2) r = 1;
        else r++;
        cr[x][y-1] = r;
      }
    }
    t = s;
  }
  int ans = max(w, h);
  for(auto el : cl) ans = max(ans, calc(el));
  for(auto el : cr) ans = max(ans, calc(el));
  cout << ans << endl;
}

