lint max_recatngle(vector<int> &h){
    int n = h.size();
    int L[n], R[n];
    stack<int> st;

    rep(i, n){
        while(!st.empty() && h[st.top()] >= h[i]) st.pop();
        L[i] = st.empty() ? 0 : (st.top()+1);
        st.push(i);
    }
    while(!st.empty()) st.pop();

    rrep(i, n){
        while(!st.empty() && h[st.top()] >= h[i]) st.pop();
        R[i] = st.empty() ? n : st.top();
        st.push(i);
    }

    lint ret = 0;
    rep(i, n) ret = max(ret, 1LL * (h[i]+1) * (R[i]-L[i]+1));
    return ret;
}

