inline PII H(int p, int i, int l, int d, KMR &kmr)
{
    int r = l + d - 1;
    if(p == 0)
    {
        return kmr.hash(i * m + l, i * m + r);
    }
    else
    {
        return kmr.hash(n * m + i * m + l, n * m + i * m + r);
    }
}

