vector<int> stk;

inline void solve(int i, int n, int m, int &ans) {
    for (int j = 1; j < m; ++j) {
        if (mat[i][j] == mat[i][j + 1])
            arr[j] = dif[i - 1][j];
        else
            arr[j] = equ[i - 1][j];
    }

    stk.assign(1, 0);
    for (int j = 1; j < m; ++j) {
        while (arr[stk.back()] >= arr[j])
            stk.pop_back();

        lef[j] = stk.back() + 1;
        stk.push_back(j);
    }

    stk.assign(1, m);
    for (int j = m - 1; j > 0; --j) {
        while (arr[stk.back()] >= arr[j])
            stk.pop_back();

        rig[j] = stk.back() - 1;
        stk.push_back(j);
    }

    for (int j = 1; j < m; ++j)
        ans = max(ans, (rig[j] - lef[j] + 2) * (arr[j] + 1));

    return;
}

