template <int n, int m>
int maximumRectangle(const int (&arr)[n][m], int w, int h){
    for(int i=0;i<w-1;++i){
        for(int j=0,k=0;j<h-1;j=k){
            while(k < h - 1 && arr[k][i] == 1){++k;}
            j = k;
            while(k < h - 1 && arr[k][i] == 0){
                acc[k][i] = k - j + 1;
                ++k;
            }
        }
