    // for(int i=0;i<=10;++i){
    //     for(int j=0;j<=8;++j){
    //         std::cout << std::setw(2) << acc[i][j];
    //     }
    //     std::cout << std::endl;
    // }

    int res = 0;
    for(int i=0;i<h-1;++i){
        std::stack<std::tuple<int, int>> st;
        st.emplace(0, acc[i][0]);
        for(int j=1;j<w;++j){
            int p, h;
            std::tie(p, h) = st.top();

            if(h < acc[i][j]){
                st.emplace(j, acc[i][j]);
            }else if(h > acc[i][j]){
                int _p, _h;
                while(!st.empty() && snd(st.top()) >= acc[i][j]){
                    std::tie(_p, _h) = st.top();
                    res = std::max(res, (j - _p + 1) * (_h + 1));
                    st.pop();
                }

                st.emplace(_p, acc[i][j]);
            }
        }
    }

    return res;
}

