int calc_max_rect(vector<int> &A) {
  stack<pair<int, int> > st;
  int ret = 0;
  for (int i = 0; i <= (int)A.size(); i++) {
    int a = i < int(A.size()) ? A[i] : 0;
    int p = i, q = i;
    while (!st.empty() && st.top().first >= a) {
      int h = st.top().first;
      q = st.top().second;
      st.pop();
      int w = (p - q);
      if (p < sz(A)) w++;
      ret = max(ret, h * w);
    }
    st.push(make_pair(a, q));
  }
  return ret;
}

