void solve() {
  REP(i,H-1) {
    cum[i][W-1]=1;
    for(int j=W-2; j>=0; --j) {
      int cur=G[i][j]==G[i+1][j],r=G[i][j+1]==G[i+1][j+1];
      if(cur==r) cum[i][j]=cum[i][j+1];
