const int N = 2e3 + 5; char str[N][N];
int n, m, t[N][N], s[N][N], ans, sta[N], tp, len, l[N];

inline int mul(int a, int b) { return (a + 1) * (b + 1); }

inline void solve(int *h) {
	sta[tp = 0] = 0, len = 0;

	For(i, 1, m) {
		if (h[i] >= sta[tp]) 
			sta[++ tp] = h[i], l[tp] = 1;
		else {
			for (len = 0; tp && sta[tp] > h[i]; -- tp)
				len += l[tp], ans = max(ans, mul(len, sta[tp]));
			sta[++ tp] = h[i], l[tp] = len + 1;
		}
	}

	for (len = 0; tp; -- tp) 
		len += l[tp], ans = max(ans, mul(len, sta[tp]));
}

int main() {

	scanf("%d%d", &n, &m);

	For(i, 1, n) scanf("%s", str[i] + 1);

	For(i, 1, n) For(j, 1, m) t[i][j] = str[i][j] == '#';

	For(i, 1, n - 1) For(j, 1, m - 1) {
		int sum = t[i][j] + t[i + 1][j] + t[i][j + 1] + t[i + 1][j + 1];
		if (!(sum & 1)) s[i][j] = 1;
	}
	-- n, -- m, Set(t, 0);

	For(i, 1, n) For(j, 1, m)
		if (s[i][j] == 1) t[i][j] = t[i - 1][j] + 1;

	For(i, 1, n) solve(t[i]);

	ans = max(max(n + 1, m + 1), ans);

	printf("%d\n", ans);
	return 0;
}

