    }
    for(int h = 1; h < H; h++){
        for(int w = 1; w < W; w++){
            if(barrier[h-1][w-1]){
                hist_barrier[h][w] = 1;
            }else{
                hist_barrier[h][w] = hist_barrier[h-1][w] + 1;
            }
        }
    }

