int histMaxRect(vector<int> &histogram)
{
    int N = histogram.size();
    int maxS = 0;
    std::stack<pair<int, int> > st;
    st.push(make_pair(1, 0));
    for (int i=0; i<histogram.size(); i++)
    {
        if (st.top().first == histogram[i])
        {
            st.pop();
            st.push(make_pair(histogram[i], i));
            continue;
        }
        while(st.top().first > histogram[i])
        {
            pair<int, int> p_tmp = st.top();
            st.pop();
            maxS = max(maxS, (i-st.top().second) * p_tmp.first);
        }
        st.push(make_pair(histogram[i], i));
    }
    // for (auto h : histogram) cout << h << " ";
    // cout << endl;
    while (st.size() > 1)
    {
        pair<int, int> p_tmp = st.top();
        st.pop();
        maxS = max(maxS, (N - st.top().second) * p_tmp.first);
    }
    // cout << maxS << endl;
    return maxS;
}

