		if (c % 2 == 0) { a[i][j] = 1; }
	}

	vector<vector<ll>> up(H, vector<ll>(W, 0));
	repn(i, H - 1)repn(j, W - 1) {
		if (a[i][j] == 1) { up[i][j] = up[i-1][j] + 1; }
		else { up[i][j] = 0; }

		//cout << up[i][j];
	}

	ll ans = 0;

	repn(i, H-1) {
		stack<pair<ll, ll>> st;
		repn(j, W-1) {
			if (st.empty()) {
				ans = max(2 * (up[i][j] + 1), ans);
				st.push({ up[i][j],j });
			}

			else if (st.top().first < up[i][j]) {
				st.push({ up[i][j],j });
			}

			else if (st.top().first >= up[i][j]) {

				ll k;
				while (!st.empty()&&st.top().first>=up[i][j]) {
					k = st.top().second;
					ans = max(ans, (up[i][j] + 1)*(j - k + 2));
					st.pop();
				}
				st.push({ up[i][j],k });
			}
		}
	}

	cout << ans << endl;

	system("PAUSE");
}

