void append_range(map<ii,int>& r_next, map<ii,int>& r_prev, vector<ii>& r){
    int L = r.size();
    rep(i, L) {
        ii k = r[i];
        r_next[k] = max(r_next[k], 1);
    }

    for (auto p : r_prev) {
        ii x = p.first;
        int ph = p.second;
        for (int i=0; i<r.size(); ++i) {
            ii y = r[i];

            if (x.second <= y.first) {
                ;
            } else if (y.second <= x.first) {
                ;
            } else {
                if (x.first <= y.first && y.second <= x.second) {
                    // y部分だけ
                    r_next[y] = max(r_next[y], ph+1);
                } else if (y.first <= x.first && y.second <= x.second) {
                    ii k(x.first, y.second);
                    r_next[k] = max(r_next[k], ph+1);
                } else if (x.first <= y.first && x.second <= y.second) {
                    ii k(y.first, x.second);
                    r_next[k] = max(r_next[k], ph+1);
                } else if (y.first <= x.first && x.second <= y.second) {
                    r_next[x] = max(r_next[x], ph+1);
                }
            }
        }
    }
}

int solve(int H, int W, vector<string>& s) {
    vector<int> d(W);
    map<ii,int> r_prev;
    int best = W;

    for (int i=0; i<H-1; ++i) {
        // 順
        rep(c, W) {
            d[c] = (s[i][c] == s[i+1][c]);
        }
        vector<ii> r0 = ranges(W, d);

        // 逆
        rep(i, W) d[i] ^= 1;
        vector<ii> r1 = ranges(W, d);

#ifdef DEBUG
        cerr << i << ") " << r_prev << endl;
        cerr << "  + " << r0 << endl;
        cerr << "  + " << r1 << endl;
#endif
        for (ii p : r0) {
            best = max(best, 2 * (p.second - p.first));
        }
        for (ii p : r1) {
            best = max(best, 2 * (p.second - p.first));
        }

        map<ii,int> r_next;
        append_range(r_next, r_prev, r0);
        append_range(r_next, r_prev, r1);
#ifdef DEBUG
        cerr << " => " << r_next << endl;
#endif

        r_prev = r_next;

        for (auto p : r_prev) {
            ii x = p.first;
            int ph = p.second;
            best = max(best, (ph+1) * (x.second - x.first));
        }

    }

    return best;
}

