typedef long long li;

vector<int> closest_less(const vector<int> &xs) {
    vector<int> res;
    vector<int> stack;
    for (int i = 0; i < xs.size(); ++i) {
        while (not stack.empty() and xs[stack.back()] >= xs[i]) {
            stack.pop_back();
        }
        if (stack.empty()) {
            res.push_back(0);
        } else {
            res.push_back(stack.back());
        }
        stack.push_back(i);
    }
    return res;
}

