const int K = 13;
struct rmqindex
{
    int po[K],ar[2*N];
    int sp[N][K];
    int v[N];
    rmqindex()
    {
        int i,k;
        ar[1]=0,k=1,po[0]=1;
        while(k<N)
        {
            for(i=k+1;i<2*k;i++)
                ar[i]=ar[k];
            ar[2*k]=1+ar[k],k*=2;
        }
        for(i=1;i<K;i++)
            po[i]=2*po[i-1];
    }
    int operation(int a,int b) // check the operation
    {
        return v[a]<v[b]?a:b;
    }
    void build(vi &val,int n)
    {
        int i,k;
        rrep(i,n)
        {
            v[i]=val[i],sp[i][0]=i;
            for(k=1;i+po[k]<=n;k++)
                sp[i][k]=operation(sp[i][k-1],sp[i+po[k-1]][k-1]);
        }
    }
    int query(int a,int b)
    {
        a++,b--;
        int y,x=b-a+1;
        y=ar[x],x-=po[y];
        return operation(sp[a][y],sp[a+x][y]);
    }
};
int ar[N][N];
int dp[N][N];
int n,m;
rmqindex rmq;
ll largestrectangle(vi &v)
{
    int l,r,k;
    int n=sz(v);
    rmq.build(v,n);
    queue<ii> pq;
    pq.push({0,n-1});
    int area=0;
    while(!pq.empty())
    {
        tie(l,r)=pq.front();
        pq.pop();
        if(r-l==1)
            continue;
        k=rmq.query(l,r);
        remax(area,v[k]*(r-l));
        pq.push({l,k});
        pq.push({k,r});
    }
    return area;
}
int block(int i,int j)
{
    if(inrange(i,1,n-1) && inrange(j,1,m-1))
    {
        int a=0;
        a=ar[i][j]+ar[i-1][j]+ar[i][j-1]+ar[i-1][j-1];
        return (a&1);
    }
    return 0;
}
