		{
			S.pop();
		}
		if(S.empty()) R[i]=n-1;
		else R[i]=S.top().se-1;
		S.push(mp(vec[i],i));
	}
	int ans=0;
	for(int i=0;i<n;i++)
	{
		ans=max(ans,(R[i]-L[i]+2)*vec[i]);
	}
	return ans;
}

