template <class T>
inline void relax(T &a, const T &b)
{
	if (b > a)
		a = b;
}

const int MaxN = 2000;
const int MaxM = 2000;

int n, m;
char s[MaxN + 1][MaxM + 2];

int a[MaxN][MaxM];
int up[MaxN][MaxM + 1];

int sta_n, sta[MaxM + 1];

int main()
{
	cin >> n >> m;
	for (int i = 1; i <= n; ++i)
		scanf("%s", s[i] + 1);

	for (int i = 1; i < n; ++i)
		for (int j = 1; j < m; ++j)
			a[i][j] = !((s[i][j] == '#') ^ (s[i + 1][j] == '#') ^ (s[i][j + 1] == '#') ^ (s[i + 1][j + 1] == '#'));

	for (int i = 1; i < n; ++i)
		for (int j = 1; j < m; ++j)
			up[i][j] = a[i][j] ? up[i - 1][j] + 1 : 0;
	for (int i = 1; i < n; ++i)
		up[i][m] = 0;

	int res = max(n, m);
	for (int i = 1; i < n; ++i)
	{
		sta_n = 0;
		for (int j = 1; j <= m; ++j)
		{
			while (sta_n && up[i][sta[sta_n]] >= up[i][j])
			{
				relax(res, (up[i][sta[sta_n]] + 1) * (j - sta[sta_n - 1]));
				--sta_n;
			}
			sta[++sta_n] = j;
		}
	}

	cout << res << endl;

	return 0;
}

