	for (j=1;j<=W;j++)
	{
		c=getchar();
		while (c!='.'&&c!='#') c=getchar();
		g[i][j]=c=='#';
	}

	Ans=max(H,W);
	for (i=1;i<=H;i++)
	for (j=W;j>=2;j--)
		g[i][j]^=g[i][j-1];

	for (j=2;j<=W;j++)
	{
