		stack<pair<int, int> > st;
		for(int j = 0; j <= w; j++){
			if(st.empty()){
				st.push({j, t[i+1][j]});
				continue;
			}
			P p = st.top();
			if(p.second < t[i+1][j]){
				st.push({j, t[i+1][j]});
