int main() {
	scanf("%lld %lld", &H, &W);
	for (ll i = 0; i < H; i ++) {
		scanf("%s", s[i]);
		for (ll j = 0; j < W; j ++) {
			if (s[i][j] == '#') MAP[i][j] = 1;
			else MAP[i][j] = 0;
		}
	}
	ll ans = max(H, W);
	H --, W --;
	for (ll i = 0; i < H; i ++)
		for (ll j = 0; j < W; j ++) {
			if (MAP[i][j] ^ MAP[i + 1][j + 1] == MAP[i + 1][j] ^ MAP[i][j + 1]) RowGood[j] ++;
			else RowGood[j] = 0;
			stack<ll> sta; while (!sta.empty()) sta.pop();
			for (ll i = 0; i < W; i ++) {
				while (!sta.empty())
					if (RowGood[sta.top()] > RowGood[i]) {
						Right[sta.top()] = i; sta.pop();
					} else break;
				Left[i] = sta.empty() ? -1 : sta.top();
				sta.push(i);
			}
			while (!sta.empty()) {
				Right[sta.top()] = W;
				sta.pop();
			}
			for (ll i = 0; i < W; i ++) ans = max(ans, (Right[i] - Left[i]) * (RowGood[i] + 1));
		}
	printf("%lld\n", ans);
	return 0;
}

