long long LargestRectangle(vector<long long> height) {
    stack<long long> st;
    vector<long long> left(height.size()), right(height.size());
    for (int i = 0; i < (int)height.size(); ++i) {
        while (!st.empty() && height[st.top()] >= height[i]) st.pop();
        left[i] = !st.empty() ? st.top() + 1 : 0;
        st.push(i);
    }
    while (!st.empty()) st.pop();
    for (int i = (int)height.size() - 1; i >= 0; --i) {
        while (!st.empty() && height[st.top()] >= height[i]) st.pop();
        right[i] = !st.empty() ? st.top() : height.size();
        st.push(i);
    }
    long long res = 0;
    for (int i = 0; i < (int)height.size(); ++i) {
        //res = max(res, height[i] * (right[i] - left[i]));
        chmax(res, (height[i] + 1) * (right[i] - left[i] + 1));
    }
    return res;
}



