            for (int k = 0; k < 2; ++k) for (int l = 0; l < 2; ++l) {
                if (S[i+k][j+l] == '#') ++kuro;
                else ++siro;
            }
            if (kuro % 2 == 0) co[i][j] = 1;
            else co[i][j] = 0;
        }
    }
    memset(num, 0, sizeof(num));
    for (int i = 0; i < N-1; ++i) {
        int tmp = 0;
        for (int j = M-2; j >= 0; --j) {
            if (co[i][j] == 1) {
                ++tmp;
            }
            else {
                tmp = 0;
            }
            num[i][j] = tmp;
            //cout << i << ", " << j << ": " << co[i][j] << ", " << tmp << endl;
        }
    }
    for (int j = 0; j < M-1; ++j) {
        vector<long long> vec;
        for (int i = 0; i < N-1; ++i) vec.push_back(num[i][j]);
        chmax(res, LargestRectangle(vec));
    }

    return res;
}

