int histogram()
{
	/*for(int i = 1; i <= m - 1; i++)printf("%d ",a[i]);
	NL;*/
	stack < pii > st;
	st.push( _mp(0,0) );
	for(int i = 1; i <= m - 1; i++)
	{
		while( st.empty() == 0 )
		{
			pii my = st.top();
			st.pop();
			if( my.first < a[i] )
			{
				st.push(my);
				break;
			}
		}
		if( st.empty() )lft[i] = i;
		else lft[i] = i - st.top().second;
		st.push( _mp(a[i],i) );
	}
	while( st.empty() == 0 ) st.pop();
	st.push( _mp(0,m) );
	for(int i = m - 1; i >= 1; i--)
	{
		while( st.empty() == 0 )
		{
			pii my = st.top();
			st.pop();
			if( my.first < a[i] )
			{
				st.push(my);
				break;
			}
		}
		if( st.empty() )rgt[i] = m - i;
		else rgt[i] = st.top().second - i;
		st.push( _mp(a[i],i) );
	}
	int ret = 0;
	for(int i = 1; i <= m - 1; i++) ret = max( ret , (a[i] + 1) * ( rgt[i] - lft[i] + 2 ) );
	return ret;
}

