	}
	for (int i = 0;i < 2 * h - 1;++i) {
		for (int q = 0;q < 2 * w - 1;++q) {
			if (i % 2 == 0 || q % 2 == 0) {
				grid[i][q] = 0;
			}
			else {
				int cnt = 0;
				if (mewmew[i / 2][q / 2] == 1) cnt++;
				if (mewmew[i / 2 + 1][q / 2 + 1] == 1) cnt++;
				if (mewmew[i / 2 + 1][q / 2] == 1) cnt++;
				if (mewmew[i / 2][q / 2 + 1] == 1) cnt++;
				if (cnt % 2 == 1) {
					grid[i][q] = 1;
				}
			}
		}
	}
	h = 2 * h - 1;
	w = 2 * w - 1;
	for (int i = 0;i < w;++i) {
		int cnt = 0;
		for (int q = 0;q < h;++q) {
			cnt++;
			if (grid[q][i] == 1) cnt = 0;
			memorize[q][i] = cnt;
		}
	}
	long long ans = 0;
	for (int i = 0;i < h;++i) {
		stack<pair<int,int>> wow;
		for (int q = 0;q <= w;++q) {
			if (wow.empty() == true||wow.top().first < memorize[i][q]) {
				wow.push(make_pair(memorize[i][q],q));
			}
			else {
				int itring = q;
				while (wow.empty() == false&&wow.top().first > memorize[i][q]) {
					ans = max(ans, ((q - wow.top().second+1)/2) * (wow.top().first+1)/2);
					itring = min(itring, wow.top().second);
					wow.pop();
				}
				wow.push(make_pair(memorize[i][q], itring));
			}
		}
	}
	cout << ans << endl;
	return 0;
}

