template<int um> class UF {
public:
    vector<int> par,rank;
    vector<int>sz;
    UF() {rank=vector<int>(um,0); for(int i=0;i<um;i++){par.push_back(i);sz.pb(1);}}
    int operator[](int x) {return (par[x]==x)?(x):(par[x] = operator[](par[x]));}
    int operator()(int x,int y) {
        sz[x]=sz[x]+sz[y];
        sz[y]=sz[x];
        if((x=operator[](x))==(y=operator[](y))) return x;
        if(rank[x]<rank[y]) return par[x]=y;//rankが小さいxの親をyにする
        rank[x]+=rank[x]==rank[y]; return par[y]=x;//rankがxとyで一緒ならrank++
    }
    bool same(int x,int y){return operator[](x)==operator[](y);}
};
