void upd(int dtx,int dty){ans=max(ans,calc(dtx,dty));}
int getpos(int dt,int h1,int h2){return ceil((1.0*dt*h1)/((h2-h1)*1.0));}
void ins(int x,int y){
	if(hd>tl){tl++,q[tl][0]=x,q[tl][1]=y;return;}
	int lst=x;
	while(hd<=tl&&q[tl][1]<=y) lst=q[tl][0],tl--;
	while(hd<tl){
		int t1=getpos(q[tl][0]-q[tl-1][0],q[tl-1][1],q[tl][1])+q[tl][0]+1;
		int t2=getpos(lst-q[tl-1][0],q[tl-1][1],y)+lst+1;
		if(t2>=t1) tl--; else break;
	}
	tl++,q[tl][0]=lst,q[tl][1]=y;
}
void check(int x,int y){
	while(hd<tl){
		int t1=q[hd][0],h1=q[hd][1];
		int t2=q[hd+1][0],h2=q[hd+1][1];
		if(calc(y-t1,x-h1)<=calc(y-t2,x-h2)) hd++;
		else break;
	}
}
