// ---------------------- template ----------------------

long long MaxRectInHist(const std::vector<int> &h) {
    int n = h.size();
    std::stack<int> s;
    std::vector<int> L(n), R(n);
    for (int i = 0; i < n; i++) {
        while (s.size() && h[s.top()] >= h[i]) s.pop();
        L[i] = s.size() ? (s.top() + 1) : 0;
        s.push(i);
    }
    while (s.size()) s.pop();
    for (int i = n - 1; i >= 0; i--) {
        while (s.size() > 0 && h[s.top()] >= h[i]) s.pop();
        R[i] = s.size() ? s.top() : n;
        s.push(i);
    }
    long long res = 0;
    for (int i = 0; i < n; i++) {
        res = std::max(res, (long long)(h[i]+1) * (R[i] - L[i]+1));
    }
    return res;
}

int GetMaxRect(vector<vector<bool> > field) {
	vector<vector<int> > hists(field.size(), vector<int>(field[0].size()));
	REP(j, field[0].size()) {
		if (field[0][j]) hists[0][j] = 1;
		else hists[0][j] = 0;
	}
	int res = MaxRectInHist(hists[0]);
	FOR(i, 1, field.size()) {
		REP(j, field[i].size()) {
			if (field[i][j] != 0) {
				hists[i][j] += hists[i - 1][j] + 1;
			}
		}
		res = max(res, MaxRectInHist(hists[i]));
	}
	return res;
}

void solve() {
	int H, W; cin >> H >> W;
	vector<string> S;
	REP(i, H) {
		string str; cin >> str;
		S.push_back(str);
	}
	vector<vector<bool> > field(H - 1, vector<bool>(W - 1));
	REP(i, field.size()) {
		REP(j, field[i].size()) {
			int cnt = 0;
			for (int x = 0; x < 2; ++x) {
				for (int y = 0; y < 2; ++y) {
					if (S[i + x][j + y] == '#') ++cnt;
				}
			}
			if (cnt % 2 == 0) field[i][j] = true;
			else field[i][j] = false;
		}
	}

	cout << max(GetMaxRect(field), max(H,W)) << endl;
}

