int main ()
{
    int i, j;
    scanf ("%d%d", &n, &m);
    for (i = 1; i <= n; i ++)
        scanf ("%s", c[i] + 1);

    for (i = 1; i < n; i ++)
        for (j = 1; j < m; j ++)
        {
            a[i][j] = ((c[i][j] == '#') + (c[i + 1][j] == '#') + (c[i][j + 1] == '#') + (c[i + 1][j + 1] == '#')) & 1;
            if (a[i][j])
                l[i][j] = 0;
            else
                l[i][j] = l[i - 1][j] + 1;
        }

    if (n < m)
        ans = m;
    else
        ans = n;

    n --;
    m --;

    vector <pair <int, int>> t;

    for (i = 1; i <= n; i ++)
    {
        t.clear ();

        for (j = m; j >= 1; j --)
        {
            int cnt = 1;
            while (t.size () && t[t.size () - 1].first >= l[i][j])
            {
                cnt += t[t.size () - 1].second;
                t.pop_back ();
            }
            t.push_back ({l[i][j], cnt});
            right[j] = cnt;
        }

        t.clear ();

        for (j = 1; j <= m; j ++)
        {
            int cnt = 1;
            while (t.size () && t[t.size () - 1].first >= l[i][j])
            {
                cnt += t[t.size () - 1].second;
                t.pop_back ();
            }
            t.push_back ({l[i][j], cnt});

            if ((right[j] + cnt) * (l[i][j] + 1) > ans)
                ans = (right[j] + cnt) * (l[i][j] + 1);
        }
    }

    printf ("%d\n", ans);

    return 0;
}

#include<iostream>
