using namespace std;

#define sz(x) (int)(x.size())
#define fr(i,a,b) for(int i=a;i<b;++i)
#define fdr(i,a,b) for(int i=b-1;i>=a;--i)
#define mp make_pair
#define pb push_back
typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;
/////////////////////

int const N = 2e3 + 41;

int n, m;
int a[N][N];
string s[N];

int same[N][N], diff[N][N];
int l[N][N], r[N][N];

vector<pii> q;

void buildL(int l[N], int same[N], int diff[N], int a[N]){
	q.clear();
	fr(i, 1, m+1){
		int v;
		if(a[i] == a[i-1]) v = same[i];
		else v = diff[i];
		while(sz(q) > 0 && (q.back().first <= v)){
			q.pop_back();
		}
		if(sz(q) == 0) l[i] = 0;
		else l[i] = q.back().second - 1;
		q.pb(mp(v, i));
	}
}

void buildR(int r[N], int same[N], int diff[N], int a[N]){
	q.clear();
	fdr(i, 1, m+1){
		int v;
		if(a[i] == a[i-1]) v = same[i];
		else v = diff[i];
		while(sz(q) > 0 && (q.back().first <= v)){
			q.pop_back();
		}
		if(sz(q) == 0) r[i] = m + 1;
		else r[i] = q.back().second;
		q.pb(mp(v, i));
	}
}

void solve(){
	cin >> n >> m;
	fr(i, 0, n) cin >> s[i];
	fr(i, 0, n) fr(j, 0, m){
		if(s[i][j] == '#') a[i+1][j+1] = 1;
	}
	fr(i, 1, n+1) fr(j, 1, m+1){
		if(j == 1){
			same[i][j] = diff[i][j] = 0;
		}else{
			if(a[i][j] == a[i][j-1]){
				same[i][j] = same[i-1][j];
				diff[i][j] = i;
			}else{
				diff[i][j] = diff[i-1][j];
				same[i][j] = i;
			}
		}
	}


	fr(i, 2, n+1){
		buildL(l[i], same[i-1], diff[i-1], a[i]);
		buildR(r[i], same[i-1], diff[i-1], a[i]);
	}

	int ans = max(n, m);
	fr(i, 2, n+1){
		fr(j, 2, m+1){
			int h = i;
			if(j > 1){
				if(a[i][j] == a[i][j-1]) h -= same[i][j];
				else h -= diff[i][j];
			}
			int w = r[i][j] - l[i][j] - 1;
			ans = max(ans, h * w);

		}
	}
	cout << ans << endl;
}

int main(){
#ifdef _DEBUG
	freopen("input.txt","r",stdin);
	freopen("output.txt","w",stdout);
#endif

	solve();


	return 0;
}

