void solve() {
	cin >> h >> w;
    s.assign(h, vector<char>(w));
    rep(i, h) {
        rep(j, w) {
            cin >> s[i][j];
        }
    }
    vector<vector<int>> check(h, vector<int>(w - 1));
    rep(j, w - 1) {
        rep(i, h) {
            check[i][j] = ((s[i][j] == '#') ^ (s[i][j + 1] == '#'));
        }
    }
    // rep(i, h) {
    //     rep(j, w - 1) {
    //         cerr << check[i][j];
    //     }
    //     cerr << endl;
    // }
    vector<vector<int>> cnt(h, vector<int>(w - 1, 1));
    rep(j, w - 1) {
        int cur = 1, now = check[0][j];
        for(int i = 1; i < h; ++ i) {
            if(now == check[i][j]) {
                ++ cur;
                cnt[i][j] = cur;
            } else {
                cur = 1;
                cnt[i][j] = cur;
                now = check[i][j];
            }
        }
    }
    // rep(i, h) {
    //     rep(j, w - 1) {
    //         cerr << cnt[i][j];
    //     }
    //     cerr << endl;
    // }
    int ans = 0;
    rep(i, h) {
        vector<int> l(w - 1), r(w - 1);
        stack<int> st;
        rep(j, w - 1) {
            while(st.size() and cnt[i][st.top()] >= cnt[i][j]) st.pop();
            l[j] = (st.empty() ? 0 : st.top() + 1);
            st.push(j);
        }
        while(st.size()) st.pop();
        per(j, w - 1) {
            while(st.size() and cnt[i][st.top()] >= cnt[i][j]) st.pop();
            r[j] = (st.empty() ? w - 1 : st.top());
            st.push(j);
        }
        rep(j, w - 1) {
            chmax(ans, cnt[i][j] * (r[j] - l[j] + 1));
        }
    }
    cout << ans << endl;
}

