struct Rectangle{long long height,pos; };
long long getRectangleArea(long long size, long long buffer[]){
	stack<Rectangle> S;
	long long maxv = 0;
	buffer[size] = 0;
	for (int i=0;i<=size;i++){
    	Rectangle rect;
        rect.height = buffer[i];
        rect.pos = i;
        if (S.empty()){
        	S.push(rect);
		}else{
       		if(S.top().height<rect.height){
            	S.push(rect);
       		}else if(S.top().height>rect.height){
            	int target = i;
            	while (!S.empty() && S.top().height>=rect.height){
            		Rectangle pre = S.top(); S.pop();
                	long long area = pre.height * (i - pre.pos+1);
                	maxv = max(maxv,area);
                	target = pre.pos;
            	}
            	rect.pos = target;
            	S.push(rect);
       		}
      	}
     }
     return maxv;
}

