		vector<int> height(W, 0);
		int res = 2;
		for(int i=1;i<H;i++){
			for(int j=1;j<W;j++){
				int cnt = 0;
				for(int ii=0;ii<2;ii++){
					for(int jj=0;jj<2;jj++){
						if(vs[i-ii][j-jj]=='#') ++cnt;
					}
				}
				if(cnt%2 == 0){
					++height[j-1];
				} else {
					height[j-1] = 0;
				}
			}
			stack<pair<int,int>> st;
			for(int j=0;j<W;j++){
				int h = height[j];
				int p = j;
				while(!st.empty() && h < st.top().first){
					res = max(res, (st.top().first + 1) * (j - st.top().second + 1));
					p = st.top().second;
					st.pop();
				}
				if(h > 0 && (st.empty() || st.top().first < h)) st.emplace(h, p);
			}
		}
		cout << res << endl;
	}
}

