};

int is_ok[2048][2048];
int h[2048][2048];

void solve(ll H, ll W, vector<string> S) {
  REP(i,H-1) REP(j,W-1)
    is_ok[i][j] = ((S[i][j] == S[i][j+1]) == (S[i+1][j] == S[i+1][j+1]));
  REP(i,H-1) REP(j,W-1) {
    if (i == 0) h[i][j] = is_ok[i][j] + 1;
    else {
      if (is_ok[i][j]) h[i][j] = h[i-1][j] + 1;
      else h[i][j] = 1;
    }
  }
  int res = 0;
  REP(i,H-1) {
    vector<pair<int,int>> left;
    left.emplace_back(-1, -1);
    REP(j,W) {
      int pos = j;
      while (h[i][j] < left.back().second) {
        int val = left.back().second * (j - left.back().first + 1);
        chmax(res, val);
        pos = left.back().first;
        left.pop_back();
      }
      if (h[i][j] > left.back().second) {
        left.emplace_back(pos, h[i][j]);
      }
    }
  }
  assert (res >= H && res >= W);
  cout << res << endl;
}

