                  if(ch[i][j + 1] == '#') a[i][j] ++;
                  if(ch[i + 1][j] != '#') a[i][j] ++;
                  if(ch[i + 1][j + 1] != '#') a[i][j] ++;
                  a[i][j] %= 2;
                  a[i][j] ^= 1;
                  if(a[i][j]) a[i][j] += a[i - 1][j];
            }

      for(int i = 1; i <= n; i ++)
