  for (int i = 0; i < h; i++) {
    table[i].resize(w);
    for (int j = 0; j < w; j++)
      table[i][j] = 1;
  }
  for (int i = 1; i < h; i++)
    for (int j = 0; j < w; j++)
      if (!(ng[i][j] && ng[i][j + 1])) {
        table[i][j] = table[i - 1][j] + 1;
        if (ng[i][j + 1])
          ng[i + 1][j + 1] = true;
      }
