using namespace std;

const int inf = 1e9 + 7;
const int N = 2002;

typedef long long ll;

int n, m, ans, a[N][N], table[11][N][N], numlog[N];
char ch[N][N];

void build(int x)
{
      for(int i = 0; i <= numlog[m]; i ++)
      {
            int curlen = 1 << i;
            for(int j = 1; j <= m; j ++)
            {
                  if(i == 0)
                  {
                        table[i][x][j] = a[x][j];
                        continue;
                  }
                  table[i][x][j] = min(table[i - 1][x][j], table[i - 1][x][min(j + curlen / 2, m)]);
            }
      }
}

int get(int l, int r, int x)
{
      int curlog = numlog[(r - l + 1)];
      return min(table[curlog][x][l], table[curlog][x][r - (1 << curlog) + 1]);
}

int main()
{
      for(int i = 2; i < N; i ++)
            numlog[i] = numlog[i / 2] + 1;

      memset(table, 127, sizeof(table));

      scanf("%d %d", &n, &m);

      for(int i = 1; i <= n; i ++)
      {
            scanf("\n");
            for(int j = 1; j <= m; j ++)
                  scanf("%c", &ch[i][j]);
      }

      for(int i = 1; i < n; i ++)
            for(int j = 1; j < m; j ++)
            {
                  if(ch[i][j] == '#') a[i][j] ++;
                  if(ch[i][j + 1] == '#') a[i][j] ++;
                  if(ch[i + 1][j] != '#') a[i][j] ++;
                  if(ch[i + 1][j + 1] != '#') a[i][j] ++;
                  a[i][j] %= 2;
                  a[i][j] ^= 1;
                  if(a[i][j]) a[i][j] += a[i - 1][j];
            }

      for(int i = 1; i <= n; i ++)
            build(i);

      for(int i = 1; i < n; i ++)
      {
            for(int j = 1; j < m; j ++)
            {
                  int h, w, l = 1, r = j;
                  if(!a[i][j]) continue;
                  while(r - l > 1)
                  {
                        int md = (l + r) >> 1;
                        if(get(md, j, i) >= a[i][j])
                              r = md;
                        else
                              l = md;
                  }
                  if(get(l, j, i) >= a[i][j])
                        r = l;
                  h = r;

                  l = j, r = m;

                  while(r - l > 1)
                  {
                        int md = (l + r) >> 1;
                        if(get(j, md, i) >= a[i][j])
                              l = md;
                        else
                              r = md;
                  }
                  if(get(j, r, i) >= a[i][j])
                        l = r;
                  w = l;

                  ans = max(ans, (w - h + 2) * (a[i][j] + 1));
            }
      }

      cout << ans << endl;
}

