int m, n, a[maxn][maxn], Left[maxn], Right[maxn], f[maxn][maxn];
vector<int> p;
stack<int> st;

int solve(const vector<int> p) {
    while (st.sz()) st.pop();
    REP(i, p.sz()) {
        while (st.sz() && p[st.top()]>=p[i]) st.pop();
        if (st.sz()) Left[i] = st.top();
        else Left[i] = -1;
        st.push(i);
    }
    REPD(i, p.sz()) {
        while (st.sz() && p[st.top()]>=p[i]) st.pop();
        if (st.sz()) Right[i] = st.top();
        else Right[i] = p.sz();
        st.push(i);
    }
    int res = 0;
    REP(i, p.sz()) {
        res = max(res, (Right[i]-Left[i])*p[i]);
    }
    return res;
}

