    int a[n+2] , l[n+1] , r[n+1] , ans = 0 , x , y ;
    stack<int> s , p ;
    for(int i = 1 ; i <= n ; ++i) a[i] = heights[i-1] ;
    a[0] = -1 , a[n+1] = -1 ;
    s.push(0) ;
    for(int i = 1 ; i <= n ; ++i)
    {
        while(a[s.top()]>=a[i]) s.pop() ;
        l[i] = s.top() ;
        s.push(i) ;
    }
    p.push(n+1) ;
    for(int i = n ; i > 0 ; --i)
    {
        while(a[p.top()]>=a[i]) p.pop() ;
        r[i] = p.top() ;
        p.push(i) ;
    }
    for(int i = 1 ; i <= n ; ++i)
