    auto hist = vectors(h - 1, w, int());
    repeat (y, h - 1) {
        hist[y][w - 1] = 1;
        repeat_reverse (x, w - 1) {
            bool p = ((s[y][x] == s[y + 1][x]) == (s[y][x + 1] == s[y + 1][x + 1]));
            hist[y][x] = (p ? hist[y][x + 1] + 1 : 1);
        }
    }
    int result = max(h, w);
