        for (int y = 0; y < h; y ++) cin >> s[y];
        vector<vector<int> > t(2 * h - 1, vector<int> (2 * w - 1, 1));
        for (int y = 1; y < 2 * h - 2; y += 2) {
                for (int x = 1; x < 2 * w - 2; x += 2) {
                        int yy = y / 2, xx = x / 2;
                        int getxor = s[yy][xx] ^ s[yy + 1][xx] ^ s[yy][xx + 1] ^ s[yy + 1][xx + 1];
                        if (getxor) t[y][x] = 0;
                }
        }
        pair<int, vector<int>> get = LargestRectangle(t, 2 * h - 1, 2 * w - 1);
        int ans = 0;
        for (int i = 0; i < get.second.size(); i ++) {
                int height = get.second[i];
                int width = get.first / height;
                int res = ((height + 1) / 2) * ((width + 1) / 2);
                ans = max(ans, res);
        }
