  for (ll i = 0; i < H - 1; i++) {
    for (ll j = 0; j < W - 1; j++) {
      if ((G[i][j] + G[i][j + 1] + G[i + 1][j] + G[i + 1][j + 1]) % 2) {
        A[i][j] = 1;
      }
    }
  }

  vvi B(H - 1, vi(W - 1));
  for (ll i = 0; i < H - 1; i++) {
    for (ll j = 0; j < W - 1; j++) {
      if (A[i][j]) {
        B[i][j] = 0;
      } else {
        if (i == 0)
          B[i][j] = 1;
        else
          B[i][j] = B[i - 1][j] + 1;
      }
    }
  }

  ll ans = 0;

  for (ll i = 0; i < H - 1; i++) {
    stack<pair<ll, ll>> s;
    for (ll j = 0; j < W - 1; j++) {
      if (s.size() == 0 && B[i][j] > 0) {
