i64 histgram(int n, const vector<int> &h) {
    vector<int> L(n), R(n);

    stack<int> s;
    for (int i = 0; i < n; ++i) {
        while (!s.empty() && h[s.top()] >= h[i]) {
            s.pop();
        }

        L[i] = s.empty() ? 0 : (s.top() + 1);
        s.push(i);
    }

    s = stack<int>();
    for (int i = n - 1; i >= 0; i--) {
        while (!s.empty() && h[s.top()] >= h[i]) {
            s.pop();
        }

        R[i] = s.empty() ? n : s.top();
        s.push(i);
    }

    i64 res = 0;
    for (int i = 0; i < n; ++i) {
        res = max(res, (i64)h[i] * (R[i] - L[i]));
    }

    return res;
}

