long double insx(int a, int b) {
	if (b == 0 || a == 0) return -10000;
	if (a == b) return 1000000;
	return ((long double)(S[b].second - S[a].second))/(S[a].first - S[b].first);
}

int solve(int n) {
	fill(S, S+maxn, mp(0,0)); int hd = 0, idx = 0; int ans = -20;
	for (int i = 1; i <= n; i++) {
		int pos = i;
		while (hd > 0 && S[hd].first >= b[i]) { pos = min(pos, posn[hd]); hd--; }
		hd++; posn[hd] = pos; S[hd] = mp(b[i], -(pos-2)*b[i]);
		idx = min(idx, hd);
		while (idx < hd && insx(idx,idx+1) < i) idx++;
		ans = max(ans, S[idx].first * i + S[idx].second);

	}
	return ans;
}


