int l[2005], r[2005];

int calc(int x)
{
	stack<int> stk;
	stk.push(0);
	h[x][0] = -1;
	for(int i = 1; i <= H; i++){
		while(h[x][stk.top()] >= h[x][i]) stk.pop();
		l[i] = stk.top()+1;
		stk.push(i);
	}

	while(stk.size()) stk.pop();
	stk.push(H+1);
	h[x][H+1] = -1;
	for(int i = H; i >= 1; i--){
		while(h[x][stk.top()] >= h[x][i]) stk.pop();
		r[i] = stk.top()-1;
		stk.push(i);
	}

	int ret = 0;
	for(int i = 1; i <= H; i++){
		ret = max(ret, (h[x][i] + 1) * (r[i] - l[i] + 2));
	}
	return ret;
}

