using namespace std;
const int Max_NM(2050);

int N, M, rev[Max_NM][Max_NM], up[Max_NM][Max_NM];
char S[Max_NM];

void init()
{
	scanf("%d%d", &N, &M);
	for (int i = 1;i <= N;++i)
	{
		scanf("%s", S + 1);
		for (int j = 2;j <= M;++j)
			rev[i][j] = (S[j - 1] != S[j]), up[i][j] = (rev[i][j] == rev[i - 1][j] ? up[i - 1][j] : 0) + 1; 
	}
}

int L[Max_NM], R[Max_NM];
void work()
{
	int Ans(0);
	for (int i = 1;i <= N;++i)
	{
		/*
		stack<int> S;
		for (int j = 2;j <= M;++j)
