			while (S.empty() == false && up[i][S.top()] > up[i][j])
				L[S.top()] = j + 1, S.pop();
			S.push(j);
		}
		while (S.empty() == false)
			L[S.top()] = 2, S.pop();
		for (int j = 2;j <= M;++j)
			Ans = max(Ans, up[i][j] * (R[j] - L[j] + 2));
		*/
		for (int j = 2;j <= M;++j)
