void pre()
{
	for(int i=1;i<=n;++i)
	for(int t=1;t<=m;++t)
	c[i][t]=(b[i][t]?c[i][t-1]+1:0);
}

void solve()
{
	int ans=0;
	pre();
	for(int t=1;t<=m;++t)
	{
		int top=0;int op1=1;
		for(int i=1;i<=n;++i)
		{
			op1=i;
			while(top&&q[top]>=c[i][t])
			{
				ans=max(ans,min(m-1,i-op[top])*min(n-1,q[top]));
				op1=min(op1,op[top]);
				top--;
			}
			op[++top]=op1;q[top]=c[i][t];
		}
	}
	cout<<ans;
}

