struct histogram_solver{
    vector<int> dp;
    vector<int> he;
    static long long solve(vector<int> values){
        stack<int> s;
        int i = 0;
        long long ans = 0;
        while(i < values.size()){
            if(s.empty() || values[s.top()] <= values[i]) s.push(i++);
            else{
                int tp = s.top(); s.pop();
                long long area = 1ll * (values[tp] + 1) * (s.empty() ? i + 1: i - s.top());
                ans = max(ans, area);
            }
        }
        while(!s.empty()){
            int tp = s.top(); s.pop();
            long long area = 1ll * (values[tp] + 1) * (s.empty() ? i + 1: i - s.top());
            ans = max(ans, area);
        }
        return ans;
    }
};
