int tryit2(char* s, const int y0, const int x0, const int hsize, const int wsize)
{
	int black_cnt=0; //奇数ならbad

	for(int y=y0;y<y0+hsize-1;y++){
		for(int x=x0;x<x0+wsize-1;x++){
			if(s[y*W_MAX+x]=='#') black_cnt++;
			if(s[(y+1)*W_MAX+x]=='#') black_cnt++;
			if(s[y*W_MAX+x+1]=='#') black_cnt++;
			if(s[(y+1)*W_MAX+x+1]=='#') black_cnt++;
			if(black_cnt%2!=0) return 0; //bad
			black_cnt = 0;
		}
	}

	return 1;
}

