const int N = 2010;

int h, w;
char board[N][N];
int g[N][N];

int L[N], R[N];

int calc(vector<int> a) {
    vector<int> st;
    for (int i = 0; i < int(a.size()); i++) {
        while (!st.empty() && a[i] <= a[st.back()]) {
            st.pop_back();
        }
        L[i] = (st.empty() ? 0 : st.back() + 1);
        st.push_back(i);
    }

    st.clear();
    for (int i = int(a.size()) - 1; i >= 0; i--) {
        while (!st.empty() && a[i] <= a[st.back()]) {
            st.pop_back();
        }
        R[i] = (st.empty() ? int(a.size()) - 1 : st.back() - 1);
        st.push_back(i);
    }

    int res = 0;
    for (int i = 0; i < int(a.size()); i++) {
        res = max(res, a[i] * (R[i] - L[i] + 2));
    }

    return res;
}

