    for (int i = 0; i < h; i++) {
        scanf("%s", board[i]);
    }
    for (int i = 0; i < h - 1; i++) {
        for (int j = 0; j < w; j++) {
            g[i][j] = (board[i][j] != board[i + 1][j]);
        }
    }

    vector<int> f(h - 1);
    int ans = w;
    for (int j = w - 1; j >= 0; j--) {
        vector<int> nf(h - 1);
        for (int i = 0; i < h - 1; i++) {
            nf[i] = 1;
