void init(){
    for (int i = 1; i < h; i++)
    for (int j = 1; j < w; j++){
        if ((s[i][j] + s[i-1][j] + s[i][j-1] + s[i-1][j-1]) % 2 == 0)
            a[i][j] = a[i-1][j] + 1;
        else
