const int maxn = 2000 + 10;
string s[maxn];
int dp[maxn][maxn], tdp[maxn][maxn];
int l[maxn], r[maxn];

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);
    int h, w; cin >> h >> w;
    for (int i = 1; i <= h; ++i) cin >> s[i], s[i] = '-' + s[i];
    if (h == 1) {
        cout << w << endl; 
        return 0;
    }
    for (int i = 1; i < h; ++i) {
        string a = s[i], b = s[i + 1];
        for (int j = 1; j <= w; ++j) {
            if (a[j] == b[j]) dp[i][j] = dp[i][j - 1] + 1;
            else dp[i][j] = 0;
        }
        string c = "-";
        for (int j = 1; j <= w; ++j) c += (b[j] == '.' ? '#' : '.');
        for (int j = 1; j <= w; ++j) {
            if (a[j] == c[j]) tdp[i][j] = tdp[i][j - 1] + 1;
            else tdp[i][j] = 0;
        }
        for (int j = 1; j <= w; ++j) dp[i][j] = max(dp[i][j], tdp[i][j]);
    } 
    int ans = 0;
    for (int j = 1; j <= w; ++j) {
        for (int i = 1; i < h; ++i) l[i] = i - 1, r[i] = i + 1;
        for (int i = 1; i < h; ++i) {
            while (l[i] > 0 && dp[l[i]][j] >= dp[i][j]) l[i] = l[l[i]];
        }
        for (int i = h - 1; i >= 1; --i) {
            while (r[i] < h && dp[r[i]][j] >= dp[i][j]) r[i] = r[r[i]];
        }
        for (int i = 1; i < h; ++i) ans = max(ans, dp[i][j] * (r[i] - l[i]));
    }
    cout << ans << endl;
    return 0;
}

