int calc(vi& h){
    int n = (int)h.size();

    vi L(n), R(n), st(n);
    int t = 0;
    rep(i, n){
        while(t > 0 and h[st[t - 1]] >= h[i]) t--;
        L[i] = t == 0 ? 0:(st[t - 1] + 1);
        st[t++] = i;
    }
    t = 0;
    rrep(i, n){
        while(t > 0 and h[st[t - 1]] >= h[i]) t--;
        R[i] = t == 0 ? n:st[t - 1];
        st[t++] = i;
    }

    int ret = 0;
    rep(i, n){
        chmax(ret, (h[i] + 1) * (R[i] - L[i] + 1));
    }

    return ret;
}

