void build(int v, int l, int r) {
	if (l == r) {
		t[v] = up[curRow][l];
		return;
	}
	int mid = (l + r) / 2;
	build(2 * v, l, mid);
	build(2 * v + 1, mid + 1, r);
	t[v] = min(t[2 * v], t[2 * v + 1]);
}

int getl(int v, int l, int r, int wl, int wr, int val) {
	if (wl > wr)
		return -1;
	if (wl == wr) {
		if (up[curRow][wl] < val)
			return wl;
		else
			return -1;
	}
	int mid = (l + r) / 2;
	int tmp = getl(2 * v + 1, mid + 1, r, max(wl, mid + 1), wr, val);
	if (tmp != -1 && up[curRow][tmp] < val)
		return tmp;
	tmp = getl(2 * v, l, mid, wl, min(mid, wr), val);
	if (tmp != -1 && up[curRow][tmp] < val) 
		return tmp;
	return -1;
}

int getr(int v, int l, int r, int wl, int wr, int val) {
	if (wl > wr)
		return m;
	if (wl == wr) {
		if (up[curRow][wl] < val)
			return wl;
		return m;
	}
	int mid = (l + r) / 2;
	int tmp = getr(2 * v, l, mid, wl, min(mid, wr), val);;
	if (tmp != m && up[curRow][tmp] < val)
		return tmp;
	tmp = getr(2 * v + 1, mid + 1, r, max(mid + 1, wl), wr, val);
	if (tmp != m && up[curRow][tmp] < val) 
		return tmp;
	return m;
}

