            dp[f][i][j] = dp[f][i][j + 1] + 1;
          } else {
            dp[f][i][j] = 0;
          }
        }
      }
    }
    int ans = 0;
    for (int j = 0; j < W; j++) {
      vector<int> widths;
      widths.push_back(W - j);
      for (int i = 1; i < H; i++) {
        widths.push_back(dp[(S[i - 1][j] ^ 1) * 2 + (S[i][j] ^ 1)][i][j]);
      }
      ans = max(ans, maxRectangleArea(widths));
    }
    cout << ans << endl;
  }
  return 0;
}

