class UnionFind{
    using vec = vector<ll>;
    public:
        vec rank;
        vec parent;
        vec size;
        ll max_size;

        UnionFind(ll N){
            rank = vec(N, 0);
            parent = vec(N);
            size = vec(N, 1);
            max_size = 1;
            iota(parent.begin(), parent.end(), 0ll);
        }

        ~UnionFind(){
        }

        ll find(ll child){
            return (child == parent[child] ? child : parent[child] = find(parent[child]));
        }

        void unit(ll x, ll y){
            ll px = find(x);
            ll py = find(y);
            if(px == py){
                return;
            }
            if(rank[px] < rank[py]){
                swap(px, py);
            }
            parent[py] = px;
            size[px] += size[py];
            chmax(max_size, size[px]);
            rank[px] += (rank[px] == rank[py]);
        }

        ll get_max_size() { return max_size; }

        bool same(ll x, ll y){
            return (find(x) == find(y));
        }

};

