using pii = pair<int, int>;

int main() {
    int h, w; cin >> h >> w;
    vector<string> s(h);
    for(int i = 0; i < h; ++i) {
        cin >> s[i];
    }

    vector<vector<int>> v(h - 1, vector<int>(w - 1));
    for(int i = 0; i < h - 1; ++i) {
        for(int j = 0; j < w - 1; ++j) {
            int p = 0;
            for(int di = 0; di <= 1; ++di) {
                for(int dj = 0; dj <= 1; ++dj) {
                    p += s[i + di][j + dj] == '#';
                }
                v[i][j] = p % 2 == 0;
            }
        }
    }
    vector<vector<int>> hist(h - 1, vector<int>(w - 1));
    for(int i = 0; i < h - 1; ++i) {
        for(int j = 0; j < w - 1; ++j) {
            if(v[i][j] == 0) continue;
            if(i != 0) hist[i][j] = hist[i - 1][j];
            hist[i][j] += 1;
        }
    }

    int ans = max(h, w);
    for(int i = 0; i < h - 1; ++i) {
        for(int lp = 0; lp < 2; ++lp) {
            stack<pii> st; st.emplace(-1, -1);
            for(int j = 0; j < w - 1; ++j) {
                while(st.top().first >= hist[i][j]) st.pop();
                ans = max(ans, (hist[i][j] + 1) * (j - st.top().second + 1));
                st.emplace(hist[i][j], j);
            }
            reverse(begin(hist[i]), end(hist[i]));
        }
    }

    cout << ans << endl;
}

