using namespace std;
int n = 0, m = 0;
char mathx[3050][3050];
bool same[3050][3050];
int up[3050][3050];
int sta[3050][2], top = 0;
signed main()
{

	scanf("%d%d", &n, &m);
	for(int i = 1; i <= n; i++) scanf("%s", mathx[i] + 1);
	for(int i = n; i >= 1; i--)
		for(int j = 1; j <= m; j++)
		{
			same[i][j] = (mathx[i][j] == mathx[i][j + 1]);
			up[i][j] = (same[i][j] != same[i + 1][j]? 1: up[i + 1][j] + 1);
		}
	int ans = max(n, m);
	for(int i = 1; i <= n; i++)
	{
		top = 0;
		for(int j = 1; j <= m; j++)
		{
			if(top > 0)
			{
				#define aol(x, a, h) (h * (x - a + 1))
				int x = 1, y = top, z = 0;
				while(x < y)
				{
					z = x + ((y - x + 1) >> 1);
					if(z == 1 || aol(j, sta[z - 1][1], sta[z - 1][0]) < aol(j, sta[z][1], sta[z][0])) x = z;
					else if(aol(j, sta[z - 1][1], sta[z - 1][0]) > aol(j, sta[z][1], sta[z][0])) y = z - 1;
					else { x = y = z; break; }
				}
				ans = max(ans, aol(j, sta[x][1], sta[x][0]));
			}
			int u = j;
			while(top > 0 && (sta[top][0] > up[i][j] || (sta[top][0] < up[i][j] && (top > 1 && (aol(j, sta[top - 1][1], sta[top - 1][0]) > aol(j, sta[top][1], sta[top][0]) && aol(j, sta[top - 1][1], sta[top - 1][0]) <= aol(j, u, up[i][j]))))))
			{ if(sta[top][0] > up[i][j]) u = sta[top][1]; top--; }
			if(!top || sta[top][0] < up[i][j])
				top++, sta[top][0] = up[i][j], sta[top][1] = u;
		}
	}
	cout << ans << endl;
	return 0;
}

