int rob(int n, int m) {
	FOR(i,0,m) {
		dp[i][n-1] = (0==ok[i][n-1]) ? 0 : 1;
		for (int j = n - 2; j>=0; --j) {
			dp[i][j] = (0==ok[i][j]) ? 0 : 1 + dp[i][j+1];
		}
	}
	int maxArea = 0;
	FOR(i,0,m) {
		FOR(j,0,n) {
			int width = dp[i][j];
			for (int k = i; k < m && width > 0; ++k) {
				width = min(width, dp[k][j]);
				maxArea = max(maxArea, (k-i+2)*(width + 1));
			}
		}
	}
	return maxArea;
}

