const int MAXN = 2000;
bitset<MAXN + 1> f[MAXN + 1];
bool g[MAXN + 1][MAXN + 1], temp[MAXN + 1][MAXN + 1];
int w, h, ans = 1, now[MAXN + 1];

void solve() {
    ans = max(w, h);
    for(int i = 2; i <= h; i++) {
        for(int j = 1; j <= w; j++)
            g[i - 1][j] = f[i - 1][j] ^ f[i][j];
    }
    for(int i = 1; i <= h - 1; i++)
        now[i] = 1;
    for(int j = 2; j <= w; j++) {
        for(int i = 1; i <= h - 1; i++) {
            if(g[i][j] != g[i][j - 1]) {
                now[i] = 1;
            } else {
                now[i]++;
            }
        }
        vector<int> cur, left(h), right(h);
        for(int i = 1; i <= h - 1; i++) {
            while(!cur.empty() && now[cur.back()] >= now[i])
                cur.pop_back();
            if(cur.empty())
                left[i] = 1;
            else
                left[i] = cur.back() + 1;
            cur.push_back(i);
        }
        cur.clear();
        for(int i = h - 1; i >= 1; i--) {
            while(!cur.empty() && now[cur.back()] >= now[i])
                cur.pop_back();
            if(cur.empty())
                right[i] = h - 1;
            else
                right[i] = cur.back() - 1;
            cur.push_back(i);
        }
        for(int i = 1; i <= h - 1; i++) {
            ans = max(ans, (right[i] - left[i] + 1 + 1) * now[i]);
        }
    }
}

