    for(int i = 1; i <= h; i++) {
        for(int j = 1; j <= w; j++)
            temp[j][i] = f[i][j];
    }
    swap(h, w);
    for(int i = 1; i <= h; i++)
        for(int j = 1; j <= w; j++)
            f[i][j] = temp[i][j];
    solve();
    cout << ans << "\n";
    return 0;
}

