long long solve() {
  long long res = max(h, w);
  for (int i = 0; i < w; ++i) {
    vector<long long> hist;
    for (int j = 1; j < h; ++j)
      hist.push_back(calc(j - 1, (s[j][i] != s[j - 1][i]) * h + j, i));
    stack<long long> len, id;
    hist.push_back(0);
    len.push(0);
    id.push(-1);
    for (int j = 0; j < h; ++j) {
      int nxtid = j;
      while (hist[j] < len.top()) {
        nxtid = id.top();
        res = max(res, len.top() * (j - id.top() + 1));
        len.pop();
        id.pop();
      }
      if (hist[j] > len.top()) {
        len.push(hist[j]);
        id.push(nxtid);
      }
    }
  }
  return res;
}

long long calc(int u, int d, int lef) {
  if (rh.calchash(u, lef, w) == rh.calchash(d, lef, w)) return w - lef;
  long long l = lef, r = w;
  while (r - l > 1) {
    long long mid = (r + l) / 2;
    if (rh.calchash(u, lef, mid) == rh.calchash(d, lef, mid))
      l = mid;
    else
      r = mid;
  }
  return l - lef;
}

