struct Rectangle {
    ll h;
    ll p;  // position from left
};
ll max_area_of_histgram(ll n, vector<ll>& height) {
    stack<Rectangle> S;
    ll maxv = 0;

    for (int i = 0; i <= n; i++) {
        Rectangle rect;
        rect.h = height[i];
        rect.p = i;

        if (S.empty()) {
            S.push(rect);
        }
        else if (S.top().h < rect.h) {
            S.push(rect);
        }
        else if (S.top().h > rect.h) {
            ll now = i;
            while ((!S.empty()) && (S.top().h >= rect.h)) {
                Rectangle pre = S.top(); S.pop();
                ll area = 1LL * pre.h * (i - pre.p);
                maxv = max(maxv, area);
                now = pre.p;
            }
            rect.p = now;
            S.push(rect);
        }
    }
    return maxv;
}

ll calc(vector<vector<char>>& S){
    ll ret = 0;
    int H = (int)S.size(), W = (int)S[0].size();
    vector<ll> height(H+1,1);
    height[H] = 0;
    ret = max_area_of_histgram(H, height);
    for(int j = W-2; j >= 0; j--){
        for(int i = 0; i < H; i++){
            if(i == 0) height[i]++;
            else{
                int cnt = 0;
                for(int k = -1; k < 1; k++) for(int l = 0; l < 2;l++) cnt += (S[i+k][j+l]=='#');
                if(cnt&1){
                    height[i] = 1;
                }else{
                    height[i]++;
                }
            }
        }
        ret = max(ret,max_area_of_histgram(H, height));
    }
    return ret;
}
void rotate(vector<vector<char>>& S){
    vector<vector<char>> T(S[0].size(),vector<char>(S.size()));
    for(int i = 0; i < S.size();i++){
        for(int j = 0; j < S[0].size();j++){
            T[S[0].size()-j-1][i] = S[i][j];
        }
    }
    S = T;
}
ll solve(){
    ll res = 0;
    int H,W; cin >> H >> W;
    vector<vector<char>> S(H,vector<char>(W));
    for(auto& vec:S) for(auto& in:vec) cin >> in;
    res = max(res,calc(S));
    rotate(S);
    res = max(res,calc(S));
    rotate(S);
    res = max(res,calc(S));
    rotate(S);
    res = max(res,calc(S));
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    cout << solve() << endl;
    return 0;
}

