		}
		t[i+1][w] = 0;
		stack<pair<int, int> > st;
		for(int j = 0; j <= w; j++){
			if(st.empty()){
				st.push({j, t[i+1][j]});
				continue;
			}
			pair<int, int> p = st.top();
			if(p.second < t[i+1][j]){
				st.push({j, t[i+1][j]});
			}else if(p.second > t[i+1][j]){
				int pos;
