			R[i] = (st2.empty() ? H - 1 : st2.top());
			st2.push(i);
		}

		for (int i = 0; i < H - 1; i++) {
			ans = max(ans, (s2[i][j] + 1) * (R[i] - L[i] + 1));
		}
	}
	cout << ans << endl;
	return 0;
}

