class FlipAndRectangles{
    int di[4] = {0, 0, 1, 1};
    int dj[4] = {0, 1, 0, 1};
    int maxRecInLine(vi H){
        // Compute the max_rectangle in one dimension.
        if(H.empty()) return 0;
        H.insert(H.begin(), -2);
        H.push_back(-1);
        int n = (int)H.size(), ans = 0;
        stack<int> stk;
        stk.push(0);
        for(int i=1;i<n;++i){
            while(H[stk.top()] >= H[i]){
                int pivat = stk.top();
                stk.pop();
                ans = max(ans, (i - stk.top()) * (H[pivat]+1));
            }
            stk.push(i);
        }
        return ans;
    }
public:
    int solution(vector<string> M){
        assert(!M.empty() && !M[0].empty());
        int n = (int)M.size(), m = (int)M[0].size();
        assert(n >= 2 && m >=2);
        int ans = max(n, m);
        // From left to right
        vi good(n-1,0);
        for(int j=0;j<m-1;++j){
            for(int i=0;i<n-1;++i){
                int cnt = 0;
                for(int k=0;k<4;++k) cnt += (M[i+di[k]][j+dj[k]]=='#');
                if(cnt%2) good[i] = 0;
                else ++good[i];
            }
            ans = max(ans, maxRecInLine(good));
        }

        return ans;
    }
};




int main(){
