///--------------------START-------------------------
int h,w;
char a[MAXN][MAXN];
int mark[MAXN][MAXN];
int b[MAXN][MAXN],c[MAXN][MAXN];
int ans;

int cal(int i,int j){
    return a[i][j]=='.';
}

int S[MAXN];
int wid[MAXN];
int top;

int solve(int i){
    int ret=0;
    top=0;
    for(int j=1;j<=w;j++){
//        int h1= (j==w+1) ? 0 : i-b[i][j]+1;
//        int h2= (j==w+1) ? 0 : i-c[i][j]+1;
        int h1=i-b[i][j]+1;
        int h2=i-c[i][j]+1;
        int Wid=0;
        if(2<=j&&j<=w) ret=max(ret,S[top]*(wid[top]+1));
        while(top>0&&h2<=S[top]){
            Wid+=wid[top];
            int x=S[top];
            top--;
            ret=max(ret,x*Wid);
        }
        ++top;
        S[top]=h2;
        wid[top]=Wid+1;
    }
    int Wid=0;
    while(top>0){
        Wid+=wid[top];
        int x=S[top];
        top--;
        ret=max(ret,x*Wid);
    }

    top=0;
    for(int j=w;j>=1;j--){
//        int h2= (j==w+1) ? 0 : i-b[i][j]+1;
//        int h1= (j==w+1) ? 0 : i-c[i][j]+1;
        int h2=i-b[i][j]+1;
        int h1=i-c[i][j]+1;
        int Wid=0;
        if(2<=j&&j<=w) ret=max(ret,S[top]*(wid[top]+1));
        while(top>0&&h2<=S[top]){
            Wid+=wid[top];
            int x=S[top];
            top--;
            ret=max(ret,x*Wid);
        }
        ++top;
        S[top]=h2;
        wid[top]=Wid+1;
    }
    Wid=0;
    while(top>0){
        Wid+=wid[top];
        int x=S[top];
        top--;
        ret=max(ret,x*Wid);
    }

    return ret;
}

void work(){
    scanf("%d%d",&h,&w);
    memset(mark,0,sizeof(mark));
    memset(b,0,sizeof(b));
    memset(c,0,sizeof(c));
    for(int i=1;i<=h;i++) scanf("%s",a[i]+1);
    for(int i=1;i<h;i++){
        for(int j=1;j<w;j++){
            int x=cal(i,j)+cal(i,j+1)+cal(i+1,j)+cal(i+1,j+1);
            if(x%2==1) mark[i][j]=1;
            else mark[i][j]=0;
        }
    }
//    for(int i=1;i<h;i++){
//        for(int j=1;j<w;j++){
//            printf("%d ",mark[i][j]);
//        }
//        printf("\n");
//    }
    for(int i=1;i<=h;i++){
        for(int j=1;j<=w;j++){
            if(i==1) b[i][j]=1;
            else if(j==1) b[i][j]=1;
            else if(mark[i-1][j-1]) b[i][j]=i;
            else b[i][j]=b[i-1][j];

            if(i==1) c[i][j]=1;
            else if(j==w) c[i][j]=1;
            else if(mark[i-1][j]) c[i][j]=i;
            else c[i][j]=c[i-1][j];
        }
    }
//    for(int i=1;i<=h;i++){
//        for(int j=2;j<=w;j++)if(b[i][j]!=c[i][j-1]) exit(1);
//    }
    ans=max(h,w);
    for(int i=1;i<=h;i++){
        ans=max(ans,solve(i));
    }
    printf("%d\n",ans);
}

///--------------------END-------------------------
