inline pair<int, int> solve(int val, vector<int> dat, int sz) {
    int l = 0, r = sz;  // dat[l] < val
    while (r - l > 1) {
        int mid = (r + l) / 2;
        if (dat[mid] < val)
            l = mid;
        else
            r = mid;
    }
    return {val - dat[l], dat[r] - val};
}

