unsigned long long dfs(int r, int c, bool flag)
{
	if (c >= n)
		return 1;
	if (c == 0 && r == 0 && input[0][0] == input[1][0])
		return 3 * dfs(0, 1, false) % MOD7;
	else if (c == 0 && r == 0 && input[0][0] == input[0][1])
		return 3 * dfs(1, 0, false) % MOD7;
	else if (c == 0 && r == 1)
		return 2 * dfs(0, 2, false) % MOD7;
	else
	{
		if (r == 0 && input[0][c] == input[1][c])
		{
			if (input[0][c - 1] == input[1][c - 1])
				return 2 * dfs(0, c + 1, false) % MOD7;
			else
				return 1 * dfs(0, c + 1, false) % MOD7;
		}
		else if (r == 0)
			return 2 * dfs(1, c, false) % MOD7 + dfs(1, c, true) % MOD7;
		else
		{
			if (flag)
				return 2 * dfs(0, c + 2, false) % MOD7;
			else
				return dfs(0, c + 2, false) % MOD7;
		}
	}
}

