		str3[0][j] = '#';
	}

	REP(i, 0, H) {
		REPM(j, W - 1, 0) {
			if (str[i][j] == str[i][j + 1]) {
				str2[i][j] = '.';
			} else {
				str2[i][j] = '#';
			}
		}
	}

	REP(i, 0, H) {
		REP(j, 0, W) {
			if (str3[i][j] == '#') {
				v[i].push_back(j);
			}
		}
	}

	//REP(i, 0, H) {
	//	cout << str3[i] << endl;
	//}


	REP(i, 0, H) {
		REP(j, 0, W) {
			if (str3[i][j] == '.') continue;
			int right = W - 1;

			REP(k, i + 1, H) {
				auto it = lower_bound(v[k].begin(), v[k].end(), j + 1);
				if (it != v[k].end() && *it < right) {
					right = *it - 1;
				}
				if (j == right) {
					Register(H - i);
					break;
				}
				Register((k - i + 1) * (right - j + 1));
			}
		}
	}
	cout << MAX << endl;
	return 0;
}

