struct achist{
  int id;
  int height;
};


struct loc2d{
  int x;
  int y;
};

bool comp_loc2d(const loc2d &l1, const loc2d &l2){
  if(l1.x == l2.x){
    return l1.y < l2.y;
  }
  return l1.x < l2.x;
}


int main(){
  int H, W;

  cin >> H >> W;
  string data[H];
  vector<loc2d> badlocs;

  for(int i=0;i<H;++i){
    cin >> data[i];
  }

  for(int i=0;i<H-1;++i){
    for(int j=0;j<W-1;++j){
      int cnt = 0;
      if(data[i][j]=='.'){
	cnt++;
      }
      if(data[i+1][j]=='.'){
	cnt++;
      }
      if(data[i][j+1]=='.'){
	cnt++;
      }
      if(data[i+1][j+1]=='.'){
	cnt++;
      }
      if(cnt == 1 || cnt ==3){
	loc2d l;
	l.y = i; l.x = j;
	badlocs.push_back(l);
      }
    }
  }

  sort(badlocs.begin(), badlocs.end(), comp_loc2d);
  for(int i=0;i<badlocs.size();++i){
    //cout<<badlocs[i].x<<","<<badlocs[i].y<<endl;
  }

  // 最大長方形アルゴリズムの準備
  // http://algorithms.blog55.fc2.com/blog-entry-133.html
  int hists[H-1][W-1];

  for(int j=0;j<W-1;++j){
    int seq = 0;
    for(int i=0;i<H-1;++i){
      loc2d l;
      l.x = j;
      l.y = i;
      bool block = binary_search(badlocs.begin(),badlocs.end(),l,comp_loc2d);
      if(block){
	//cout<<"b"<<j<<","<<i<<endl;
	hists[i][j]=0;
	for(int l=0;l<seq;++l){
	  hists[i-1-l][j] = l+1;
	}
	seq = 0;
      }else{
	seq++;
	if(i == H-2){
	  for(int l=0;l<seq;++l){
	    hists[i-l][j] = l+1;
	  }
	}
      }
    }
  }
  for(int i=0;i<H-1;++i){
    for(int j=0;j<W-1;++j){
      //cout<<hists[i][j]<<",";
    }
    //cout<<endl;
  }

  // ヒストグラムの最大を取る
  stack<achist> acs;
  int maxv = -1;
  for(int i=0;i<H-1;++i){
    for(int j=0;j<W;++j){
      achist ac;
      if(j!=W-1){
	ac.id = j;
	ac.height = hists[i][j];
      }else{
	ac.id = W-1;
	ac.height = 0;
      }
      if(acs.empty()){
	acs.push(ac);
      }else{
	if(acs.top().height < ac.height){
	  acs.push(ac);
	}else if(acs.top().height > ac.height){
	  while(!acs.empty() && acs.top().height >= ac.height){
	    const int v = (ac.id - acs.top().id+1) * (acs.top().height+1);
	    maxv = max(maxv,v);
	    acs.pop();
	  }
	}
      }
    }
  }
  cout<<maxv<<endl;
  return 0;
}

