int solve(int n) {
	vector<int> q;
	q.push_back(0);
	b[0] = b[n + 1] = 0;
	for (int i = 1; i <= n; ++ i) {
		while (b[q.back()] >= b[i]) q.pop_back();
		L[i] = q.back();
		q.push_back(i);
	}
	q.clear();
	q.push_back(n + 1);
	for (int i = n; i >= 1; -- i) {
		while (b[q.back()] >= b[i]) q.pop_back();
		R[i] = q.back();
		q.push_back(i);
	}
	int ans = 0;
	for (int i = 1; i <= n; ++ i) ans = max(ans, b[i] * (R[i] - L[i]));
	return ans;
}
