int H, W, L[2009], R[2009], st[2009], col[2009][2009], dp[2009][2009]; string s[2009];
int calc(vector<int> v) {
	int n = v.size(), t = 0;
	for (int i = 0; i < n; i++) {
		if (t > 0 && v[st[t - 1]] >= v[i]) t--;
		L[i] = (t == 0 ? 0 : st[t - 1] + 1);
		st[t++] = i;
	}
	for (int i = n - 1; i >= 0; i--) {
		while (t > 0 && v[st[t - 1]] >= v[i]) t--;
		R[i] = (t == 0 ? n : st[t - 1]);
		st[t++] = i;
	}
	int ret = 0;
	for (int i = 0; i < n; i++) ret = max(ret, v[i] * (R[i] - L[i] + 1));
	return ret;
}
int solve() {
	int ret = min(H, W);
	for (int i = 0; i < H - 1; i++) {
		stack<int> st;
		for (int j = 0; j < W - 1; j++) {
			if (col[i][j] == 0) dp[i][j] = (i == 0 ? 2 : dp[i - 1][j] + 1);
			else dp[i][j] = 1;
		}
		vector<int> v(dp[i], dp[i] + W - 1);
		ret = max(ret, calc(v));
	}
	return ret;
}
