			if (col[i][j] != col[i + 1][j]) col[i][j] = 1;
			else col[i][j] = 0;
		}
	}
	int ret = solve();
	for (int i = 0; i < H - 1; i++) {
		for (int j = 0; j < W - 1; j++) {
