using namespace std;

struct Node {
    int h, v, ind;
    bool vis;
} a[200010];

struct Edge {
    int to, nex;
} e[2000010];

int n, ans, cnt = 0, no = 0;
string xs, nm, fa, tmp;
unordered_map<string, int> id;

void addedge(int u, int v) {
    e[++cnt] = (Edge){v, a[u].h};
    a[u].h = cnt;
    ++a[v].ind;
}

void topo() {
    queue<int > q;
    for(int i = 1; i <= no; ++i)
        if(!a[i].ind) q.push(i);
    while(!q.empty()) {
        int u = q.front();
        a[u].vis = 1;
        q.pop();
        for(int i = a[u].h; i; i = e[i].nex) {
            int v = e[i].to;
            --a[v].ind;
            a[v].v = max(a[v].v, a[u].v + 1);
            ans = max(ans, a[v].v);
            if(!a[v].ind) q.push(v);
        }
    }
}

void dfs(int u, int &val, int &dep) {
    a[u].vis = 1;
    val = max(val, a[u].v);
    ++dep;
    for(int i = a[u].h; i; i = e[i].nex)
        if(!a[e[i].to].vis)
            dfs(e[i].to, val, dep);
}

int main() {
