        if(!id[nm]) id[nm] = ++no;
        if(!id[fa]) id[fa] = ++no;
        addedge(id[nm], id[fa]);
    } topo();
    for(int i = 1; i <= no; ++i)
        if(!a[i].vis) {
            int val = 0, dep = 0;
            dfs(i, val, dep);
            ans = max(ans, val + dep);
        }
    cout << ans;
    return 0;
}

