using namespace std;
int32_t main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	int w, h;
	cin >> w >> h;
	char matrix[w][h];
	int del[w+1];
    for (int i=0; i < w; i++){
		for (int j=0; j < h; j++){
			cin >> matrix[i][j];
		}
    }
    vector<set<int> > p;
    for (int i=0; i <= w; i++){
		set<int> ms;
		p.push_back(ms);
    }
    for (int i=1; i < w; i++){
        for (int j=1; j < h; j++){
			int summ = 0;
			if (matrix[i-1][j-1] == '#') summ++;
			if (matrix[i-1][j] == '#') summ++;
			if (matrix[i][j-1] == '#') summ++;
			if (matrix[i][j] == '#') summ++;
			if (summ % 2 != 0){
                p[i].insert(j);
			}
        }
    }
    int ans = 0;
    for (int start = 0; start < h; start++){
		for (int j=0; j <= w; j++){
			del[j] = 0;
		}
        vector<pair<int, int> > np;
        for (int j=0; j <= w; j++){
			if (p[j].size() == 0) continue;
			set<int>::iterator it = p[j].upper_bound(start);
			if (it == p[j].end()) continue;
			int num = *it;
			np.push_back(make_pair(num, j));
        }
        sort(np.begin(), np.end());
        set<int> pp;
        pp.insert(0);
        pp.insert(w);
        priority_queue<int> dist;
        dist.push(w);
        int u = 0;
        for (int next=start+1; next <= h; next++){
            while (u < np.size() && np[u].first < next){
                int str = np[u].second;
                u++;
                set<int>::iterator ii = pp.upper_bound(str);
                set<int>::iterator i1 = ii;
                i1--;
                int v1 = *i1;
                int v2 = *ii;
                del[v2-v1]++;
                int n1 = str - v1;
                int n2 = v2 - str;
                dist.push(n1);
                dist.push(n2);
                pp.insert(str);
            }
            int aa;
            while (true){
				int el = dist.top();
				if (del[el] > 0){
					del[el]--;
					dist.pop();
				}
				else{
                    aa = el;
                    break;
				}
            }
            ans = max(ans, aa * (next - start));
        }
    }
    cout << ans << endl;
    return 0;
}

