		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j + 1 < W; j++) {
			d[i][j] = b[i][j] ^ b[i][j + 1];
		}
	}
	int ans = 0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j + 1 < W; j++) {
			if (i == 0 || d[i][j] == d[i - 1][j]) cnt[j]++;
			else cnt[j] = 1;
		}
		stack<int> S;
		for (int j = 0; j + 1 < W; j++) {
			while (!S.empty() && cnt[S.top()] >= cnt[j]) S.pop();
			if (S.empty()) L[j] = 0;
			else L[j] = S.top() + 1;
			S.push(j);
		}
		while (!S.empty()) S.pop();
		for (int j = W - 2; j >= 0; j--) {
			while (!S.empty() && cnt[S.top()] >= cnt[j]) S.pop();
			if (S.empty()) R[j] = W - 1;
			else R[j] = S.top();
			S.push(j);
		}
		for (int j = 0; j + 1 < W; j++) {
			ans = max(ans, cnt[j] * (R[j] - L[j] + 1));
		}
