class UnionFind{
public:
    int n;
    vector<int> u;
    UnionFind(int _n = 0){
        n = _n;
        u = vector<int>(n, -1);
    }
    int r(int x){
        if(u[x] < 0)return x;
        return u[x] = r(u[x]);
    }
    void unite(int x, int y){
        x = r(x);
        y = r(y);
        if(x == y)return;
        if(-u[x] < -u[y])swap(x,y);
        u[x] += u[y];
        u[y] = x;
    }
    int size(int x){
        return -u[r(x)];
    }
};


int main(){
    cin >> n >> m;
    for(int i = 0;i < n;i++)cin >> str[i];
    for(int i = 0;i < n-1;i++){
        for(int j = 0;j < m-1;j++){
            int cnt = (str[i][j] == '#')
                + (str[i+1][j] == '#')
                + (str[i][j+1] == '#')
                + (str[i+1][j+1] == '#');
            if(cnt % 2){
                col[j].push_back(i);
            }
        }
    }

    int ans = 0;

    for(int i = 0;i < n;i++){
        UnionFind uf(m);
        vector<int> walls = {0};
        int last = 0;
        int longest = 1;
        for(int j = 0;j < m;j++){
            auto it = lower_bound(col[j].begin(), col[j].end(), i);
            if(it != col[j].end()){
                ng[*it].push_back(j);                
                while(last <= j){
                    if(last != j){
                        uf.unite(last, last + 1);
                        longest = max(longest, uf.size(last));
                    }
                    last++;
                }         
            }
        }
        while(last <= m-1){
            if(last != m-1){
                uf.unite(last, last + 1);
                longest = max(longest, uf.size(last));
            }
            last++;
        }

        for(int j = n-1;j >= i;j--){
            int h = j - i + 1;
            ans = max(ans, h * longest);
            if(j == i)break;
            for(auto p: ng[j-1]){
                uf.unite(p, p+1);
                longest = max(longest, uf.size(p));
            }
            ng[j-1].clear();
        }
    }

    cout << ans << endl;

    return 0;
}

