const int DIM = 2e3 + 5;

char mat[DIM][DIM]; int c[DIM][DIM];
int equ[DIM][DIM], dif[DIM][DIM];
int lef[DIM], rig[DIM], arr[DIM];

vector<int> stk;

inline void solve(int i, int n, int m, int &ans) {
    for (int j = 1; j < m; ++j) {
        if (mat[i][j] == mat[i][j + 1])
            arr[j] = dif[i - 1][j];
        else
            arr[j] = equ[i - 1][j];
    }

    stk.assign(1, 0);
    for (int j = 1; j < m; ++j) {
        while (arr[stk.back()] >= arr[j])
            stk.pop_back();

        lef[j] = stk.back() + 1;
        stk.push_back(j);
    }

    stk.assign(1, m);
    for (int j = m - 1; j > 0; --j) {
        while (arr[stk.back()] >= arr[j])
            stk.pop_back();

        rig[j] = stk.back() - 1;
        stk.push_back(j);
    }

    for (int j = 1; j < m; ++j)
        ans = max(ans, (rig[j] - lef[j] + 2) * (arr[j] + 1));

    return;
}

inline void solve(int n, int m, int &ans) {
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j < m; ++j) {
            equ[i][j] = equ[i - 1][j] + 1;
            dif[i][j] = dif[i - 1][j] + 1;

            if (mat[i][j] != mat[i][j + 1])
                dif[i][j] = 0;
            else
                equ[i][j] = 0;
        }
    }

    arr[0] = arr[m] = -1;

    for (int i = 2; i <= n; ++i) {
        solve(i, n, m, ans);
        for (int j = 1; j <= m; ++j)
            mat[i][j] = 1 - mat[i][j];

        solve(i, n, m, ans);
        for (int j = 1; j <= m; ++j)
            mat[i][j] = 1 - mat[i][j];
    }

    return;
}

int main( void ) {

    int n, m;
    cin >> n >> m;

    int ans = max(n, m);

    for (int i = 1; i <= n; ++i) {
        cin >> (mat[i] + 1);

        for (int j = 1; j <= m; ++j)
            mat[i][j] = (mat[i][j] == '#' ? 1 : 0);
    }

    for (int i = 0; i <= 3; ++i) {
        solve(n, m, ans);

        for (int i = 1; i <= n; ++i)
            for (int j = 1; j <= m; ++j)
                c[j][n - i + 1] = mat[i][j];

        swap(n, m);
        for (int i = 1; i <= n; ++i)
            for (int j = 1; j <= m; ++j)
                mat[i][j] = c[i][j];
    }

    cout << ans;
    return 0;
}

