	ll H,W; cin >> H >> W;
	string S1,S2;
	cin >> S1;
	V<V<ll>> flg(H,V<ll>(W,0)),cnt(H,V<ll>(W+1,0));	
	for(int i = 0; i < H - 1; ++i){
		cin >> S2;
		for(int j = 0; j < W - 1; ++j){
			int a = (S1[j] == '#');
			int b = (S1[j + 1] == '#');
			int c = (S2[j] == '#');
			int d = (S2[j + 1] == '#');
			int tmp = a+b+c+d;
			if(tmp == 1 || tmp == 3) flg[i][j] = 1;			
		}
		S1 = S2;
	}

	for(int j = 0; j < W; ++j){
		if(!flg[0][j]) cnt[0][j] = 1;
		for(int i = 1; i < H; ++i){
			if(flg[i][j]) continue;
			cnt[i][j] = cnt[i-1][j] + 1;
		}
	}
	ll ans = max(H,W);
	for(int i = 1; i < H; ++i){
		stack<pair<long long,long long>> st;
		st.push({cnt[i-1][0]+1,0});
		for(ll j = 1; j <= W; ++j){

			ll vj = cnt[i-1][j]+1;
			if(st.empty()){
				st.push({vj,j});
				continue;
			}

			ll vk = st.top().first, k = st.top().second;

			if(vk < vj) st.push({vj,j});
			if(vk < vj || vk == vj)	continue;

			while(1){
				chmax(ans,vk*(j - k + (j!=W?1:0)));
				st.pop();
				if(st.size() && st.top().first > vj) vk = st.top().first, k = st.top().second;
				else break;
			}
			st.push({vj,j});
		}
	}
	//for(int i = 0; i < H; ++i) print(i,cnt[i]);
	cout << ans << endl;

	return 0;
}

