int getMaxRectangleInHistgram(const std::vector<int>& v) {
	int w = v.size();
	std::stack<int> st;
	std::vector<int> L(w), R(w);
	REP(i, w) {
		while (!st.empty() && v[st.top()] >= v[i]) st.pop();
		L[i] = st.empty() ? 0 : (st.top() + 1);
		st.push(i);
	}
	st = std::stack<int>();
	RREP(i, w) {
		while (!st.empty() && v[st.top()] >= v[i]) st.pop();
		R[i] = st.empty() ? w : st.top();
		st.push(i);
	}
