int getLargestRectangle(vector<int>& hight) {
    int w = hight.size(),res = 0;
    stack<P> st;
    for (int i = 0;i < w;++i) {
        if (st.empty()) {
            if (hight[i]) st.push(P(hight[i],i));
        } else {
            int t = st.top().first;
            if (t < hight[i]) st.push(P(hight[i],i));
            else if (t > hight[i]) {
                int l = i;
                while (!st.empty() && hight[i] < st.top().first) {
                    P p = st.top();
                    l = p.second;
                    res = max(res,(p.first+1)*(i-l+1));
                    st.pop();
                }
                if (st.empty() || st.top().first < hight[i]) st.push(P(hight[i],l));
            }
        }
    }
    return res;
}

