void solve()
{
    scanf("%d%d", &n, &m);
    int ans = max(n, m);
    for(int i = 0; i < n; ++ i) {
        scanf("%s", a[i]);
        for(int j = 0; j < m; ++ j) {
            a[i][j] = (a[i][j] == '#');
        }
