////////////辅助函数////////////
inline bool check(int x, int y) {
  return (org[x-1][y-1]^org[x-1][y]^org[x][y-1]^org[x][y]);
}

////////////主要函数////////////
void init() {
  scanf("%d%d", &H, &W);
  for (int i=0; i<H; i++) 
    for (int j=0; j<W; j++) {
      int ch = getchar();
      while (ch!='#' && ch!='.') ch = getchar();
      org[i][j] = (ch == '#' ? 1 : 0);
    }
  for (int i=1; i<H; i++)
    for (int j=1; j<W; j++)
      if (check(i, j)) mat[i][j] = 1;
}

void solve() {
  int ans = 0;
  for (int j=0; j<=W; j++) up[j]=0, left[j]=0, right[j]=W;
  for (int i=1; i<=H; i++) {
    int lo = 0, ro = W;
    for (int j=0; j<=W; j++) 
      if (mat[i-1][j]) up[j]=1, left[j]=0, lo=j;
      else {
	up[j] = up[j] + 1;
	left[j] = max(left[j], lo);
      }
    for (int j=W; j>=0; j--) {
      if (mat[i-1][j]) right[j] = W, ro = j;
      else right[j] = min(right[j], ro);
      ans = max(ans, up[j] * (right[j] - left[j]));      
    }
  }
  printf("%d\n", ans);
}

int main() {
  init();
  solve();
  return 0;
}

