using namespace std;

int LargestRectangle(vector< int > height)
{
  stack< int > st;
  height.push_back(0);
  vector< int > left(height.size());
  int ret = 0;
  for(int i = 0; i < height.size(); i++) {
    while(!st.empty() && height[st.top()] >= height[i]) {
      ret = max(ret, (i - left[st.top()]) * height[st.top()]);
      st.pop();
    }
    left[i] = st.empty() ? -1 : st.top();
    st.emplace(i);
  }
  return (ret);
}

