using namespace std;

long long max_rectangle_in_histogram(const vector<int> &height) {
    const unsigned int N = height.size();

    // L
    vector<int> L(N);
    {
        int t = 0; // スタックのサイズ
        int st[N];
        for (int i = 0; i < N; ++i) {
            while (t > 0 and height[st[t - 1]] >= height[i]) {
                t--;
            }
            L[i] = (t == 0 ? 0 : (st[t - 1] + 1));
            st[t++] = i;
        }
    }

    // R
    vector<int> R(N);
    {
        int t = 0;
        int st[N];
        for (int i = N - 1; i >= 0; i--) {
            while (t > 0 and height[st[t - 1]] >= height[i]) {
                t--;
            }
            R[i] = (t == 0 ? N : st[t - 1]);
            st[t++] = i;
        }
    }

    long long ans = 0;
    for (int i = 0; i < N; i++) {
//        ans = max(ans, (long long)height[i] * (R[i] - L[i]));
        ans = max(ans, (long long)(1 + height[i]) * (1 + (R[i] - L[i])));
    }

    return ans;
}

long long max_rectangle(const vector<vector<int>> &field) {
    const int space = 1;    // 塗れるマス

    const unsigned int H = field.size();
    const unsigned int W = field[0].size();

    long long ans = 0;
    vector<int> line(W, 0); // ある行について上にいくつスペースがあるか
    for (int y = 0; y < H; ++y) {
        for (int x = 0; x < W; ++x) {
            if (field[y][x] != space) {
                line[x] = 0;
            }
            else {
                line[x]++;
            }
        }
        ans = max(ans, max_rectangle_in_histogram(line));
    }
    return ans;
}


int main() {
