i64 histgram(int n, const vector<int> &h) {
    vector<int> L(n), R(n);

    stack<int> s;
    for (int i = 0; i < n; ++i) {
        while (!s.empty() && h[s.top()] >= h[i]) {
            s.pop();
        }

        L[i] = s.empty() ? 0 : (s.top() + 1);
        s.push(i);
    }

    s = stack<int>();
    for (int i = n - 1; i >= 0; i--) {
        while (!s.empty() && h[s.top()] >= h[i]) {
            s.pop();
        }

        R[i] = s.empty() ? n : s.top();
        s.push(i);
    }

    i64 res = 0;
    for (int i = 0; i < n; ++i) {
        res = max(res, (i64)h[i] * (R[i] - L[i]));
    }

    return res;
}

i64 solve(int h, int w, const vector<string> &s) {
    auto a = make_vector<int, 2>(h, w);
    for (int i : rep(0, h)) {
        a[i][0] = 0;
        for (int j : rep(1, w)) {
            a[i][j] = s[i][j - 1] != s[i][j];
        }
    }

    auto b = make_vector<int, 2>(h, w);

    for (int j : rep(0, w)) {
        b[0][j] = 1;
        for (int i : rep(1, h)) {
            if (a[i - 1][j] == a[i][j]) {
                b[i][j] = b[i - 1][j] + 1;
            } else {
                b[i][j] = 1;
            }
        }
    }

    i64 ans = 0;

    for (int i : rep(0, h)) {
        ans = max(ans, histgram(w, b[i]));
    }

    return ans;
}

int main() {
    int h, w;
    in(h, w);

    auto t = vin<string>(h);

    i64 ans = solve(h, w, t);

    auto s = vector<string>(w, string(h, 'a'));

    for (int i : rep(0, h)) {
        for (int j : rep(0, w)) {
            s[j][i] = t[i][j];
        }
    }

    ans = max(ans, solve(w, h, s));

    out(ans);
}

