int B[2010][2010];
int L[2010], R[2010];

int find_rect(int D[2010]) {
	stack<int> S;
	rep(i, 0, M) {
		while(!S.empty() && D[S.top()] >= D[i]) S.pop();
		L[i] = S.empty() ? 0 : S.top() + 1;
		S.push(i);
	}
	rer(i, M, 0) {
		while(!S.empty() && D[S.top()] >= D[i]) S.pop();
		R[i] = S.empty() ? M : S.top();
		S.push(i);
	}
	int res = 0;
	rep(i, 0, M) {
		MAX(res, (D[i] + 1) * (R[i] - L[i] + 1));
	}
	return res;
}

