    for (int i = 0; i < H; ++i)
        cin >> S[i];

    for (int i = 0; i < H - 1; ++i) {
        string r0 = S[i];
        string r1 = S[i + 1];
        int p = (r0[0] == r1[0]);
        pt[i][0] = 1;
        int c = 1;
        for (int j = 1; j < W; ++j) {
            if (p == (r0[j] == r1[j])) {
                c += 1;
            } else {
                p = !p;
                c = 1;
            }
            pt[i][j] = c;
        }
    }


    int max_area = (H < W) ? W : H;

    for (int j = 0; j < W; ++j) {
        st[0] = 0;
        int lw = pt[0][j];
        int stp = 0;
        for (int i = 1; i < H - 1; ++i) {
            int w = pt[i][j];
            if (lw < w) {
                st[++stp] = i;
            } else if (w < lw) {
                int lo = 0;
                int hi = stp;
                if (w < pt[st[0]][j]) {
                    lo = -1;
                } else {
                    while (lo + 1 < hi) {
                        int mid = (lo + hi) / 2;
                        int mw = pt[st[mid]][j];
                        if (mw <= w) {
                            lo = mid;
                        } else {
                            hi = mid;
                        }
                    }
                }
                while (lo < stp) {
                    int i0 = st[stp--];
                    int area = pt[i0][j] * (i - (stp < 0 ? 0 : i0) + 1);
                    max_area = (max_area < area) ? area : max_area;
                }
                if (stp < 0 || pt[st[stp]][j] < w) {
                    st[++stp] = i;
                }
            }
            lw = w;
        }
        while (0 <= stp) {
            int i0 = st[stp--];
            int area = pt[i0][j] * (H - (stp < 0 ? 0 : i0));
            max_area = (max_area < area) ? area : max_area;
        }
    }

    cout << max_area << endl;
    return 0;
}

