int solve(vector<int> v) {
    int n = v.size();

    vector<int> st(n, -1), dr(n, n);

    vector<int> s;

    for(int i = 0; i < n; ++i) {
        while(not s.empty() and v[i] < v[s.back()]) {
            dr[s.back()] = i;
            s.pop_back();
        }
        s.push_back(i);
    }

    s.clear();

    for(int i = n - 1; i >= 0; --i) {
        while(not s.empty() and v[i] < v[s.back()]) {
            st[s.back()] = i;
            s.pop_back();
        }
        s.push_back(i);
    }

    int ans = 0;

    for(int i = 0; i < n; ++i) {
        ans = max(ans, v[i] * (dr[i] - (st[i] + 1) + 1));
    }

    return ans;
}

