    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < m - 1; ++j) {
            if(a[i][j] == a[i][j + 1]) {
                dp[i][j] = 1;
                dp_flip[i][j] = 0;
                if(i - 1 >= 0) {
                    dp[i][j] += dp[i - 1][j];
                }
            } else {
                dp[i][j] = 0;
                dp_flip[i][j] = 1;
                if(i - 1 >= 0) {
                    dp_flip[i][j] += dp_flip[i - 1][j];
                }
            }
        }
    }

    for(int i = 0; i < n; ++i)
        for(int j = 0; j < m; ++j)
            dp[i][j] = max(dp[i][j], dp_flip[i][j]);

    int ans = 0;

    for(int i = 0; i < n; ++i) {
        int run = 0;
        for(int j = 0; j < m; ++j) {
            if(j - 1 < 0 or (j - 1 >= 0 and a[i][j] == a[i][j - 1])) {
                run += 1;
                ans = max(ans, run);
            } else {
                run = 0;
            }
