int hoge(bitset<2020> S,int W) {
	bitset<2020> T;
	if(S[0]==1) S^=R[W];

	if(S.count()==0) return W;
	int ret=0;
	for(;ret+64<W;ret+=64) {
		T=S>>64;
		if(T.count()==0) break;
		S=T;
	}
	int i;
	FOR(i,64) if(S[i]) return ret+i;
	assert(0);

}

