bool normal(vector<vector<bool>> v) {
	int _id = id(v);
	if (v[0][0] + v[0][1] + v[1][0] + v[1][1] == 4) {
		return _can[_id] = true;
	}
	if (_can[_id] == -1) {
		_can[_id] = -2;
		bool kekus = false;
		for (auto sub : get_vars(v)) {
			if (_can[id(sub)] == -2) continue;
			if (_can[id(sub)] == -1) {
				normal(sub);
			}
			if (_can[id(sub)]) {
				kekus = true;
				break;
			}
		}
		_can[_id] = kekus;
	}
	return _can[_id];
}


