            if(s[i][j]=='#'){
                cnt++;
            }
            if(s[i][j-1]=='#'){
                cnt++;
            }
            if(s[i-1][j]=='#'){
                cnt++;
            }
            if(s[i-1][j-1]=='#'){
                cnt++;
            }
            if(cnt%2){
                f[i][j]=1;
            }
        }
    }
    for(int i=0;i<h;i++){
        dp[i][0]=i+1;
    }
    for(int i=0;i<w;i++){
        dp[0][i]=1;
    }
    for(int i=1;i<h;i++){
        for(int j=1;j<w;j++){
            if(f[i][j]){
                dp[i][j]=1;
            }
            else{
                dp[i][j]=dp[i-1][j]+1;
            }
        }
    }
    ans=max(h,w);
