        }
        while(!st.empty()){
            st.pop();
        }
        st.push(make_pair(w-1,dp[i][w-1]));
        for(int j=w-2;j>=0;j--){
            while(!st.empty()&&st.top().second>=dp[i][j]){
                st.pop();
            }
            if(st.empty()){
                r[i][j]=w-1;
            }
            else{
                r[i][j]=st.top().first-1;
            }
            st.push(make_pair(j,dp[i][j]));
        }
        for(int j=0;j<w;j++){
            ans=max(ans,dp[i][j]*(r[i][j]-l[i][j]+1));
        }
    }
    printf("%d\n",ans);
