// ヒストグラム内最大長方形

int solve(vector<int> vec) {
  stack<int> st;
  int n = vec.size();
  vector<int> L(n), R(n);
  for(int i = 0; i < n; i++) {
    int h = vec[i];
    if(st.size() && vec[st.top()] > h) st.pop();
    if(st.empty() || h != vec[st.top()]) st.push(i);
    L[i] = st.top();
  }
  while(st.size()) st.pop(); /// ///
  for(int i = n-1; i >= 0; i--) {
    int h = vec[i];
    if(st.size() && vec[st.top()] > h) st.pop();
    if(st.empty() || h != vec[st.top()]) st.push(i);
    R[i] = st.top();
  }
  int res = 0;
  for(int i = 0; i < n; i++) {
    res = max(res, vec[i] * (R[i] - L[i] + 1));
  }
  return res;
}

