    vector<string> s(h);
    for(int i=0;i<h;i++) cin>>s[i];

    ll res = max(h,w);
    vector<vector<int>> b(h-1,vector<int>(w-1));
    for(int i=0;i+1<h;i++){
        for(int j=0;j+1<w;j++){
            int cnt = s[i][j]=='#' ^ s[i+1][j]=='#' ^ s[i][j+1]=='#' ^ s[i+1][j+1]=='#';
            b[i][j] = (int)(!cnt);
        }  
    }

    vector<vector<ll>> sum(h,vector<ll>(w));
    for(int i=0;i<h-1;i++){
        for(int j=0;j<w-1;j++){
            if(b[i][j]) sum[i+1][j] = sum[i][j]+1;
        }
    }

    for(int i=0;i<h-1;i++){
        int x = i+1;
        stack<pair<int,ll>> lh;
        lh.push({-1,0});
        for(int y=0;y<w;y++){
            while(sum[x][y]<lh.top().second){
                auto tmp = lh.top(); lh.pop();
                ll height = tmp.second;
                ll width = y-tmp.first;
                res = max(ll(res),(width+1)*(height+1));
            }
            if(lh.top().second<sum[x][y]) lh.push({y,sum[x][y]});
        }
    }
    cout<<res<<endl;

    return 0;
}

