        cnts['#'] = cnts['.'] = 0;
        cnts[grid[hh][ww]]++;
        cnts[grid[hh][ww+1]]++;
        cnts[grid[hh+1][ww]]++;
        cnts[grid[hh+1][ww+1]]++;
        if (abs(cnts['#'] - cnts['.']) == 2) qh[ww+1].push(hh+1);
    }
    rep (ww, 2003) qh[ww].push(h);

    debug_printf("--- ans init\n");
    ll ans = max(h, w);

    rep (sh, h) {
        srep (ww, 1, w+1) while (qh[ww].front() <= sh) qh[ww].pop();

        priority_queue_incr<t2> qhw;
        srep (ww, 1, w+1) {
            ll hh = qh[ww].front();
            qhw.push(t2(hh, ww));
        }

        set<ll> borders;
        priority_queue<ll> lenq;
        S ll removed_lencnt[2003];
        memset(removed_lencnt, 0, sizeof(removed_lencnt));

        borders.insert(0);
        borders.insert(w);
        lenq.push(w);

        srep (eh, sh, h) {
            while (!qhw.empty()) {
                auto item = qhw.top();
                ll hh = get<0>(item);
                ll ww = get<1>(item);

                if (hh > eh) break;
                qhw.pop();

                auto left = borders.lower_bound(ww);
                auto right = left;
                left--;

                lenq.push(ww - *left);
                lenq.push(*right - ww);
                removed_lencnt[*right-*left]++;
                borders.insert(ww);
            }

            for ( ; ; ) {
                ll len = lenq.top();
                if (removed_lencnt[len]) {
                    removed_lencnt[len]--;
                    lenq.pop();
                    continue;
                }

                ans = max(ans, (eh - sh + 1LL) * len);
                break;
            }
        }
    }

    debug_printf("---- ans\n");
    cout << ans << endl;
}

