            a[i][j] = s[j] == '#';
        }
    }
    for (int i = 1; i < n; i++) {
        for (int j = 1; j < m; j++) {
            b[i][j] = a[i][j]^a[i][j-1]^a[i-1][j-1]^a[i-1][j] ^1;
        }
    }
    int res = max(n,m);
    for (int i = 2; i < n; i++) {
        vector<int> d;
        d.emplace_back(0);
        for (int j = 1; j < m; j++) {
            if (b[i][j]) b[i][j] += b[i-1][j];
            d.emplace_back(b[i][j]);
        }
        d.emplace_back(0);
        int ans = max_area<int>(d);
        res = max(res, ans);
    }
    cout << res;
}

