        cin >> F[i];

    vector<vector<short>> upSame(H, vector<short>(W));
    vector<vector<short>> upNega(H, vector<short>(W));

    for (int y = 1; y < H; ++y) {
        for (int bx = 0; bx < W; ) {
            upSame[y][bx] = W - bx;
            for (int x = bx; x < W; ++x) {
                if (F[y - 1][x] != F[y][x]) {
                    upSame[y][bx] = x - bx;
                    break;
                }
            }
            short v = upSame[y][bx];
            --v;
            ++bx;
            while (v >= 0) {
                upSame[y][bx] = v;
                --v;
                ++bx;
            }
        }
    }
    for (int y = 1; y < H; ++y) {
        for (int bx = 0; bx < W;) {
            upNega[y][bx] = W - bx;
            for (int x = bx; x < W; ++x) {
                if (F[y - 1][x] == F[y][x]) {
                    upNega[y][bx] = x - bx;
                    break;
                }
            }
            short v = upNega[y][bx];
            --v;
            ++bx;
            while (v >= 0) {
                upNega[y][bx] = v;
                --v;
                ++bx;
            }
        }
    }

    int best = max(H, W);
    for (int oy = 0; oy < H; ++oy) {
        if ((H - oy) * W <= best)
            break;

        for (int ox = 0; ox < W; ++ox) {
            if ((H - oy) * (W - ox) <= best)
                break;

            int ex = W;
            for (int ey = oy + 2; ey <= H; ++ey) {
                if ((H - oy) * (ex - ox) <= best)
                    break;

                int y = ey - 1;
                ex = min(ex, ox + max(upSame[y][ox], upNega[y][ox]));
                best = max(best, (ey - oy) * (ex - ox));
            }
        }
    }

    cout << best << '\n';

    return 0;
}

