inline void up(int &x,const int &y){if(x<y)x=y;}
const int maxn = 2100;

int n,m;
char str[maxn];
int col[maxn][maxn],v[maxn][maxn];
int h[maxn],L[maxn],R[maxn];
int t[maxn],tp;

int main()
{
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++)
	{
		scanf("%s",str);
		for(int j=0;j<=m;j++) col[i][j+1]=str[j]=='.'?0:1;
	}
	for(int i=1;i<n;i++) for(int j=1;j<m;j++) v[i][j]=col[i][j]^col[i+1][j]^col[i][j+1]^col[i+1][j+1];
	int ans=max(n,m);
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<m;j++) h[j]++;
		t[tp=1]=0;
		for(int j=1;j<m;j++)
		{
			while(h[t[tp]]>=h[j]) tp--;
			L[j]=t[tp]; t[++tp]=j;
		}
		t[tp=1]=m;
		for(int j=m-1;j>=1;j--)
		{
			while(h[t[tp]]>=h[j]) tp--;
			R[j]=t[tp]; t[++tp]=j;
		}
		for(int j=1;j<m;j++) up(ans,h[j]*(R[j]-L[j]));
		for(int j=1;j<m;j++) if(v[i][j]) h[j]=0;
	}
	printf("%d\n",ans);

	return 0;
}

