const int N=2000+19;
const int oo=(1<<30)-1;

char s[N][N];
int A[N][N],B[N][N],h[N],stk[N],l[N],r[N];
int n,m,ans,top;

void Work(){
	For(i,1,n+1){
		For(j,1,m+1){
			if (A[i][j]) h[j]=0;else h[j]++;
		}
		h[0]=h[m+1]=-1;
		stk[top=1]=0;
		for (int j=1;j<=m;j++){
			while (h[j]<h[stk[top]]) top--;
			l[j]=stk[top];
			stk[++top]=j;
		}
		stk[top=1]=m+1;
		for (int j=m;j>=1;j--){
			while (h[j]<=h[stk[top]]) top--;
			r[j]=stk[top];
			stk[++top]=j;
		}
		For(j,1,m+1){
			ans=max(ans,(h[j]+1)*(r[j]-l[j]));
		}
	}
}

int main(){
	n=IN(),m=IN();
	For(i,1,n+1) scanf("%s",s[i]+1);
	ans=max(n,m);
	For(i,1,n+1) For(j,1,m) B[i][j]=(s[i][j]=='#')^(s[i][j+1]=='#');
	For(i,1,n) For(j,1,m) A[i][j]=B[i][j]^B[i+1][j];
	n--,m--;
	Work();
	printf("%d\n",ans);
}

