#define rep(i,l,r) for(int i=l;i<=r;++i)
#define per(i,r,l) for(int i=r;i>=l;--i)

const int N=2000;
bitset<N>s[N],cant[N];
int n,m;

int lk[N],mx;
void merge(int k)
{
	int l=lk[k-1],r=lk[k];
	chmax(mx,r-l+1);
	lk[l]=r;lk[r]=l;
}

int main()
{
	int n,m;
	cin>>n>>m;
	rep(i,0,n-1)
	{
		string str;
		cin>>str;
		rep(j,0,m-1)s[i][j]=str[j]=='#';
	}
	int ans=0;
	rep(i,0,n-1)
	{
		cant[i].reset();
		rep(j,i+1,n-1)
		{
			bitset<N>now=s[i]^s[j];
			cant[j]=cant[j-1]|(now^(now<<1));
		}
		rep(k,0,m-1)lk[k]=k;
		mx=1;
		rep(k,1,m-1)
		if(!cant[n-1][k])
			merge(k);
		chmax(ans,(n-i)*mx);
		per(j,n-2,i)
		{
			bitset<N>now=cant[j]^cant[j+1];
			for(int k=now._Find_next(0);k<N;k=now._Find_next(k))merge(k);
			chmax(ans,(j-i+1)*mx);
		}
	}
	cout<<ans<<endl;
}

