int main()
{
  std::ios::sync_with_stdio(false);
  cin.tie(NULL) ; cout.tie(NULL) ;
  int n,m;
  cin>>n>>m;
  rep(i,1,n+1) cin>>s[i],s[i]="#"+s[i];
  rep(i,1,n)
    {
      rep(j,1,m)
	{
	  int cnt=(s[i][j]=='#');
	  cnt+=(s[i+1][j]=='#');
	  cnt+=(s[i][j+1]=='#');
	  cnt+=(s[i+1][j+1]=='#');
	  if(cnt%2==1) mat[i][j]=0;
	  else mat[i][j]=1;
	}
    }
  int row=0,col=0,ans=0;
  rep(i,1,n)
    {
      rep(j,1,m)
	{
	  if(mat[i][j]==1) pre[i][j]=pre[i-1][j]+1;
	  else pre[i][j]=0;
	  //trace(i,j,pre[i][j]);
	}
      stack<int> st;
      rep(j,1,m)
	{
	  while(!st.empty() && pre[i][st.top()]>pre[i][j])
	    {
	      int tmp=st.top(); st.pop();
	      int curr=pre[i][tmp]*(st.empty()?j:j-st.top()-1);
	      if(curr>ans)
		{
		  ans=curr;
		  row=(st.empty()?j:j-st.top()-1);
		  col=pre[i][tmp];
		}
	    }
	  st.push(j);
