      while(!st.empty())
	{
	  int tmp=st.top(); st.pop();
	  int curr=pre[i][tmp]*(st.empty()?m-1:m-1-st.top()-1);
	  if(curr>ans)
	    {
	      ans=curr;
	      row=(st.empty()?m-1:m-1-st.top()-1);
	      col=pre[i][tmp];
	    }
	}
      //trace(row,col,ans);
    }
  cout<<(row+1)*(col+1)<<endl;
  return 0 ;
}

#include<cstdio>
