            while(!st.empty() && v[st.top()] > v[j])
            {
                mxl[j] = j - st.top();
                st.pop();
            }
            if(st.empty())
                mxl[j] = j - 1;
            if(!st.empty() && v[st.top()] == v[j])
                mxl[j] = j - st.top();
            else
                st.push(j);
        }
        while(!st.empty())
            st.pop();
        for(int j = m; j >= 1; j--)
        {
            mxr[j] = 0;
            while(!st.empty() && v[st.top()] > v[j])
            {
                mxr[j] = st.top() - j;
                st.pop();
            }
            if(st.empty())
                mxr[j] = m - j;
            if(!st.empty() && v[st.top()] == v[j])
                mxr[j] = st.top() - j;
            else
                st.push(j);
        }
        while(!st.empty())
            st.pop();
        for(int j = 1; j <= m; j++)
            ans = max(ans, (mxl[j] + mxr[j] + 2) * (v[j] + 1));
    }
    cout << ans << "\n";
    return 0;
}

