void solve(int cnt[])
{
	static int lef[MAXN], rig[MAXN];
	stack<int> sta1, sta2;
	for(int i = 1; i <= m - 1; i++)
	{
		while(!sta1.empty() && cnt[sta1.top()] >= cnt[i])
			sta1.pop();
		lef[i] = sta1.empty() ? 0 : sta1.top();
		sta1.push(i);
	}
	for(int i = m - 1; i >= 1; i--)
	{
		while(!sta2.empty() && cnt[sta2.top()] >= cnt[i])
			sta2.pop();
		rig[i] = sta2.empty() ? m : sta2.top();
		sta2.push(i);
	}
	for(int i = 1; i <= m - 1; i++)
		ans = max(ans, (cnt[i] + 1) * (rig[i] - lef[i] - 1 + 1));
	// for(int i = 1; i <= m - 1; i++)
	// 	cerr << lef[i] << ' ' << rig[i] << " / ";
	// cerr << endl;
}

