#define REP(i,n) for(int i=0;i<(int)(n);i++)
#define ALL(x) (x).begin(),(x).end()
#define LL long long

using namespace std;

int main(){

    int H,W;cin>>H>>W;
    bool S[H][W];
    REP(i,H){
        string s;cin>>s;
        REP(j,W)S[i][j]=(s[j]=='#');
    }

    bool rect_[H][W-1];
    REP(i,H)REP(j,W-1)rect_[i][j]=S[i][j]^S[i][j+1];

    bool rect[H-1][W-1];
    REP(i,H-1)REP(j,W-1)rect[i][j]=rect_[i][j]^rect_[i+1][j];

    int length[H-1][W-1];
    REP(i,H-1){
        int cnt=0;
        REP(j,W-1){
            if(!rect[i][j])cnt++;
            else{
                for(int k =j-cnt;cnt>0;k++){
                    length[i][k]=cnt--;
                }
                cnt=0;
                length[i][j]=0;
            }
        }
        REP(j,cnt)length[i][W-1-cnt+j]=cnt-j;
    }

    int area =2;//最大面積０の場合は？
    stack<pair<int,int> > stk;
    REP(j,W-1){
        stk.push({-1,0});
        REP(i,H-1){
            pair<int,int> p = stk.top();
            if(p.first<length[i][j])stk.push({length[i][j],i+1});
            else if(p.first>length[i][j]){
                while(stk.top().first>length[i][j]){
                    p=stk.top();
                    stk.pop();
                    area = max(area,(p.first+1)*(i+1 - p.second +1));
                }
                stk.push({length[i][j],p.second});
            }
        }
        while(!stk.empty()){
            area = max(area,(stk.top().first+1)*(H-stk.top().second +1));
            stk.pop();
        }
    }

    cout<<area<<endl;


    return 0;
}

