        st.push(make_pair(0,-1));
        for(int j=0;j<w;j++){
            pair<int,int> ret;
            while(ret=st.top(),height[i][j]<ret.first){
                res=max((j-ret.second+1)*(ret.first+1),res);
                st.pop();
            }
            st.push(make_pair(height[i][j],j));
        }
    }
    cout<<res<<endl;
    return 0;
}

