using namespace std;

int main()
{
    int H, W;
    cin >> H >> W;

    vector<string> F(H, string());
    for (int i = 0; i < H; ++i)
        cin >> F[i];

    vector<vector<int>> upSame(H, vector<int>(W));
    vector<vector<int>> upNega(H, vector<int>(W));

    for (int y = 1; y < H; ++y) {
        for (int bx = 0; bx < W; ++bx) {
            if (bx > 0 && upSame[y][bx - 1] > 0) {
                upSame[y][bx] = upSame[y][bx - 1] - 1;
            } else {
                upSame[y][bx] = W - bx;
                for (int x = bx; x < W; ++x) {
                    if (F[y - 1][x] != F[y][x]) {
                        upSame[y][bx] = x - bx;
                        break;
                    }
                }
            }

            if (bx > 0 && upNega[y][bx - 1] > 0) {
                upNega[y][bx] = upNega[y][bx - 1] - 1;
            } else {
                upNega[y][bx] = W - bx;
                for (int x = bx; x < W; ++x) {
                    if (F[y - 1][x] == F[y][x]) {
                        upNega[y][bx] = x - bx;
                        break;
                    }
                }
            }
        }
    }

    int best = max(H, W);
    for (int oy = 0; oy < H; ++oy) {
        if ((H - oy) * W <= best)
            break;

        for (int ox = 0; ox < W; ++ox) {
            if ((H - oy) * (W - ox) <= best)
                break;

            int ex = W;
            for (int ey = oy + 2; ey <= H; ++ey) {
                if ((H - oy) * (ex - ox) <= best)
                    break;

                int y = ey - 1;
                ex = min(ex, ox + max(upSame[y][ox], upNega[y][ox]));
                best = max(best, (ey - oy) * (ex - ox));
            }
        }
    }

    cout << best << '\n';

    return 0;
}

