struct tail {
  int l, r;

  tail() : l(0), r(0) {}

  int d() {
    return r - l;
  }
};

void solve() {
  int h, w; cin >> h >> w;
  vector<string> s(h); cin >> s;

  Graph<int> g(h-1, vi(w-1, 0));

  rep(i,h-1) {
    rep(j,w-1) {
      bool even = true;

      if (s[i][j] == '#') even ^= true;
      if (s[i][j+1] == '#') even ^= true;
      if (s[i+1][j] == '#') even ^= true;
      if (s[i+1][j+1] == '#') even ^= true;

      if (even) {
        g[i][j] = i == 0 ? 1 : g[i-1][j] + 1;
      }
    }
  }

  int ans = max(h, w);

  rep(i,h-1) {
    vector<tail> tails(w-1);

    stack<int> st;

    rep(j,w-1) {
      while (!st.empty()) {
        int v = st.top();

        if (g[i][v] <= g[i][j]) break;

        tails[v].r = j;
        st.pop();
      }

      st.emplace(j);
    }

    while (!st.empty()) {
      tails[st.top()].r = w-1;
      st.pop();
    }

    rrep(j,w-1) {
      while (!st.empty()) {
        int v = st.top();

        if (g[i][v] <= g[i][j]) break;

        tails[v].l = j;
        st.pop();
      }

      st.emplace(j);
    }

    while (!st.empty()) {
      tails[st.top()].l = -1;
      st.pop();
    }

    rep(j,w-1) {
      chmax(ans, (g[i][j] + 1) * tails[j].d());
    }
  }

  cout << ans << endl;
}


