        }
    }
}

int solve(int H, int W, vector<string>& s) {
    vector<int> d(W);
    map<ii,int> r_prev;
    int best = W;

    for (int i=0; i<H-1; ++i) {
        // 順
        rep(c, W) {
            d[c] = (s[i][c] == s[i+1][c]);
        }
        vector<ii> r0 = ranges(W, d);

        // 逆
        rep(i, W) d[i] ^= 1;
        vector<ii> r1 = ranges(W, d);

#ifdef DEBUG
        cerr << i << ") " << r_prev << endl;
        cerr << "  + " << r0 << endl;
        cerr << "  + " << r1 << endl;
#endif
        for (ii p : r0) {
            best = max(best, 2 * (p.second - p.first));
        }
        for (ii p : r1) {
            best = max(best, 2 * (p.second - p.first));
        }

        map<ii,int> r_next;
        append_range(r_next, r_prev, r0);
        append_range(r_next, r_prev, r1);
#ifdef DEBUG
        cerr << " => " << r_next << endl;
#endif

        r_prev = r_next;

        for (auto p : r_prev) {
            ii x = p.first;
            int ph = p.second;
            best = max(best, (ph+1) * (x.second - x.first));
        }

    }

    return best;
}

