lli getLargestHist(vector<lli> h)
{
    stack<node> st;
    lli m = 0;
    h.push_back(0);
    rep(i, h.size())
    {
        node a;
        a.h = h[i];
        a.x = i;
        if (st.empty()) {
            st.push(a);
        } else if (st.top().h < a.h) {
            st.push(a);
        } else if (st.top().h > a.h) {
            int tar = i;
            while (!st.empty() && st.top().h >= a.h) {
                node pre = st.top();
                st.pop();
                m = max(pre.h * (i - pre.x + 1), m);
                tar = pre.x;
            }
            a.x = tar;
            st.push(a);
        }
    }
    return m;
}
