template<typename T>
T largestrectangle(vector<T> &v){
  int n=v.size();
  T res=0;
  using P = pair<int, T>;
  stack<P> sp;
  sp.emplace(-1,T(0));
  for(int i=0;i<n;i++){
    int j=i;
    while(sp.top().second>v[i]){
      j=sp.top().first;
      if(sp.top().second)
        res=max(res,(i-j+1)*(sp.top().second+1));
      sp.pop();
    }
    if(sp.top().second<v[i]) sp.emplace(j,v[i]);
  }
  while(!sp.empty()){
    if(sp.top().second)
      res=max(res,(n-sp.top().first+1)*(sp.top().second+1));
    sp.pop();
  }
  return res;
}

