#include <bits/stdc++.h>
using namespace std;
#define FOR(i,n) for (int i=1;i<=n;i++)
#define REP(i,a,b) for (int i=a;i<=b;i++)

#define pb push_back

typedef long long ll;

const int inf=0x3f3f3f3f;
const int N=2000+10;

int n,m;
int a[N][N];
int b[N];
int f[N][N];
int s[N];
int pos[N];
int top;
int lf[N],rf[N];
int cpt() {
	// 对于所有1<=l<=r<=n，计算出max{(r-l+1)*min(b[l]~b[r])}
	// 思想是枚举区间[l,r]中最小值向两边延伸
	memset(s,0,sizeof s);
	memset(pos,0,sizeof pos);
	memset(lf,0,sizeof lf);
	memset(rf,0,sizeof rf);
	top=0;

	FOR(i,m) {
		while (top&&s[top]>=b[i]) {
			top--;
		}
		lf[i]=pos[top]+1;
		s[++top]=b[i];
		pos[top]=i;
	}
	top=0;
	FOR(i,m) pos[i]=0;
	for (int i=m;i>=1;i--) {
		while (top&&s[top]>=b[i]) {
			top--;
		}
		rf[i]=pos[top]-1;
		if (top==0) rf[i]=m;
		s[++top]=b[i];
		pos[top]=i;
	}
	int ans=0;
	FOR(i,m) {
		ans=max(ans,(rf[i]-lf[i]+2)*b[i]);
	}
	return ans;
}
bool check(int x,int y) {
	int cnt=0,cnt2=0;
	REP(i,0,1) REP(j,-1,0) {
		if (a[x+i][y+j]) cnt++;
		else cnt2++;
	}
	if (cnt==1||cnt2==1) return 0;
	return 1;
}
int main() {

	std::ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	cin>>n>>m;
	FOR(i,n) FOR(j,m) {
		char t='\n';
		while (t=='\n') cin>>t;
		if (t=='#') a[i][j]=1;
	}
	// 大小边界？
	if (m==1) {
		int cnt=0;
		FOR(i,n) if (a[i][1]) cnt++;
		return max(cnt,n-cnt);
	}
	for (int i=n;i>=1;i--) REP(j,2,m) {
		if (i==n) f[i][j]=1;
		else {
			if (check(i,j)) f[i][j]=f[i+1][j]+1;
			else f[i][j]=1;
		}
	}
	/*
	FOR(i,n) {
		FOR(j,m) cout<<f[i][j];
		cout<<endl;
	}
	*/
	int ans=0;
	FOR(i,n) {
		FOR(j,m-1) b[j]=f[i][j+1];
		m--;
		ans=max(ans,cpt());
		m++;
	}
	cout<<ans<<endl;
	return 0;
}

