long long max_rectangle(const std::vector<long long>& hist){
  using ll=long long;
  using P=std::pair<ll,ll>;

  ll w=hist.size();
  ll ret=0;
  std::stack<P> sta;
  for(ll i=0;i<w;i++){
    ll left=i;
    while(!sta.empty()&&sta.top().first>=hist[i]){
      auto e=sta.top();sta.pop();
      left=e.second;
      if((i-e.second+1)*(e.first+1)>ret)ret=(i-e.second+1)*(e.first+1);
    }
    sta.push(P(hist[i],left));
  }
  while(!sta.empty()){
    auto e=sta.top();sta.pop();
    if((w-e.second+1)*(e.first+1)>ret)ret=(w-e.second+1)*(e.first+1);
  }
  return ret;
}

