struct dat{int h,i;};

int calc(int A[],int f){
  stack <dat> S;
  int res = 0;
  for(int i=0;i<=w;i++){
    int h = A[i];
    if(S.empty() || S.top().h < h) S.push((dat){h,i});
    else if(S.top().h > h){
      int ni = i;
      while(!S.empty() && S.top().h > h){
        dat t = S.top(); S.pop();
        ni = t.i;

        if(f==0 && i-t.i>0 && t.h>0){
          int area = (i - t.i + 1) * ( t.h + 1);
          res = max(res,area);
        }
        if(f==1){
          int area = (i - t.i ) * ( t.h );
          res = max(res,area);
        }
      }
      res = max(res,(i-ni)*h);
      S.push((dat){h,ni});
    }
  }
  return res;
}

