// ヒストグラム内最大長方形
// 実際の長方形の間を受け取っているので、調整する

int solve(vector<int> vec) {
  stack<int> st;
  int n = vec.size();
  vector<int> L(n), R(n);
  for(int i = 0; i < n; i++) {
    int h = vec[i];
    L[i] = i;
    while(st.size() && vec[st.top()] >= h) {
      L[i] = st.top();
      if(vec[st.top()] > h) st.pop();
      else break;
    }
    if(st.empty() || h != vec[st.top()]) st.push(i);
  }
  while(st.size()) st.pop(); /// ///
  for(int i = n-1; i >= 0; i--) {
    int h = vec[i];
    R[i] = i;
    while(st.size() && vec[st.top()] >= h) {
      R[i] = st.top();
      if(vec[st.top()] > h) st.pop();
      else break;
    }
    if(st.empty() || h != vec[st.top()]) st.push(i);
  }
  int res = 0;
  for(int i = 0; i < n; i++) {
    res = max(res, vec[i] * (R[i] - L[i] + 1 + 1));
  }
  return res;
}

