using ll = long long;

// max Rectangle in Histogram

int calc(vector<int> v) {
  int n = v.size();
  vector<int> L(n), R(n);

  // decreasing from top
  stack<int> st;
  for(int i=0; i < n; i++) {
    while(st.size() && v[st.top()] >= v[i]) st.pop();
    /////////
    L[i] = 0;
    if(st.size()) L[i] = st.top()+1;
    if(st.empty() || v[st.top()] != v[i]) st.push(i);
    /////////
  }
  st = stack<int>();
  for(int i=n-1; i >= 0; i--) {
    while(st.size() && v[st.top()] >= v[i]) st.pop();
    /////////
    R[i] = n-1;
    if(st.size()) R[i] = st.top()-1;
    if(st.empty() || v[st.top()] != v[i]) st.push(i);
    /////////
  }
  int res = 0;
  for(int i=0; i < n; i++) {
    res = max(res, v[i] * (R[i] - L[i] + 2));
  }
  return res;
}

