template<typename T> T calc(T h,T w){ return (h+1)*(w+1); }
template<typename T> T LargestRectangle(vector<T>& v)
{
   int N=v.size();
   vector<int> l(N),r(N);
   stack<int> S;
   for(int i=0;i<N;i++){
      while(!S.empty() and v[S.top()]>=v[i]) S.pop();
      l[i]=(S.empty()? 0:S.top()+1); S.push(i);
   }
   S=stack<int>();
   for(int i=N-1;i>=0;i--){
      while(!S.empty() and v[S.top()]>=v[i]) S.pop();
      r[i]=(S.empty()? N:S.top()); S.push(i);
   }
   T res=0;
   for(int i=0;i<N;i++) res=max(res,calc(v[i],r[i]-l[i]));
   return res;
}

