int N, M;
char Matrix[2005][2005];
bool X[2005][2005];
int Dif[2][2005][2005];
pair <int, int> Deq[5005];
int ans;
void Read()
{
    cin >> N >> M;
    cin.get();
    for(int i = 1; i <= N; i++)
        cin.getline(Matrix[i] + 1, 2005);
    for(int i = 1; i <= N; i++)
        for(int j = 1; j <= M; j++)
            if(Matrix[i][j] == '#')
                X[i][j] = 1;
}

void precalcDif()
{
    for(int i = 1; i <= N; i++)
        for(int j = 1; j <= M; j++)
        {
            if(Matrix[i][j] != Matrix[i][j - 1])
            {
                Dif[0][i][j] = 0;
                Dif[1][i][j] = Dif[1][i - 1][j] + 1;
            }
            else
            {
                Dif[1][i][j] = 0;
                Dif[0][i][j] = Dif[0][i - 1][j] + 1;
            }
        }
}

void Solve()
{
    ans = max(M, N);
    for(int i = 1; i <= N; i++)
    {
        for(int row = 0; row <= 1; row++)
        {
            int End = 0, Begin = 1;
            Deq[++End] = make_pair(i, 1);
            for(int j = 2; j <= M; j++)
            {
                int val1 = X[i][j - 1], val2 = X[i][j];
                if(row == 1)
                    val1 = 1 - val1, val2 = 1 - val2;
                int x = 0, y = 0;
                if(val1 == 0)
                {
                    x = 1;
                }
                if(val2 == 0)
                    y = 1;
                x = (x ^ y);
                int pos = Dif[x][i - 1][j] + 1;
                while(Begin <= End && pos <= Deq[End].first)
                {
                    ans = max(ans, (j - Deq[End - 1].second) * Deq[End].first);
                    --End;
                }
                Deq[++End] = make_pair(pos, j);
            }
            while(Begin <= End)
            {
                ans = max(ans, (M + 1 - Deq[End - 1].second ) * Deq[End].first);
                --End;
            }
        }
    }
    cout << ans << "\n";
}
int main()
{
    Read();
    precalcDif();
    Solve();
    return 0;
}

