int black[2020][2020];
int white[2020][2020];
int same[2020][2020];
int diff[2020][2020];

void preprocess(){
    rep(i,H) rep(j,W){
        if(S[i][j]=='#') black[i][j]=1;
        if(i>0&&S[i][j]=='#') black[i][j]+=black[i-1][j];
    }
    rep(i,H) rep(j,W){
        if(S[i][j]=='.') white[i][j]=1;
        if(i>0&&S[i][j]=='.') white[i][j]+=white[i-1][j];
    }

    rep(i,H) rep(j,W){
        if(j==0) continue;
        if(S[i][j]==S[i][j-1]) same[i][j]=1;
        if(i>0&&S[i][j]==S[i][j-1]) same[i][j]+=same[i-1][j];
    }
    rep(i,H) rep(j,W){
        if(j==0) continue;
        if(S[i][j]!=S[i][j-1]) diff[i][j]=1;
        if(i>0&&S[i][j]!=S[i][j-1]) diff[i][j]+=diff[i-1][j];
    }
}

int calc(int h,vector<int> &A,vector<int> &P){
    stack<pair<int,int>> st;
    int res=0;
    rep(j,W){
        if(j==0) continue;
        int pos=j;
        while(st.size()&&st.top().first>=P[j]){
            auto f=st.top();
            st.pop();
            pos=f.second;
        }
        chmax(res,P[j]*(j-pos+2));
        st.push(mkp(P[j],pos));
    }
    while(st.size()){
        auto f=st.top();
        st.pop();
        chmax(res,f.first*(W-f.second));
    }

    int now=0;
    while(now<W){
        int plus=h+1;
        int nex=now+1;
        while(nex<W&&A[nex]==A[now]){
            chmin(plus,P[nex]);
            chmax(res,(plus)*(nex-now+1));
            nex++;
        }
        now=nex;
    }
    return res;
}

