#define N 2010
using namespace std;
int n, m, m1[N][N], map[N][N], sum, ans, L[N][N], R[N][N], h[N][N];
char S[N];
int main(){
	scanf("%d%d", &n, &m);
	for(int i=1; i<=n; i++){
		scanf("%s", S+1);
		for(int j=1; j<=m; j++)m1[i][j]=S[j]=='#'?1:0;
	}
	for(int i=1; i<=n-1; i++)
		for(int j=1; j<=m-1; j++){
			sum=m1[i][j]+m1[i][j+1]+m1[i+1][j]+m1[i+1][j+1];
			map[i][j]=sum&1?0:1;
		}
	ans=max(n, m);
	for(int i=1; i<=n-1; i++){
		L[i][0]=0;
		for(int j=1; j<=m-1; j++)L[i][j]=map[i][j]?L[i][j-1]:j;
		R[i][m]=m;
		for(int j=m-1; j; j--)R[i][j]=map[i][j]?R[i][j+1]:j;
	}
	for(int i=1; i<=m-1; i++){L[0][i]=0; R[0][i]=m; h[0][i]=0;}
	for(int i=1; i<=n-1; i++)
		for(int j=1; j<=m-1; j++){
			if(!map[i][j]){L[i][j]=0; R[i][j]=m; h[i][j]=0; continue;}
			h[i][j]=h[i-1][j]+1; L[i][j]=max(L[i-1][j], L[i][j]); R[i][j]=min(R[i-1][j], R[i][j]);
			ans=max(ans, (R[i][j]-L[i][j])*(h[i][j]+1));
		}
	printf("%d", ans);
	return 0;
}

