int H, W;
vector<string> S;
vector<vector<vector<pair<int, int> > > > rects;
vector<vector<int> > odd;

vector<pair<int, int> > dp(int h, int w)
{
    vector<pair<int, int> > res;

    res.push_back(make_pair(1, w+1));
    res.push_back(make_pair(h+1, 1));

    int maxHeight = h + 1;
    for (int i=0; i<=h; i++) if (odd[i][w]) maxHeight = h + 1 - i;
    int maxWidth = w + 1;
    for (int j=0; j<=w; j++) if (odd[h][j]) maxWidth = w + 1 - j;

    for (auto ulp : rects[h-1][w-1])
    {
        pair<int, int> newpair = make_pair(min(maxHeight, ulp.first+1), min(maxWidth, ulp.second+1));
        res.push_back(newpair);
    }
    sort(res.begin(), res.end());
    reverse(res.begin(), res.end());

    vector<pair<int, int> > res2{res.front()};
    for (auto r : res)
    {
        if (r.first != res2.back().first) res2.push_back(r);
    }

    return res2;
}

