	if (c == 0 && r == 0 && input[0][0] == input[1][0])
		return 3 * dfs(0, 1, false) % 7;
	else if (c == 0 && r == 0 && input[0][0] == input[0][1])
		return 3 * dfs(1, 0, false) % 7;
	else if (c == 0 && r == 1)
		return 2 * dfs(0, 2, false) % 7;
	else
	{
		if (r == 0 && input[0][c] == input[1][c])
		{
			if (input[0][c - 1] == input[1][c - 1])
				return 2 * dfs(0, c + 1, false) % 7;
