		else if (r == 0)
			return 2 * dfs(1, c, false) % 7 + dfs(1, c, true) % 7;
		else
		{
			if (flag)
				return 2 * dfs(0, c + 2, false) % 7;
			else
				return dfs(0, c + 2, false) % 7;
		}
	}
}

