typedef long long ll;
typedef pair<ll, ll> pii;
typedef vector<ll> vi;
typedef vector<vi> vvi;
typedef vector<pii> vpii;
const ll INF = (1ll << 60);

int main() {
  ll H, W;
  cin >> H >> W;

  vvi G(H, vi(W));
  for (ll i = 0; i < H; i++) {
    string s;
    cin >> s;
    for (ll j = 0; j < W; j++) {
      if (s[j] == '#') {
        G[i][j] = 1;
      }
    }
  }

  vvi A(H - 1, vi(W - 1));
  for (ll i = 0; i < H - 1; i++) {
    for (ll j = 0; j < W - 1; j++) {
      if ((G[i][j] + G[i][j + 1] + G[i + 1][j] + G[i + 1][j + 1]) % 2) {
        A[i][j] = 1;
      }
    }
  }

  vvi B(H - 1, vi(W - 1));
  for (ll i = 0; i < H - 1; i++) {
    for (ll j = 0; j < W - 1; j++) {
      if (A[i][j]) {
        B[i][j] = 0;
      } else {
        if (i == 0)
          B[i][j] = 1;
        else
          B[i][j] = B[i - 1][j] + 1;
      }
    }
  }

  ll ans = 0;

  for (ll i = 0; i < H - 1; i++) {
    stack<pair<ll, ll>> s;
    for (ll j = 0; j < W - 1; j++) {
      if (s.size() == 0 && B[i][j] > 0) {
        s.push({j, B[i][j]});
      } else if (s.size() && B[i][j] > s.top().second) {
        s.push({j, B[i][j]});
      } else if (s.size() && B[i][j] < s.top().second) {
        while (s.size() && B[i][j] < s.top().second) {
          ans = max(ans, (s.top().second + 1) * (j - s.top().first + 1));
          s.pop();
        }
      }
    }

    while (s.size()) {
      ans = max(ans, (s.top().second + 1) * (W - s.top().first));
      s.pop();
    }
  }

  cout << ans << endl;
}

