    scanf("%d%d", &h, &w);
    for (int i = 1; i <= h; ++i)
        scanf("%s", input[i] + 1);
    if (h == 1 || w == 1) {
        printf("%d\n", h * w);
        return 0;
    }
    for (int i = 1; i <= h; ++i)
        for (int j = 1; j < w; ++j) {
            input[i][j] = input[i][j] != input[i][j + 1];
            input[i][j] ^= input[i - 1][j];
        }
    for (int i = h; i > 2; --i)
        for (int j = 1; j < w; ++j)
            input[i][j] ^= input[i - 2][j];
    for (int i = 2; i <= h; ++i) {
        front = rear = 1;
        while (rear < w) {
            while (rear < w && !input[i][rear])
                ++rear;
            while (front < rear) {
                rl[i][front] = rear - front;
                ++front;
            }
            ++rear, ++front;
        }
    }
