                s[pos++] = Rect(rl[i][j], 1);
            else {
                w_now = 0;
                while (pos && rl[i][j] <= s[pos - 1].h) {
                    w_now += s[pos - 1].w;
                    ans < (t = (s[pos - 1].h + 1) * (w_now + 1)) && (ans = t);
                    --pos;
                }
                s[pos++] = Rect(rl[i][j], w_now + 1);
            }
        }
        w_now = 0;
        while (pos) {
            w_now += s[pos - 1].w;
            ans < (t = (s[pos - 1].h + 1) * (w_now + 1)) && (ans = t);
            --pos;
        }
    }
    ans < h && (ans = h);
    ans < w && (ans = w);
    printf("%d\n", ans);
    return 0;
}

