typedef long long ll;
typedef pair<ll,ll> P;

char mp[2222][2222];
bool ng[2222][2222];
int high[2222][2222];

int seica(int h,int w){
	ll ret = 0;
	REP(i,h){
		stack<pair<ll,ll>> st;
		REP(j,w){
			if(st.empty() || st.top().FI < high[i][j]){
				st.push(MP(high[i][j],j));
			}
			else if(st.top().FI == high[i][j]){
				continue;
			}
			else {
				while(!st.empty() && st.top().FI > high[i][j]){
					auto now = st.top();
					st.pop();
					ret = max(ret,(j - now.SE) * now.FI);
					//cout << i << " " << now.FI << " " << now.SE << " " << (j - now.SE) * now.FI << endl;
				}
			}
			if(st.empty() || st.top().FI < i + 1)st.push(MP(i + 1,j));
		}
		while(!st.empty()){
			auto now = st.top();
			st.pop();
			ret = max(ret, (w - now.SE) * now.FI);
			//cout << i << " " << now.FI << " " << now.SE << " " << (w - now.SE) * now.FI << endl;
		}
	}
	return ret;
}

