			else {
				l[t.se] = l[t.se-1];
			}

			if(t.se == W-2 || r[t.se+1] < 0) {
				r[t.se] = t.se;
			}
			else {
				r[t.se] = r[t.se+1];
			}

			r[l[t.se]] = r[t.se];
			l[r[t.se]] = l[t.se];

			res = max(res, h * (r[t.se]-l[t.se]+2));
		}
	}
	res = max(res, (ll)max(H,W));
	cout << res << endl;
}

