			if((a[i][j]==a[i+1][j])==(a[i][j+1]==a[i+1][j+1]))
				b[i][j]=b[i][j+1]+1;
			else
				b[i][j]=1;
		}
	}
	int maxlen;
	for(int i=1;i<=m;i++){
		for(int j=1;j<n;j++)
			c[j]=(node){j,b[j][i]};
		for(int j=1;j<=n;j++)
			f[j]=j,len[j]=1;
		maxlen=1;
		sort(c+1,c+n,cmp);
		for(int j=1;j<n;j++){
			len[fa(c[j].p)]+=len[fa(c[j].p+1)];
			f[fa(c[j].p+1)]=fa(c[j].p);
			if(len[fa(c[j].p)]>maxlen)
				maxlen=len[fa(c[j].p)];
			if(maxlen*c[j].v>ans)
				ans=maxlen*c[j].v;
		}
	}
	printf("%d\n",ans);
	return 0;
}

