    for(i=0; i<H; i++){
        cin >> s[i];
    }
    for(i=1; i<H; i++){
        for(j=0; j<W; j++){
            bad[i][j] = (s[i-1][j-1] == '#') ^ (s[i][j-1] == '#') ^ (s[i-1][j] == '#') ^ (s[i][j] == '#');
        }
    }
    long long ans = 0;
    long long r;
    for(r=1; r<=W; r++){
        vector<long long> stack = {};
        for(i=0; i<=H; i++){
            if(bad[i][r-1]){
                l[i] = r - 1;
            }
            width[i] = r - l[i];
            while(stack.size() > 0 && width[stack[stack.size()-1]] >= width[i]){
                stack.pop_back();
            }
            top[i] = stack.size() == 0 ? 0 : stack[stack.size()-1];
            stack.push_back(i);
        }
        stack.resize(0);
        for(i=H; i>=0; i--){
            while(stack.size() > 0 && width[stack[stack.size()-1]] >= width[i]){
                stack.pop_back();
            }
            bottom[i] = stack.size() == 0 ? H : stack[stack.size()-1];
            stack.push_back(i);
        }
        for(i=0; i<=H; i++){
            ans = max(ans, width[i] * (bottom[i] - top[i]));
        }
    }
    cout << ans << endl;
    return 0;
}

