template <class T>
class mque{
	protected:
		T que[N];
		int hd,tl;
	public:
		mque():hd(0),tl(0){}
		inline T front(){
			return que[hd];
		}
		inline void pop(){
			++hd;
		}
		inline void push(const T &v){
			que[tl++]=v;
		}
};
mque <int> lim[N];

int solve(const int st){
	static int buk[N],stk[N];
	for(int i=1; i<m; ++i){
		while(lim[i].front()<st) lim[i].pop();
		buk[i]=lim[i].front();
	}
	buk[m]=st-1;
	int ans=0,top=0;
	for(int i=1; i<=m; ++i){
		for(; top&&buk[stk[top]]>buk[i]; --top){
			apx(ans,(i-stk[top-1])*(buk[stk[top]]-st));
		}
		stk[++top]=i;
	}
	return ans;
}

