struct Rectangle { int height;  int pos; };

int getLargestRectangle(int size, vi buffer) {
	stack<Rectangle> S;
	int maxv = 0;
	buffer[size] = 0;

	for (int i = 0; i <= size; i++) {	//
		Rectangle rect;
		rect.height = buffer[i];
		rect.pos = i;
		if (S.empty()) {
			S.push(rect);
		}
		else {
			if (S.top().height < rect.height) {
				S.push(rect);
			}
			else if (S.top().height > rect.height) {
				int target = i;
				while (!S.empty() && S.top().height >= rect.height) {
					Rectangle pre = S.top(); S.pop();
					int area = ((pre.height + 1) / 2) * ((i - pre.pos + 1) / 2);
					maxv = max(maxv, area);
					target = pre.pos;
				}
				rect.pos = target;
		        S.push(rect);
			}
		}
	}
	return maxv;	
}
