      while (k + 1 < w && biggest[k+1] == 0) ++k;
      //cerr << i << " " << j << " " << k << endl;
      int width = k - j + 1;
      int s = width * (i + 1);
      if (s > ans) ans = s;
      int height = i - biggest[j] + 1;
      while (top > 0 && height <= stk[top-1].h)
      {
        int w = j - stk[top-2].w - 1;
        int h = height;
        int s = w * h;
        if (s > ans) ans = s;
        --top;
      }
      stk[top++] = {k, height};
      j = k + 1;
    }
    while (top > 1)
    {
      --top;
      int s = stk[top].h * (w-1 - stk[top-1].w);
      if (s > ans) ans = s;
    }
  }
  printf("%d\n", ans);
  return 0;
}

