    for(int i=0;i+1<h;i++){
        for(int j=0;j+1<w;j++){
            int cnt = s[i][j]=='#' ^ s[i+1][j]=='#' ^ s[i][j+1]=='#' ^ s[i+1][j+1]=='#';
