bool Judge (int x, int y) {
	return x > 1 & y > 1 && (((s[x][y] == '#') + (s[x - 1][y] == '#') + (s[x][y - 1] == '#') + (s[x - 1][y - 1] == '#')) & 1);
}

void Max (int &x, int y) { if (x < y) x = y; }

int main () {
	scanf("%d%d", &H, &W);
	for (int i = 1; i <= H; ++i) scanf("%s", s[i] + 1);
	for (int i = 1; i <= H; ++i) {
		for (int j = 1; j <= W; ++j) {
			++h[j];
			if (j < W && Judge(i, j + 1)) h[j] = 1;
			while (top && h[stk[top]] >= h[j]) {
				Max(ans, h[stk[top]] * (j - stk[top - 1]));
				--top;
			}
			stk[++top] = j;
		}
		while (top) Max(ans, h[stk[top]] * (W - stk[top - 1])), --top;
	}
	printf("%d\n", ans);
	return 0;
}

