ll f(vvi arr){
    int n = sz(arr);
    int m = sz(arr[0]);
    for(auto &_ : arr)
        _.insert(_.begin(),-1);
    arr.insert(arr.begin(),vi(m+1,-1));
    vvi up(n+2,vi(m+2,0));
    rep(i,1,n)
        rep(j,1,m){
            up[i][j] = up[i-1][j]+1;
            if(arr[i][j] != 0)
                up[i][j] = 0;
