                ll h = stacc.back().Y;
                ans = max(ans,(w+1)*(h+1));
                last_popped = stacc.back().X;
                stacc.pop_back();
            }
            stacc.pb({last_popped,up[i][j]});
        }
    }
    return ans;
}
