using namespace std;

const int MaxN = 2000;
int n, m;
int a[MaxN + 5][MaxN + 5];
int b[MaxN + 5][MaxN + 5];
int l[MaxN + 5], r[MaxN + 5], h[MaxN + 5];
char s[MaxN + 5];

bool Check(int x, int y)
{
	int cnt = 0;
	cnt += b[x][y];
	cnt += b[x + 1][y];
	cnt += b[x][y + 1];
	cnt += b[x + 1][y + 1];
	return (!(cnt & 1));
}

void Init()
{
	memset(a, 0, sizeof(a));
	memset(b, 0, sizeof(b));
	for (int i = 1; i <= n; i++) {
		scanf("%s", s);
		for (int j = 0; j < m; j++)
			b[i][j + 1] = (int)(s[j] == '#');
	}
	for (int i = 1; i <= n - 1; i++)
		for (int j = 1; j <= m - 1; j++)
			if (Check(i, j)) a[i][j] = 1;
				else a[i][j] = 0;
}

void Solve()
{
	int i = 0, j = 0, lmax = 0, rmax = 0, ans = 0; 
	n--; m--;
	memset(l, 0, sizeof(l));
	memset(r, 0, sizeof(r));
	memset(h, 0, sizeof(h));
	/*for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++)
			printf("%d ", a[i][j]);
		printf("\n");
	}*/
	for (i = 1; i <= m; i++) l[i] = 1, r[i] = m;
	for (i = 1; i <= n; i++) {
		for (lmax = j = 1; j <= m; j++) if (a[i][j]) {
			h[j]++;
			if (lmax > l[j]) l[j] = lmax;
		}else h[j] = 0, l[j] = 1, r[j] = m, lmax = j + 1;
		for (rmax = j = m; j; j--) if (a[i][j]) {
			if (rmax < r[j]) r[j] = rmax;
			if ((r[j] - l[j] + 2) * (h[j] + 1) > ans) 
				ans = (r[j] - l[j] + 2) * (h[j] + 1);
		}else rmax = j - 1;
	}
	printf("%d\n", ans);
}

int main()
{
	while (~scanf("%d%d", &n, &m)) {
		Init();
		Solve();
	}
	return 0;
}

