#define INF 1145141919
#define MOD 1000000007

int H, W;
int S[2000][2000];
int T[2000][2000];
int solve(int y) {
  vector<int> h;
  rep(x, W) h.pb(T[x][y]);
  h.pb(0);
  //for (int y:h)cout<<y<<",";cout<<"\n";

  int m = 0;
  stack<P> S;
  rep(x, h.size()) {
    if (S.empty()) {
      S.push(P(h[x], x));
    }
    else {
      if (S.top()._1 < h[x]) {
        S.push(P(h[x], x));
      }
      else if (S.top()._1 > h[x]) {
        int last = x;
        while (!S.empty() && S.top()._1 >= h[x]) {
          P t = S.top(); S.pop();
          //m = max(m, t._1 * (x - t._2));
          m = max(m, (t._1+1) * (x - t._2 + 1));
          last = t._2;
        }
        S.push(P(last, x));
      }
    }
  }
  return m;
}

