      T[x-1][y-1] = S[x][y]^S[x-1][y]^S[x][y-1]^S[x-1][y-1];
    }
  }
  W--, H--;
  //rep(y, H) {rep(x, W) cout<<T[x][y];cout<<"\n";}
  rep(x, W) rep(y, H) T[x][y] ^= 1;
  // find the largest rectangle with only 1s
  rep(x, W) {
    rep(y, H) {
      if (y > 0 && T[x][y]) T[x][y] += T[x][y-1];
    }
  }
  int m = 0;
  rep(y, H) m = max(m, solve(y));
  cout << m << "\n";
  return 0;
}

