int calc(vector<int> v) {
	int n = v.size(), t = 0;
	for (int i = 0; i < n; i++) {
		if (t > 0 && v[st[t - 1]] >= v[i]) t--;
		L[i] = (t == 0 ? 0 : st[t - 1] + 1);
		st[t++] = i;
	}
	t = 0;
	for (int i = n - 1; i >= 0; i--) {
		while (t > 0 && v[st[t - 1]] >= v[i]) t--;
		R[i] = (t == 0 ? n : st[t - 1]);
		st[t++] = i;
	}
	int ret = 0;
	for (int i = 0; i < n; i++) ret = max(ret, v[i] * (R[i] - L[i] + 1));
	return ret;
}
