    const int MAXW = 2010;

    static string S[MAXH];
    for (int r = 0; r < H; r++) {
        cin >> S[r];
    }

    static int height[MAXH][MAXW];
    for (int c = 0; c < W; c++) {
        int t = 0;
        int status = -1; // 1:同じ, 0:異なる
        for (int r = 0; r < H; r++) {
            if (c > 0 and (S[r][c - 1] == S[r][c]) != status) {
                t = r;
                status = (S[r][c - 1] == S[r][c]);
            }
            height[r][c] = r - t + 1;
        }
    }

    // 最大長方形問題
    int ans = 0;
    for (int r = 0; r < H; r++) {
        static int L[MAXW], R[MAXW];
        memset(L, 0, sizeof(L));
        stack<int> st;
        for (int c = 0; c < W; c++) {
            while (!st.empty() and height[r][st.top()] >= height[r][c]) st.pop();
            L[c] = st.empty() ? 0 : (st.top() + 1);
            st.push(c);
        }

        memset(R, 0, sizeof(R));
        while (!st.empty()) st.pop();
        for (int c = W - 1; c >= 0; c--) {
            while (!st.empty() and height[r][st.top()] >= height[r][c]) st.pop();
            R[c] = st.empty() ? (W - 1) : (st.top() - 1);
            st.push(c);
        }

        for (int c = 0; c < W; c++) {
            ans = max(ans, (R[c] - max(0, L[c] - 1) + 1) * height[r][c]);
        }
    }
    cout << ans << endl;

    return 0;
}

