int top[N];
int ans = 0;

void update(int k, int l, int r, int pos, int val) {
	if (pos < l || r < pos) return;
	if (l == r && r == pos) {
		f[k].fi = val; f[k].se = pos;
		return;
	}
	int mid = (l + r) / 2;
	update(k * 2, l, mid, pos, val); update(k * 2 + 1, mid + 1, r, pos, val);
	f[k] = max(f[k * 2], f[k * 2 + 1]);
}

pair<int, int> get(int k, int l, int r, int L, int R) {
	if (r < L || R < l) return mp(0, 0);
	if (L <= l && r <= R) return f[k];
	int mid = (l + r) / 2;
	return max(get(k * 2, l, mid, L, R), get(k * 2 + 1, mid + 1, r, L, R));
}

void upgrade(int wh) {
	for (int i = 2; i <= m; i++) {
		int sum = a[wh][i] + a[wh][i - 1] + a[wh - 1][i] + a[wh - 1][i - 1];
		if (sum & 1) {
			top[i] = wh;
			update(1, 1, m, i, wh);
		}
	}
}

int solve(int l, int r, int base) {
	if (l > r) return 0;
	if (l == r) {
		int h = base - top[l] + 1;
		return h * (r - l + 2);
	}
	pair<int, int> rec = get(1, 1, m, l, r);
	int h = base - rec.fi + 1;
	int ret = h * (r - l + 2);
	ret = max(ret, solve(l, rec.se - 1, base));
	ret = max(ret, solve(rec.se + 1, r, base));
	return ret;
}

