string str3[2000];
vector<int> v[2000];

int MAX = 0;

void Register(int i) {
	if (MAX < i) MAX = i;
}


int main() {
	cin >> H >> W;
	REP(i, 0, H) {
		cin >> str[i];
	}

	REP(i, 0, H) {
		REP(j, 0, W) {
			str2[i] += '.';
			str3[i] += '.';
		}
	}

	REP(i, 0, H) {
		REP(j, 1, W) {
			if (str[i][j] == str[i][j - 1]) {
				str2[i][j] = '.';
			} else {
				str2[i][j] = '#';
			}
		}
	}

	REP(j, 0, W) {
		REP(i, 1, H) {
			if (str2[i][j] == str2[i - 1][j]) {
				str3[i][j] = '.';
			} else {
				str3[i][j] = '#';
			}
		}
	}


	REP(i, 0, H) {
		str3[i][0] = '#';
	}
	REP(j, 0, W) {
		str3[0][j] = '#';
	}

	REP(i, 0, H) {
		REPM(j, W - 1, 0) {
			if (str[i][j] == str[i][j + 1]) {
				str2[i][j] = '.';
			} else {
				str2[i][j] = '#';
			}
		}
	}

	REP(i, 0, H) {
		REP(j, 0, W) {
			if (str3[i][j] == '#') {
				v[i].push_back(j);
			}
		}
	}

	//REP(i, 0, H) {
	//	cout << str3[i] << endl;
	//}


	REP(i, 0, H) {
		REP(j, 0, W) {
			if (str3[i][j] == '.') continue;
			int right = W - 1;

			Register(right - j + 1);
			REP(k, i + 1, H) {
				auto it = lower_bound(v[k].begin(), v[k].end(), j + 1);
				if (it != v[k].end() && *it <= right) {
					right = *it - 1;
				}
				/*if (j == right) {
					Register(H - i);
					break;
				}*/
				Register((k - i + 1) * (right - j + 1));
			}
		}
	}
	cout << MAX << endl;
	return 0;
}

