const int MAXN=2000;
//arr 1 adalah arr invers
//versi adalah jenis yang mana yang mau diambe
int par[MAXN+5],kompterbesar,size[MAXN+5],n,m,arr[2][MAXN+5][MAXN+5],versi[MAXN+5]={},ans,beda[MAXN+5],jauh[MAXN+5];
vector <int> edgelist;
void resetdisjoint(){				//yang akan dibagi jadi komponen itu yang menurun
	kompterbesar=1;
	for(int i=1;i<=n;i++)
	{
		par[i]=i;
		size[i]=1;
	}
}
int finds(int u){
	if(par[u]!=u)
		par[u]=finds(par[u]);
	return par[u];
}
void gabung(int u,int v){
	u=finds(u);
	v=finds(v);
	if(u==v)
		return;
	if(size[u]<size[v])
		swap(u,v);
	//yang jadi parent itu yang punya size lebih besar dan dipasikan u
	size[u]+=size[v];
	par[v]=u;

	//update komponen terbesar
	kompterbesar=max(kompterbesar,size[u]);
}
void updateans(int calonans){
	ans=max(ans,calonans);
}
void buatarrinvers(){
	for(int i=1;i<=n;i++)
		for(int j=1;j<=m;j++)
			arr[1][i][j]=arr[0][i][j]^1;
}
void tentukanversi(int kolom){		//menentukan bentuk invers atau tidak yang di pake
	versi[1]=0;
	for(int i=2;i<=n;i++)
	{
		versi[i]=0;
		if(arr[versi[i]][i][kolom]!=arr[versi[i-1]][i-1][kolom])
			versi[i]=1;
	}
}
void updatebeda(int kolom){			//memperbaiki nilainya beda sama yang diatasnya
	for(int i=2;i<=n;i++)
	{
		if(beda[i]<=kolom)
			beda[i]=kolom+1;
		while(beda[i]<=m&&(arr[versi[i-1]][i-1][beda[i]]==arr[versi[i]][i][beda[i]]))
			beda[i]++;
	}
}
void isijauh(int kolom){			//isi jauh nya beda sama dia
	for(int i=2;i<=n;i++)
		jauh[i]=beda[i]-kolom;
}
bool cmpbeda(int a,int b){			//menentukan urutan edgelist sort dari yang paling jauh
	return (jauh[a]>jauh[b]);
}
int main()
{
	scan(n,m);
	ans=max(n,m);
	for(int i=1;i<=n;i++)			//baca input;
	{
		char input[m];
		scanf("%s",&input);
		for(int j=0;j<m;j++)			//0-based jadi 1-based
			arr[0][i][j+1]=(input[j]=='#')?1:0;
	}

	edgelist.resize(n-1);			//inisialisasi edgelist
	for(int i=0;i<edgelist.size();i++)
		edgelist[i]=i+2;

	buatarrinvers();
	memset(beda,-1,sizeof(beda));			//posisi beda pertamanya anggap dulu tidak ada
	for(int i=1;i<=m;i++)			//proses
	{
		tentukanversi(i);			//buat mereka angka depannya sama
		resetdisjoint();
		updatebeda(i);
		isijauh(i);
		sort(all(edgelist),cmpbeda);
		/*for(int i=1;i<=n;i++)
			cout<<versi[i]<<endl;
		cout<<endl<<endl;
		cout<<"ohahahage "<<beda[2]<<endl;*/
		for(auto v:edgelist)
		{
			gabung(v,v-1);
			updateans(kompterbesar*jauh[v]);
		}
	}
	cout<<ans<<endl;
}

