const int N=2005;
int n,m,up[N],ch[N],ans,qu[N],qr;

int main(){
	scanf("%d%d",&n,&m);
	ans=max(n,m);
	for(int i=1;i<=n;i++){
		int a=get(),b;
		qr=0;
		for(int x=1;x<m;x++){
			b=get();
			if((a==b)!=ch[x])ch[x]^=1,up[x]=0;
			up[x]++,a=b;
			while(qr&&up[qu[qr]]>up[x])qu[qr--]=0;
			qu[++qr]=x;
			ans=max(ans,up[x]*2);
			if(up[qu[qr-1]]*(x+1)<=ans)continue;
			for(register int k=1;k<=qr;k++)ans=max(ans,up[qu[k]]*(x+1-qu[k-1]));
		}
	}
	printf("%d\n",ans);
	return 0;
}

