    rep(i,H) cin>>S[i];

    ans=max(H,W);
    FOR(i,1,H){
        stack<pii> stc;
        stc.push({0,0});
        FOR(j,1,W){
            if(ck(i,j)) hig[j]++;
            else hig[j]=0;
            int h=stc.top().first;
            int w=stc.top().second;
            int ww=0;
            while(h>hig[j]){
                ww+=w;
                chmax(ans,(h+1)*(ww+1));
                stc.pop();
                h=stc.top().first;
                w=stc.top().second;
            }
            if(h<hig[j]){
                stc.push({hig[j],1+ww});
            }else{
                stc.top().second+=1+ww;
            }
        }
        int ww=0;
        while(!stc.empty()){
            int h=stc.top().first;
            int w=stc.top().second;
            ww+=w;
            chmax(ans,(h+1)*(ww+1));
            stc.pop();
        }
    }
    cout1(ans)
}

