int top[maxn][maxn];
int stk[maxn],tp;
int high[maxn],L[maxn],R[maxn];


void work()
{
    while(~scanf("%d%d",&n,&m))
    {
        for(int i=1;i<=n;i++) scanf("%s",ss[i]+1);

        for(int i=1;i<=n;i++)
            for(int j=1;j<=m;j++)
                a[i][j] = ss[i][j]=='#';

        for(int i=1;i<=n-1;i++)
            for(int j=1;j<=m-1;j++)
                b[i][j] = a[i][j]^a[i+1][j]^a[i][j+1]^a[i+1][j+1];

        for(int j=1;j<=m-1;j++) top[n][j]=n;
        for(int i=n-1;i>=1;i--)
            for(int j=1;j<=m-1;j++)
                top[i][j] = b[i][j] ? i : top[i+1][j] ;

        LL ans=0;
        for(int i=1,ni;i<=n-1;i=ni+1)
        {
            ni=INF;
            for(int j=1;j<=m-1;j++) high[j]=top[i][j]-i+1, Min(ni,top[i][j]);

            tp=0;
            for(int j=1;j<=m-1;j++)
            {
                while(tp && high[stk[tp]]>=high[j]) tp--;
                L[j] = tp ? stk[tp]+1 : 1 ;
                stk[++tp]=j;
            }

            tp=0;
            for(int j=m-1;j>=1;j--)
            {
                while(tp && high[stk[tp]]>=high[j]) tp--;
                R[j] = tp ? stk[tp] : m ;
                stk[++tp]=j;
            }

            for(int j=1;j<=m-1;j++) Max(ans,(LL)high[j]*(R[j]-L[j]+1));
        }

        Max(ans,(LL)max(n,m));

        printf("%lld\n",ans);
    }
}

