const int INF = 1<<28;
const double EPS = 1e-8;
const int MOD = 1000000007;


int T, h, w;

int max_rect(vi &data){
    data.push_back(0);
    vector<pii> q;
    q.emplace_back(0, -1);
    int res = 0;
    for (int i = 0; i < data.size(); ++i) {
        int ni = i;
        int x = data[i];
        while(!q.empty() && q.back().first >= x) {
            int y, j; tie(y, j) = q.back(); q.pop_back();
            res = max(res, y * (i - j + 1));
            ni = j;
        }
        q.emplace_back(x, ni);
    }
    return res;
}

int main(int argc, char *argv[]){
    ios::sync_with_stdio(false);
    scanf("%d%d", &h, &w);
    vector<vi> raw(h, vi(w));
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            char c;
            scanf(" %c", &c);
            raw[i][j] = c == '#';
        }
    }
    int ans = max(h, w);
    vector<vi> data(w, vi(h));
    for (int i = 1; i < h; ++i) {
        int p1 = 0, p2 = 0;
        for (int j = (int) w - 1; j >= 0; --j) {
            if (raw[i][j] == raw[i-1][j]) {
                p1 = 0;
                p2 ++;
            } else {
                p1 ++;
                p2 = 0;
            }
            data[j][i] = max(p1, p2);
        }
    }
    for (int j = 0; j < w; ++j) {
        ans = max(ans, max_rect(data[j]));
    }
    cout << ans << endl;
    return 0;
}

