int mxl[NM_MAX];
int mxr[NM_MAX];

stack <int> st;

int main()
{
    cin >> n >> m;
    for(int i = 1; i <= n; i++)
    {
        string s;
        cin >> s;
        for(int j = 1; j <= m; j++)
            ma[i][j] = (s[j - 1] == '#');
    }
    for(int i = 1; i < n; i++)
        for(int j = 1; j < m; j++)
            ma[i][j] = ma[i][j] ^ ma[i + 1][j] ^ ma[i][j + 1] ^ ma[i + 1][j + 1];
    n--;
    m--;
    for(int i = n; i >= 1; i--)
        for(int j = 1; j <= m; j++)
            if(ma[i][j] == 1)
                lg[i][j] = 0;
            else
                lg[i][j] = lg[i + 1][j] + 1;
    int ans = max(n, m) + 1;
    for(int i = 1; i <= n; i++)
    {
        for(int j = 1; j <= m; j++)
            v[j] = lg[i][j];
        for(int j = 1; j <= m; j++)
        {
            mxl[j] = 0;
            while(!st.empty() && v[st.top()] > v[j])
            {
                mxl[j] = j - st.top();
                st.pop();
            }
            if(st.empty())
                mxl[j] = j - 1;
            if(!st.empty() && v[st.top()] == v[j])
                mxl[j] = j - st.top();
            else
                st.push(j);
        }
        while(!st.empty())
            st.pop();
        for(int j = m; j >= 1; j--)
        {
            mxr[j] = 0;
            while(!st.empty() && v[st.top()] > v[j])
            {
                mxr[j] = st.top() - j;
                st.pop();
            }
            if(st.empty())
                mxr[j] = m - j;
            if(!st.empty() && v[st.top()] == v[j])
                mxr[j] = st.top() - j;
            else
                st.push(j);
        }
        while(!st.empty())
            st.pop();
        for(int j = 1; j <= m; j++)
            ans = max(ans, (mxl[j] + mxr[j] + 2) * (v[j] + 1));
    }
    cout << ans << "\n";
    return 0;
}

