struct Hoge{
    set<int> points;
    multiset<int> intervals;
    Hoge(){
        points.insert(-1);
        points.insert(m-1);
        intervals.insert(m);
    }

    void init(){
        points.clear();
        intervals.clear();
        points.insert(-1);
        points.insert(m-1);
        intervals.insert(m);
    }
    void add(int x){
        if(points.count(x))return;
        auto it = points.lower_bound(x);
        int bef = *prev(it), nxt = *it;
        intervals.erase(intervals.find(nxt - bef));
        intervals.insert(nxt - x);
        intervals.insert(x - bef);
        points.insert(x);
    }
