int get(int n, int m) {
    int ans = 0;
    for (int j = 0; j < m; ++j) {
        h[j] = 0;
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            //out << c[i][j];
            if (c[i][j]) {
                ++h[j];
            } else {
                h[j] = 0;
            }
        }
        //cout << endl;
        vector <int> st;
        for (int j = 0; j < m; ++j) {
            nxt[j][1] = m;
            while (st.size()) {
                if (h[st.back()] > h[j]) {
                    nxt[st.back()][1] = j;
                    st.pop_back();
                } else {
                    break;
                }
            }
            st.pb(j);
        }
        st.clear();
        for (int j = m; j--;) {
            nxt[j][0] = -1;
            while (st.size()) {
                if (h[st.back()] > h[j]) {
                    nxt[st.back()][0] = j;
                    st.pop_back();
                } else {
                    break;
                }
            }
            st.pb(j);
        }
        st.clear();
        for (int j = 0; j < m; ++j) {
            int S = (nxt[j][1] - nxt[j][0]) * h[j];
            //cout << nxt[j][1] - nxt[j][0] - 1 << ' ' << h[j] << endl;
            chkmax(ans, S);
        }
    }
    //cout << ans << endl;
    return ans;
}

void f(int L, int R) {
    if (R - L <= 1) {
        return;
    }
    int M = (L + R) >> 1;
    for (int i = L; i < R; ++i) {
        for (int j = 0; j + 1 < m; ++j) {
            if ((arr[i][j] ^ arr[M][j]) == (arr[i][j + 1] ^ arr[M][j + 1])) {
                c[i - L][j] = 1;
            } else {
                c[i - L][j] = 0;
            }
        }
    }
    chkmax(ans, get(R - L, m - 1));
    f(L, M);
    f(M + 1, R);
}

