template <typename T> T max_rectangle_in_histogram(const vector<T> &h){
  stack<pair<T,int>> st;
  T ret = 0;

  REP(i,(int)h.size()){
    if(st.empty()) st.push({h[i],i});
    else if(st.top().fst < h[i]) st.push({h[i],i});
    else if(st.top().fst > h[i]){
      int j = i;
      while(not st.empty() and st.top().fst > h[i]){
	chmax(ret, (st.top().fst+1) * (T)(i-st.top().snd+1));
