using namespace std;
using ll = long long;
template<typename T,typename U> using P = pair<T,U>;
template<class T> using vec = vector<T>;
template<class T> using vvec = vector<vec<T>>;

int largest_rectangle(vector<int>& A){
    int N = A.size();
    int ans = 0;
    stack<P<int,int>> s;
    for(int i=0;i<N;i++){
        int pos = i;
        while(!s.empty() && s.top().first>=A[i]){
            P<int,int> p = s.top(); s.pop();
            ans = max(ans,p.first*(i-p.second+1));
            pos = p.second;
        }
        s.push({A[i],pos});
    }
    return ans;
}

