inline void solve()
{
	if(n == 1) { printf("%d\n", m); return; }
	if(m == 1) { printf("%d\n", n); return; }

	static int B[MAXN + 5][MAXN + 5];
	for(int i = 1; i < n; ++i) for(int j = 1; j < m; ++j)
		B[i][j] = (A[i][j] + A[i + 1][j] + A[i][j + 1] + A[i + 1][j + 1]) % 2 == 0;

	--n, --m;

	static int h[MAXN + 5][MAXN + 5];

	for(int j = 1; j <= m; ++j)
		for(int i = 1; i <= n; ++i)
			h[i][j] = B[i][j] == 0 ? 0 : h[i - 1][j] + 1;

	int ans = 0;
	for(int i = 1; i <= n; ++i)
	{
		static int l[MAXN + 5], r[MAXN + 5];

		static vector<int> S;
		S.clear();

		for(int j = 1; j <= m; ++j)
		{
			while(!S.empty() && h[i][S.back()] >= h[i][j]) S.pop_back();
			l[j] = S.empty() ? 1 : S.back() + 1;
			S.push_back(j);
		}

		S.clear();
		for(int j = m; j; --j)
		{
			while(!S.empty() && h[i][S.back()] >= h[i][j]) S.pop_back();
			r[j] = S.empty() ? m : S.back() - 1;
			S.push_back(j);
		}

 		for(int j = 1; j <= m; ++j) chkmax(ans, (h[i][j] + 1) * (r[j] - l[j] + 1 + 1));
	}
	printf("%d\n", ans);
}

int main()
{

	input();
	solve();

	return 0;
}

