			char x;cin >> x;
			if(x == '#')grid[i][j] = 1;
		}
	}
	//長方形の内部にある格子点が「良い正方形の中心」なら白、そうでなければ黒とする長方形を構成する
	for (int i = 0; i < h-1; i++)
	{
		for (int j = 0; j < w-1; j++)
		{
			for (int dx = 0; dx <= 1; dx++) {
				for (int dy = 0; dy <= 1; dy++) {
					good[i][j]^=grid[i+dx][j+dy];
				}
			}
		}
	}
	//構成された新しい長方形に対して、まずは各点について上に何マス連続で白があるかを数える
	for (int j = 0; j < w-1; j++)
	{
		int cum = 1;
		for (int i = 0; i < h-1; i++)
		{
			if(good[i][j] == 0) hist[i][j] = cum++;
			else cum = 1;
		}
	}
	//各行についてヒストグラムに対する最大長方形のアルゴリズムを適用して、最大の面積を求める
	for (int i = 0; i < h-1; i++)
	{
		stack<dat> s;
		int last_left = 0;
		for (int j = 0; j < w; j++)
		{
			if (s.empty()) {
				dat d = {j,hist[i][j]};
				s.push(d);
			}
			else if (hist[i][j] > s.top().height) {
				dat d = {j,hist[i][j]};
				s.push(d);
			}
			else if (hist[i][j] < s.top().height) {
				while (!s.empty() and s.top().height > hist[i][j]) {
					maxs(ans,(j - s.top().pos + 1)*(s.top().height + 1)); //問題の答えを直接求める：辺の長さ+1に注意
					last_left  = s.top().pos;
					s.pop();
				}
				dat d = {last_left,hist[i][j]};
				s.push(d);
			}
		}
	}
	cout << max(1,ans) << endl;
	return 0;
}

