    int ret = 0;
    for(int i = 0; i < H; i++) {
        while(!st.empty()) st.pop();
        for(int j = 0; j <= W; j++) {
            while(!st.empty() && dp[i][ st.top() ] > (j == W? 0 : dp[i][j])) {
                int t = st.top(); st.pop();
                int d = st.empty()? -1 : st.top();
                ret = max(ret, (j - d) * (dp[i][t] + 1));
            }
            st.push(j);
        }
