const int N = 2003;
int r, c, arr[N][N], same_conseq[N][N][2];

int getMaxArea(const vector<int> &hist, int n)
{
    // Create an empty stack. The stack holds indexes of hist[] array
    // The bars stored in stack are always in increasing order of their
    // heights.
    stack<int> s;

    int max_area = 0; // Initalize max area
    int tp;  // To store top of stack
    int area_with_top; // To store area with top bar as the smallest bar

    // Run through all bars of given histogram
    int i = 0;
    while (i < n)
    {
        // If this bar is higher than the bar on top stack, push it to stack
        if (s.empty() || hist[s.top()] <= hist[i])
            s.push(i++);

        // If this bar is lower than top of stack, then calculate area of rectangle 
        // with stack top as the smallest (or minimum height) bar. 'i' is 
        // 'right index' for the top and element before top in stack is 'left index'
        else
        {
            tp = s.top();  // store the top index
            s.pop();  // pop the top

            // Calculate the area with hist[tp] stack as smallest bar
            area_with_top = hist[tp] * (s.empty() ? i : i - s.top() - 1);

            // update max area, if needed
            if (max_area < area_with_top)
                max_area = area_with_top;
        }
    }

    // Now pop the remaining bars from stack and calculate area with every
    // popped bar as the smallest bar
    while (s.empty() == false)
    {
        tp = s.top();
        s.pop();
        area_with_top = hist[tp] * (s.empty() ? i : i - s.top() - 1);

        if (max_area < area_with_top)
            max_area = area_with_top;
    }

    return max_area;
}


int main(){

    ios_base::sync_with_stdio(0);
    cin.tie(0);

    cin>>r>>c;
    char str[N];
    for(int i=1;i<=r;i++){
    	cin>>(str+1);
    	for(int j=1;j<=c;j++)
    		arr[i][j] = (str[j] == '.' ? 0 : 1);
    }


    for(int j=c;j>=1;j--)
    	same_conseq[1][j][0] = same_conseq[1][j][1] = c-j+1;
    for(int i=2;i<=r;i++)
    	for(int j=c;j>=1;j--){
    		same_conseq[i][j][0] = (arr[i][j] == arr[i-1][j]) * (1 + same_conseq[i][j+1][0]);
    		same_conseq[i][j][1] = (arr[i][j] != arr[i-1][j]) * (1 + same_conseq[i][j+1][1]);
    	}

    int ans = max(r, c);
    for(int j=1;j<=c;j++){
    	vector<int> vals;
    	vals.pb(c-j+1);
    	for(int i=2;i<=r;i++)
    		if(arr[i][j] == arr[i-1][j])
    			vals.pb(same_conseq[i][j][0]);
    		else
    			vals.pb(same_conseq[i][j][1]);

    	ans = max(ans, getMaxArea(vals, r));
    }

    cout<<ans;
    return 0;
}

