// largest rectangle in histogram
int calc(const vector<int> &h)
{
    int n = h.size();
    vector<int> L(n),R(n),st(n);

    int t=0;
    rep(i,n)
    {
        while(t>0 && h[st[t-1]]>=h[i]) --t;
        L[i] = (t==0?0:st[t-1]+1);
        st[t++] = i;
    }

    t = 0;
    for(int i=n-1; i>=0; --i)
    {
        while(t>0 && h[st[t-1]]>=h[i]) --t;
        R[i] = (t==0?n:st[t-1]);
        st[t++] = i;
    }

    int ret = 0;
    rep(i,n) ret = max(ret, (h[i]+1)*(R[i]-L[i]+1));
    return ret;
}

