/*
进行列的翻转操作之后，合法的矩形一定满足每一行的颜色都相等（无所谓黑白，因为可以有行操作来调整）
每一行颜色相等等价于该行任意相邻两个格子颜色相等，等价于两个格子对应的列的翻转情况是 / 否相等
相当于有一些限制，同时两个相邻格子对应的列在每一行的限制都相等 
故可以直接转化成一个最大子矩形问题 
*/

#include <stack>
#include <cstdio>
#include <algorithm>

using namespace std;
const int Max_NM(2050);

int N, M, rev[Max_NM][Max_NM], up[Max_NM][Max_NM];
char S[Max_NM];

void init()
{
	scanf("%d%d", &N, &M);
	for (int i = 1;i <= N;++i)
	{
		scanf("%s", S + 1);
		for (int j = 2;j <= M;++j)
			rev[i][j] = (S[j - 1] != S[j]), up[i][j] = (rev[i][j] == rev[i - 1][j] ? up[i - 1][j] : 0) + 1; 
	}
}

int L[Max_NM], R[Max_NM];
void work()
{
	int Ans(0);
	for (int i = 1;i <= N;++i)
	{
		stack<int> S;
		for (int j = 2;j <= M;++j)
		{
			while (S.empty() == false && up[i][S.top()] > up[i][j])
				R[S.top()] = j - 1, S.pop();
			S.push(j);
		}
		while (S.empty() == false)
			R[S.top()] = M, S.pop();
		for (int j = M;j >= 2;--j)
		{
			while (S.empty() == false && up[i][S.top()] > up[i][j])
				L[S.top()] = j + 1, S.pop();
			S.push(j);
		}
		while (S.empty() == false)
			L[S.top()] = 2, S.pop();
		for (int j = 2;j <= M;++j)
			Ans = max(Ans, up[i][j] * (R[j] - L[j] + 2));
	}
	printf("%d", Ans);
}

int main()
{
	init();
	work();
	return 0;
}

