void calcRPoint(int * A, int * B, int n) {
    static int S[N]; int top = 0;
    for (int i = 1; i <= n; ++i) {
        while (top > 0 && A[S[top]] > A[i])
            B[S[top--]] = i - 1;
        S[++top] = i;
    }
    for (int i = 1; i <= top; ++i) B[S[i]] = n;
}
int calcRow(int * A ,int n) {
