int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int m, n;
  cin >> m >> n;
  vector<vector<char>> dat(m, vector<char>(n));
  for (int i = 0; i < m; i++) {
    for (int j = 0; j < n; j++) {
      cin >> dat[i][j];
    }
  }
  vector<vector<int>> hst(m, vector<int>(n, 0));
  for (int i = 1; i < m; i++) {
    for (int j = 1; j < n; j++) {
      hst[i][j] =
          dat[i - 1][j - 1] ^ dat[i - 1][j] ^ dat[i][j - 1] ^ dat[i][j]
              ? 0
              : hst[i - 1][j] + 1;
    }
  }
  int ret = 0;
  for (int i = 1; i < m; i++) {
    stack<int> stk;
    for (int j = 1; j < n; j++) {
      int crr = hst[i][j];
      while (!stk.empty() && hst[i][stk.top()] > crr) {
        int prv = stk.top();
        stk.pop();
        chmax(ret, (hst[i][prv] + 1) * ((j - prv) + 1));
      }
      if (stk.empty() || hst[i][stk.top()] < crr) {
        stk.push(j);
