const int MAXN = 2010;
char mat[MAXN][MAXN];
bool arr[MAXN][MAXN];
int up[MAXN][MAXN];
int n, m;
int ans;
int st[MAXN], at[MAXN], top;
void pop(int x) {
	ans = std::max((st[top] + 1) * (x - at[top] + 1), ans);
	--top;
}
int main() {
	std::ios_base::sync_with_stdio(false), std::cin.tie(0);
	std::cin >> n >> m; ans = std::max(n, m);
	for (int i = 1; i <= n; ++i) {
