	}
	for (int i = 1; i < n; ++i)
		for (int j = 1; j < m; ++j) {
			arr[i][j] = (mat[i][j] + mat[i][j + 1] + mat[i + 1][j] + mat[i + 1][j + 1]) % 2 == 0;
			up[i][j] = arr[i][j] ? up[i - 1][j] + 1 : 0;
		}
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j <= m; ++j) {
			int t = up[i][j];
			while (t < st[top]) pop(j);
			if (t != st[top]) st[++top] = t, at[top] = j;
		}
		while (top) pop(n + 1);
	}
	std::cout << ans << std::endl;
	return 0;
}

