using namespace std;

int H,W;
char S[2500][2500];
int c[5000][5000];
int h[5000][5000];
int l[2500];
int r[2500];
int main() {
  scanf("%d%d", &H, &W);
  for(int i=0;i<H;++i) {
    scanf("%s", S[i]);
  }
  for(int i=0;i<H;++i) {
    for(int j=0;j<W;++j) {
      if (S[i][j]=='.') {
        S[i][j] = 0;
      } else {
        S[i][j] = 1;
      }
    }
  }
  for(int i=0;i<H-1;++i) {
    for(int j=0;j<W-1;++j) {
      int sum = S[i][j] + S[i+1][j] + S[i][j+1] + S[i+1][j+1];
      c[i*2+1][j*2+1] = sum % 2;
    }
  }
  W=W*2-1;
  H=H*2-1;
  for(int i=0;i<H;++i) {
    for(int j=0;j<W;++j) {
      if (c[i][j] == 1) {
        h[i][j] = 0;
      } else if (i==0 || c[i-1][j] == 1) {
        h[i][j] = 1;
      } else {
        h[i][j] = h[i-1][j] + 1;
      }
    }
  }
  long long answer = 0;
  for(int i=0;i<H;++i) {
    stack<int> S;
    for(int j=0;j<W;++j) {
      while(!S.empty() && h[i][S.top()] >= h[i][j]) S.pop();
      if (S.empty()) {
        l[j] = 0;
      } else {
        l[j] = S.top() + 1;
      }
      S.push(j);
    }
    S=stack<int>();
    for(int j=W-1;j>=0;--j) {
      while(!S.empty() && h[i][S.top()] >= h[i][j]) S.pop();
      if (S.empty()) {
        r[j] = W-1;
      } else {
        r[j] = S.top() - 1;
      }
      S.push(j);
    }

    for(int j=0;j<W;++j) {
      int w = r[j]-l[j] + 1;
      answer = max(answer, 1ll * (h[i][j] - h[i][j]/2) * (w - w/2));
    }
  }

  printf("%lld\n", answer);
  return 0;
}

