using namespace std;
typedef pair<int, int> P;

int main()
{
    int h, w;
    cin >> h >> w;
    string s[2005];
    for(int i = 0; i < h; i++) cin >> s[i];
    vector<int> v[2005];
    for(int i = 1; i < h; i++){
        for(int j = 1; j < w; j++){
            int c = 0;
            for(int x = i - 1; x <= i; x++){
                for(int y = j - 1; y <= j; y++){
                    if(s[x][y] == '.') c++;
                }
            }
            if(c % 2) v[i].push_back(j);
        }
    }
    int ans = 0;
    for(int i = 0; i < h; i++){
        priority_queue<P> que;
        set<int> st;
        st.insert(0);
        st.insert(w);
        int d[2005]{0};
        d[0] = w;
        que.push(P(w, 0));
        for(int k = i + 1; k <= h; k++){
            ans = max(ans, que.top().first * (k - i));
            for(int j : v[k]){
                auto itr = st.upper_bound(j);
                itr--;
                int l = *itr;
                if(j != l){
                    st.insert(j);
                    d[j] = d[l] - (j - l);
                    d[l] = j - l;
                    que.push(P(d[j], j));
                    que.push(P(d[l], l));
                }
            }
            while(que.size()){
                P p = que.top();
                if(d[p.second] == p.first) break;
                que.pop();
            }
        }
    }
    cout << ans << endl;
}

