inline void removePlace(int x)
{
	set <int> :: iterator it = zle.upper_bound(x);
	set <int> :: iterator sc = it;
	--sc;
	q.erase(q.find(- (*it) + (*sc)));
	zle.insert(x);
	q.insert(x - *it);
	q.insert(*sc - x);
}
int main()
{
	boost;
	cin.tie(0); cout.tie(0);
	cin >> n >> m;
	FOR(i, 1, n) cin >> s[i];
	FOR(i, 1, n)
		FOR(j, 1, m)
			if (s[i][j - 1] == '.') tab[i][j] = 0;
			else tab[i][j] = 1;

	FOR(i, 1, n)
		FOR(j, 1, m-1)
		{
			int tp = (tab[i][j] ^ tab[i][j + 1]);
			gdzie[j][tp].insert(i);
		}

	int wyn = max(n, m);
	FOR(i, 1, n)
	{
		zle.clear();
		FOR(j, 1, m-1)
			if (tab[i][j] == tab[i][j + 1]) typ[j] = 0;
			else typ[j] = 1;

		FOR(j, 0, n) toerase[j].clear();
		FOR(j, 1, m-1)
		{
			int w = (1 ^ typ[j]);
			set <int>::iterator it = gdzie[j][w].upper_bound(i);
			if (it == gdzie[j][w].end()) continue;
			else toerase[*it].pb(j);
		}
		zle.insert(m);
		zle.insert(0);

		q.clear();
		q.insert(-m);

		FOR(j, i + 1, n)
		{
			for (auto u : toerase[j]) removePlace(u);
			if (!q.empty()) wyn = max(wyn, -(*q.begin()) * (j - i + 1));
		}

	}

	cout << wyn;
}

