int best[Maxn][Maxn][2];
vector <int> proc[Maxn];
int par[Maxn], siz[Maxn], mx;
int res;

int getPar(int x) { return par[x] == x? x: par[x] = getPar(par[x]); }

void unionSet(int a, int b)
{
	a = getPar(a), b = getPar(b);
	if (a == b) return;
	if (siz[a] >= siz[b]) { siz[a] += siz[b]; par[b] = a; mx = max(mx, siz[a]); }
	else { siz[b] += siz[a]; par[a] = b; mx = max(mx, siz[b]); }
}

int main()
{
	scanf("%d %d", &R, &C);
	for (int i = 0; i < R; i++)
		scanf("%s", B[i]);
	for (int i = R - 1; i >= 0; i--)
		for (int j = 0; j + 1 < C; j++) {
			best[i][j][0] = B[i][j] == B[i][j + 1]? 1 + best[i + 1][j][0]: 0;
			best[i][j][1] = B[i][j] != B[i][j + 1]? 1 + best[i + 1][j][1]: 0;
		}
	res = R;
	for (int i = 0; i < R; i++) {
		for (int j = 0; j < Maxn; j++)
			proc[j].clear();
		for (int j = 0; j + 1 < C; j++)
			if (B[i][j] == B[i][j + 1]) proc[best[i][j][0]].push_back(j);
			else proc[best[i][j][1]].push_back(j);
		for (int j = 0; j < C; j++) {
			par[j] = j; siz[j] = 1;
		}
		mx = 1;
		for (int j = Maxn - 1; j > 0; j--) if (!proc[j].empty()) {
			for (int k = 0; k < proc[j].size(); k++)
				unionSet(proc[j][k], proc[j][k] + 1);
			res = max(res, mx * j);
		}
	}
	printf("%d\n", res);
	return 0;
}

