i64 maxHist(int row[], int m){
    stack<int> result;
    i64 max_area = 0;
    int i = 0;
    while (i < m){
        if (result.empty() || row[result.top()] <= row[i])
            result.push(i++);
        else{
            int top_val = row[result.top()]; result.pop();
            i64 area = (i64)top_val * (i+1);
            if (!result.empty())
                area = (i64)top_val * (i - result.top() - 1 + 1 );

            max_area = max(area, max_area);
        }
    }
    while (!result.empty())    {
        int top_val = row[result.top()]; result.pop();
        i64 area = (i64)(top_val) * (i+1);
        if (!result.empty())
            area = (i64)(top_val) * (i - result.top() - 1+1);
        max_area = max(area, max_area);
    }
    return max_area;
}
i64 maxRectangle(int A[][MAX], int n, int m){
    i64 result = maxHist(A[0], m);
    for (int i = 1; i < n; i++){
        for (int j = 0; j < m; j++)
            if (A[i][j]) A[i][j] += A[i - 1][j];
        result = max(result, maxHist(A[i], m));
    }
    return result;
}


