static const int MAXN = 2004;

int n, m;
bool a[MAXN][MAXN];
bool b[MAXN][MAXN] = {{ false }};

int f[MAXN][MAXN];
int s[MAXN], top;

int main()
{
    scanf("%d%d", &n, &m);
    for (int i = 0; i < n; ++i) {
        getchar();
        for (int j = 0; j < m; ++j)
            a[i][j] = (getchar() == '#' ? 1 : 0);
    }

    for (int i = 0; i < n - 1; ++i)
        for (int j = 0; j < m - 1; ++j)
            b[i][j] = a[i][j] ^ a[i][j + 1] ^ a[i + 1][j] ^ a[i + 1][j + 1];

    for (int i = 0; i < n - 1; ++i)
        for (int j = 0; j < m - 1; ++j)
            if (b[i][j]) f[i][j] = 0;
            else f[i][j] = 1 + (i == 0 ? 0 : f[i - 1][j]);

    int ans = 1;
    for (int i = 0; i < n - 1; ++i) {
        s[0] = 0; top = 1;
        for (int j = 1; j < m - 1; ++j) {
            while (top > 0 && f[i][s[top - 1]] > f[i][j]) {
                ans = std::max(ans, (f[i][s[top - 1]] + 1) * (j - s[top - 1] + 1));
                --top;
            }
