struct ucs
{
	int q[N],w[N];
	void init(int n){for(int i=1;i<=n;i++)q[i]=i,w[i]=1;}
	int ask(int p){return p==q[p]?p:q[p]=ask(q[p]);}
	void uni(int u,int v)
	{
		int fu=ask(u),fv=ask(v);
		w[fv]+=w[fu];
		q[fu]=fv;
	}
	int query(int p){return w[ask(p)];}
}A[N],B[N];

