int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    auto solve=[](vector<string> S) {
        int N = S.size();
        int M = S[0].size();
        int ret = 0;
        vector<vector<int>> A(N, vector<int>(M-1,1));
        rep(i,N-1) {
            rep(j,M-1) {
                int a = S[i][j]==S[i][j+1];
                int b = S[i+1][j]==S[i+1][j+1];
                if (a^b) continue;
                A[i+1][j] = A[i][j]+1;
            }
        }
        rep(i,N) {
            vector<pii> sta;
            rep(j,M-1) {
                if (!sta.empty() and A[i][j] < sta.back().first) {
                    while (!sta.empty() and sta.back().first > A[i][j]) {
                        auto[h,x] = sta.back(); sta.pop_back();
                        chmax(ret,h*(j-x+1));
                    }                
                }
                if (sta.empty() or A[i][j] > sta.back().first) {
                    sta.emplace_back(A[i][j],j);
                }
            }
            while (!sta.empty()) {
                auto[h,x] = sta.back(); sta.pop_back();
                chmax(ret,h*(M-1-x+1));
            }
        }

        return ret;
    };

    int N,M; cin >> N >> M;
    vector<string> S(N);
    rep(i,N) cin >> S[i];

    int ans = solve(S);
    vector<string> T(M, string(N,' '));
    rep(i,N) rep(j,M) T[j][i] = S[i][j];
    chmax(ans,solve(T));

    cout << ans << ln;
}

