inline int calc(int n, int m) {
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= m; ++j) r[i][j] = l[i][j] = j, u[i][j] = 1;
    for (int i = 1; i <= n; ++i)
        for (int j = 2; j <= m; ++j) {
            if (x[i][j] == 1) continue;
            if (! x[i][j - 1]) l[i][j] = l[i][j - 1];
        }
    for (int i = 1; i <= n; ++i)
        for (int j = m - 1; j; --j) {
            if (x[i][j]) continue;
            if (! x[i][j + 1]) r[i][j] = r[i][j + 1];
        }
    for (int i = 1; i <= m; ++i) up(ans, 2 * (r[1][i] - l[1][i] + 2));
    for (int i = 2; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (x[i][j]) continue;
            if (! x[i - 1][j]) {
                up(l[i][j], l[i - 1][j]);
                down(r[i][j], r[i - 1][j]);
                u[i][j] = u[i - 1][j] + 1;
                up(ans, (u[i][j] + 1) * (r[i][j] - l[i][j] + 2));
            }

        }
    }
}
