  }

  vector<vector<int>> dp1 = Make2DVector(h - 1, w, -1);
  for (int r = 0; r < h - 1; r++) {
    int current = -1;
    for (int c = w - 1; c >= 0; c--) {
      if (c == w - 1) {
        current = board[r][c] == board[r + 1][c];
        dp1[r][c] = 1;
      } else {
        if ((board[r][c] == board[r + 1][c]) == current) {
          dp1[r][c] = dp1[r][c + 1] + 1;
        } else {
          current = board[r][c] == board[r + 1][c];
          dp1[r][c] = 1;
        }
      }
    }
  }

  if (DEBUG) {
    for (int r = 0; r < h - 1; r++) {
      cout << "dp1[" << r << "]: " << dp1[r] << endl;
    }
  }

