int b[maxn][maxn];

int maxHist(int row[], int C)
{
    stack<int> result;

    int top_val;

    int max_area = 0;

    int area = 0;

    int i = 0;
    while (i < C)
    {
        if (result.empty() || row[result.top()] <= row[i])
            result.push(i++);

        else
        {
            top_val = row[result.top()];
            result.pop();
            area = (top_val + 1) * (i + 1);

            if (!result.empty())
                area = (top_val + 1) * (i - result.top() - 1 + 1);
            max_area = max(area, max_area);
        }
    }

    while (!result.empty())
    {
        top_val = row[result.top()];
        result.pop();
        area = (top_val + 1) * (i + 1);
        if (!result.empty())
            area = (top_val + 1) * (i - result.top() - 1 + 1);

        max_area = max(area, max_area);
    }
    return max_area;
}

int maxRectangle(int A[][maxn], int R, int C)
{
    int result = maxHist(A[0], C);
    for (int i = 1; i < R; i++)
    {

        for (int j = 0; j < C; j++)
            if (A[i][j]) A[i][j] += A[i - 1][j];
        result = max(result, maxHist(A[i], C));
    }

    return result;
}

void solve() {
    cin >> n >> m;
    FOR(i, 0, n) {
        string s; cin >> s;
        FOR(j, 0, m) a[i][j] = s[j] == '#';
    }
    FOR(i, 0, n - 1) FOR(j, 0, m - 1) {
        b[i][j] = a[i][j] ^ a[i + 1][j] ^ a[i][j + 1] ^ a[i + 1][j + 1] ^ 1;
    }
    int ans = max(n, m);
    chkmax(ans, maxRectangle(b, n - 1, m - 1));
    cout << ans << "\n";
}

