int slv(vector<vector<bool>>&C, int H, int W) {
	vector<vector<int>>cnt(H, vector<int>(W-1));
	REP(j, W-1) {
		REP(i, H) {
			if (C[i][j] == 0)cnt[i][j] = 0;
			else {
				if (i == 0)cnt[i][j] = 1;
				else cnt[i][j] = cnt[i - 1][j] + 1;
			}
		}
	}
	//REP(i, H) {
	//	REP(j, W - 1) {
	//		cout << cnt[i][j] << " ";
	//	}cout << endl;
	//}
	ll ret = H;
	REP(i, H) {
		stack<pii>stk;
		REP(j, W - 1) {
			if (stk.empty()) {
				stk.push({ cnt[i][j],j });
			}
			else {
				pii p = stk.top();
				if (p.first < cnt[i][j])stk.push({ cnt[i][j],j });
				else if (p.first > cnt[i][j]) {
					int r = j+1;
					int h = p.first;
					int pos = j;
					while (!stk.empty()&&h >= cnt[i][j]) {
						pii now = stk.top();
						h = now.first;
						if (h < cnt[i][j])break;
						pos = now.second;
						chmax(ret, h*(r - pos));
						stk.pop();
					}
					stk.push({ cnt[i][j],pos });
				}
			}
		}
		int r = W;
		while (!stk.empty()) {
			pii now = stk.top();
			int h = now.first, pos = now.second;
			chmax(ret, h*(r - pos));
			stk.pop();
		}
	}
	return ret;
}

