	std::vector<std::vector<int>> a(h + h - 1, std::vector<int>(w + w - 1, 0));
	auto b(a);
	int dx4[] = { -1,-1,1,1 };
	int dy4[] = { -1,1,-1,1 };
	REP(i, h - 1) REP(j, w - 1) {
		int I = i + i + 1;
		int J = j + j + 1;
		REP(d, 4) {
			int dy = I + dy4[d];
			int dx = J + dx4[d];
			a[I][J] += c[dy/2][dx/2] == '#';
		}
		a[I][J] %= 2;
	}
	REP(j, w + w - 1) b[0][j] = a[0][j] == 0;
	FOR(i, 1, h + h - 1) REP(j, w + w - 1) {
		if (a[i][j] == 1) continue;
		if (a[i - 1][j] == 1) b[i][j] = 1;
		else b[i][j] = b[i - 1][j] + 1;
	}
	int ans = 0;
	REP(i, h + h - 1) {
