inline void removePlace(int x)
{
	set <int> :: iterator it = zle.upper_bound(x);
	set <int> :: iterator sc = it;
	--sc;
	zliczaj[(*it) - (*sc)]--;
	zle.insert(x);
	zliczaj[*it - x]++;
	zliczaj[x - *sc]++;
}

inline int getMax() {
	int rz = m;
	while (rz && !zliczaj[rz]) --rz;
	return rz;
}

