const int kN = 2000 + 5;
int a[kN][kN], n, m;
char s[kN];

int work()
{
    int ret = std::max(n, m);
    int wall[kN] = {};
    std::fill(wall, wall + m, 1);
    for (int i = 1; i < n; ++ i) {
        for (int j = 1; j < m; ++ j) {
            if (a[i][j] == a[i - 1][j])
                wall[j] ++;
            else 
                wall[j] = 1;
        }
        std::vector<std::pair<int, int>> stack;
        for (int j = 1; j <= m; ++ j) {
            int rem = j;
            while (!stack.empty() && stack.back().second >= wall[j]) {
                int a = stack.back().first;
                int b = stack.back().second;
                stack.pop_back();
                ret = std::max(ret, (j - a + 1) * b);
                rem = a;
            }
            stack.emplace_back(rem, wall[j]);
        }
    }
    return ret;
}

