char str[N][N];

int n, m, t[N][N], s[N][N], ans, stk[N], top;

inline int Sqr(int a, int b) {
	return (a + 1) * (b + 1);
}

int l[N];
inline void Solve(int *h) {
	int len;
	stk[top = 0] = len = 0;
	For (i, 1, m) {
		if (h[i] >= stk[top])
			stk[++ top] = h[i], l[top] = 1;
		else {
			for (len = 0; top && stk[top] > h[i]; -- top)
				len += l[top], chkmax(ans, Sqr(len, stk[top]));
			stk[++ top] = h[i], l[top] = len + 1;
		}
	} 
	for (len = 0; top; -- top)
		len += l[top], chkmax(ans, Sqr(len, stk[top]));
}

