				a[i][j] = 0;
			}
			else{
				a[i][j] = 1;
			}
		}
	}
	for (int i = 1; i < h; i++){
		for (int j = 0; j < 2; j++){
			for (int k = 0; k < 2; k++){
				for (int kk = w - 1; kk >= 0; kk--){
					int w = ((a[i - 1][kk] ^ j) == (a[i][kk] ^ k));
					s[i][kk][j][k] = w;
					if (w){
						s[i][kk][j][k] += s[i][kk + 1][j][k];
					}
				}
			}
		}
	}
	for (int j = 0; j < w; j++){
		int ds = 0;
