                x[i-1][j-1] = c[i][j-1] == c[i][j] ? 1 : 0;
            }else{
                x[i-1][j-1] = c[i][j-1] != c[i][j] ? 1 : 0;
            }
        }
    }

    int dp[1010][1010] = {};
    for(int j = 0;j < w-1;j++){
        if(x[0][j] == 1) dp[0][j] = 1;
        for(int i = 1;i < h-1;i++){
            if(x[i][j] == 1){
                dp[i][j] += dp[i-1][j] + 1;
            }
        }
    }

    int ans = max(h, w);

    for(int i = 0;i < h-1;i++){
        stack<pair<int, int> > st;
        for(int j = 0;j < w;j++){
            pair<int, int> p;
            p.first = dp[i][j];
