	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if ((str[i][j] ^ str[i][j + 1] ^ str[i + 1][j] ^ str[i + 1][j + 1]) != ('#'^'.')) {
				sum[i][j] = 1;
			}
		}
