const pii operator - (pii x, pii y) {
  x.f -= y.f;
  x.s -= y.s;
  if (x.f < 0) 
    x.f += mod1;
  if (x.s < 0) 
    x.s += mod2;
  return x;
}

const pii operator + (pii x, pii y) {
  x.f += y.f;
  x.s += y.s;
  if (x.f >= mod1) 
    x.f -= mod1;
  if (x.s >= mod2) 
    x.s -= mod2;
  return x;
}

pii get_hash(int tr, int x, int l, int r) {
  return h[tr][x][r] - (l ? h[tr][x][l - 1] : mp(0, 0));
}

bool ok(int i, int j, int l, int r) {
  return get_hash(0, i, l, r) == get_hash(0, j, l, r)
        || get_hash(1, i, l, r) == get_hash(0, j, l, r);
}

int lo[N], hi[N];

void recalc(vec v) {
  stack<int> st;
  for (int i = 0; i < sz(v); i++) {
    while (!st.empty() && v[st.top()] >= v[i]) {
      hi[st.top()] = i;
      st.pop();
    }
    lo[i] = (st.empty() ? -1 : st.top());
    st.push(i);
  }
  while (!st.empty()) {
    hi[st.top()] = sz(v);
    st.pop();
  }
  for (int i = 0; i < sz(v); i++) {
    ans = max(ans, (hi[i] - lo[i]) * v[i]);
  }
}

void calc() {
  for (int l = 0; l < m; l++) {
    vec cur;
    for (int i = 1; i < n; i++) {
      int lo = 0, hi = m - 1 - l, f;
      while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (ok(i, i - 1, l, l + mid)) {
          f = mid + 1;
          lo = mid + 1;
        } else {
          hi = mid - 1;
        }
      }
      cur.pb(f);
    }
    recalc(cur);
  }
}

pii mult(int x, pii y) {
  return mp(y.f * 1ll * x % mod1, y.s * 1ll * x % mod2);
}

