void build(int v, int l, int r) {
	if (l == r) {
		t[v] = up[curRow][l];
		return;
	}
	int mid = (l + r) / 2;
	build(2 * v, l, mid);
	build(2 * v + 1, mid + 1, r);
	t[v] = min(t[2 * v], t[2 * v + 1]);
}

int get(int v, int l, int r, int wl, int wr) {
	if (wl > wr)
		return INF;
	if (wl == l && wr == r) {
		return t[v];
	}
	int mid = (l + r) / 2;
	return min(get(2 * v, l, mid, wl, min(mid, wr)), get(2 * v + 1, mid + 1, r, max(mid + 1, wl), wr));
}

