ll histogram_max_square(vector<ll> h) {

    h.push_back(0);
    using P = pair<ll, int>;
    stack<P> st;

    ll maxv = 0;

    for (int i = 0; i < h.size(); ++i) {
        if (st.empty()) {
            st.push(P(h[i], i));
            continue;
        }
        if (st.top().first < h[i]) {
            st.emplace(h[i], i);
            continue;
        }
        if (st.top().first > h[i]) {
            int target = i;
            while (true) {
                if (st.empty() || st.top().first < h[i]) {
                    break;
                }
                ll tmp = (i - st.top().second + 1) * (st.top().first + 1);
                chmax(maxv, tmp);
                target = st.top().second;
                st.pop();
            }
            st.emplace(h[i], target);
        }
    }
    return maxv;
}


