const int MAXH = 2010;
const int MAXW = 2010;
int H, W;
char G[MAXH][MAXW];

int height[MAXH][MAXW];

int par[MAXW];
int sz[MAXW];
int getpar(int a) {
	return par[a] == -1 ? a : (par[a] = getpar(par[a]));
}
bool merge(int a, int b) {
	a = getpar(a), b = getpar(b);
	if (a == b) return false;
	if (sz[a] < sz[b]) swap(a,b);
	par[b] = a;
	sz[a] += sz[b];
	return true;
}

int go(int r) {
	for (int i = 0; i < W; i++) {
		par[i] = -1;
		sz[i] = 1;
	}

	vector<pair<int, int>> cnds(W-1);
	for (int i = 0; i+1 < W; i++) {
		cnds[i] = {height[r][i], i};
	}
	sort(cnds.rbegin(), cnds.rend());

	int res = 0;
	for (auto cnd : cnds) {
		assert(merge(cnd.second, cnd.second+1));
		res = max(res, cnd.first * sz[getpar(cnd.second)]);
	}
	return res;
}

