				height[i][j] = 1;
			} else {
				height[i][j] = (((G[i][j] == G[i][j+1]) == (G[i+1][j] == G[i+1][j+1])) ? height[i+1][j] + 1 : 1);
			}
		}
	}

	int ans = max(H, W);
	for (int i = 0; i < H; i++) {
		ans = max(ans, go(i));
	}
	cout << ans << '\n';

	return 0;
}

