	for(int i = 0; i < h - 1; i++){
		for(int j = 0; j < w - 1; j++){
			for(int k = 0; k < 2; k++){
				for(int l = 0; l < 2; l++){
					if(s[i + k][j + l] == '#') dp[i][j]++;
				}
			}
			dp[i][j] = !(dp[i][j] & 1);
