				st.emplace(dp[i][j]);
				continue;
			}
			for(int64_t x = 1; !st.empty() && dp[i][j] < st.top(); x++){
				int64_t h = st.top();
				st.pop();
				ans = max(ans, (x + 1) * (h + 1));
				ans = max(ans, (x + 2) * (dp[i][j] + 1));
			}
			st.emplace(dp[i][j]);
		}
