long long get(vector<int> &v){
	stack<int> st;
	int n = v.size(); 
	int ans = 0, i = 0;
	while(i < n){
		if(st.empty() || v[st.top()] <= v[i]){
			st.push(i++);
		}else {
			int x = st.top();
			st.pop();
			ans = max(ans, (v[x] + 1) * (st.empty() ? i + 1 : i - st.top()));
		}
	}
	while(!st.empty()){
		int x = st.top();
		st.pop();
		ans = max(ans, (v[x] + 1) * (st.empty() ? i + 1 : i - st.top()));
	}
	return ans;
}

