				Left[i] = sta.empty() ? -1 : sta.top();
				sta.push(i);
			}
			while (!sta.empty()) {
				Right[sta.top()] = W;
				sta.pop();
			}
			for (int i = 0; i < W; i ++) ans = max(ans, (Right[i] - Left[i]) * (RowGood[i] + 1));
		}
	printf("%d\n", ans);
	return 0;
}

