    for(int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<vector<int>> dp(n, vector<int> (m, 0)), dp_flip(n, vector<int> (m, 0));

    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < m - 1; ++j) {
            if(a[i][j] == a[i][j + 1]) {
                dp[i][j] = 1;
                dp_flip[i][j] = 0;
                if(i - 1 >= 0) {
                    dp[i][j] += dp[i - 1][j];
                }
            } else {
                dp[i][j] = 0;
                dp_flip[i][j] = 1;
                if(i - 1 >= 0) {
                    dp_flip[i][j] += dp_flip[i - 1][j];
                }
            }
        }
    }

    for(int i = 0; i < n; ++i)
        for(int j = 0; j < m; ++j)
            dp[i][j] = max(dp[i][j], dp_flip[i][j]);

    int ans = max(n, m);

    for(int i = 0; i < n; ++i) {
        ans = max(ans, solve(dp[i]));
    }

    cout << ans << "\n";
}

