using namespace std;

const int MAX_N = 2e3 + 5;

string grid [MAX_N];
int lbrk [MAX_N]; // last break between positions (i) and (i + 1)

bool same (char c, char d) {
  return c == d;
}

int main () {
  ios::sync_with_stdio(false);

  int n, m;
  cin >> n >> m;
  for (int i = 0; i < n; i++) {
    cin >> grid[i];
  }

  for (int i = 0; i < m; i++) {
    lbrk[i] = -1;
  }

  int ans = m;
  for (int i = 1; i < n; i++) {
    // add the i-th row and make it clear
    for (int j = 0; j < m - 1; j++) {
      if (same(grid[i - 1][j], grid[i][j]) != same(grid[i - 1][j + 1], grid[i][j + 1])) {
        lbrk[j] = i - 1;
      }
    }

    vector<pair<int, int>> breaks; // <lbrk[i], i>
    for (int j = 0; j < m - 1; j++) {
      if (lbrk[j] != -1) {
        breaks.push_back(make_pair(lbrk[j], j));
      }
    }

    if (breaks.empty()) {
      ans = max(ans, m * (i + 1));
    } else {
      sort(breaks.begin(), breaks.end());
      reverse(breaks.begin(), breaks.end());

      ans = max(ans, m * (i - breaks[0].first));      

      vector<pair<int, vector<int>>> blocks;
      for (auto pr : breaks) {
        if (blocks.empty() || pr.first != blocks.back().first) {
          blocks.push_back(make_pair(pr.first, vector<int> (0)));
        }
        blocks.back().second.push_back(pr.second);
      }

      set<int> walls;
      walls.insert(-1);
      walls.insert(m);
      for (pair<int, vector<int>> block : blocks) {
        for (int w : block.second) {
          walls.insert(w);
        }

        for (int w : block.second) {
          int lw = *prev(walls.find(w));
          int rw = *next(walls.find(w));

          ans = max(ans, (w - lw) * (i - block.first));
          ans = max(ans, (rw - w) * (i - block.first));
        }
      }
    }
  }

  cout << ans << endl;
}

