	if (f[x] == x) return x;
	else return f[x] = F(f[x]);
}
int merge(int x, int y) {
	int tx = F(x);
	int ty = F(y);
	f[tx] = ty;
	size[ty] += size[tx];
	return size[ty];
}
int calc(int pos) {
	static vector <int> a[MAXN];
