        for(int j = 0; j < w; j++){
			if(a[i][j]) t[i+1][j] = 0;
			else t[i+1][j] = t[i][j] + 1;
		}
		t[i+1][w] = 0;
		stack<pair<int, int> > st;
		for(int j = 0; j <= w; j++){
			if(st.empty()){
				st.push({j, t[i+1][j]});
				continue;
			}
			pair<int, int> p = st.top();
			if(p.second < t[i+1][j]){
				st.push({j, t[i+1][j]});
			}else if(p.second > t[i+1][j]){
				int pos;
				while(p.second >= t[i+1][j]){
					ans = max(ans, (p.second+1)*(j-(pos=p.first)+1));
					st.pop();
					if(!st.empty()) p = st.top();
					else break;
				}
				st.push({pos, t[i+1][j]});
			}
		}
	}
	return ans;
}

