		bool same = (board[i - 1][w - 1] == board[i][w - 1]);
		for (int j = w - 2; j >= 0; j--) {
			if (same ^ (board[i - 1][j] == board[i][j])) {
				val[i][j] = 1;
				same = !same;
			}
			else val[i][j] = val[i][j + 1] + 1;
		}
	}
	int ans = 0;
	REP(j, w) {
		UnionFind uf(h);
		vector<PII> vpii(h - 1);
