                i1--;
                int v1 = *i1;
                int v2 = *ii;
                multiset<int>::iterator iter = dist.upper_bound(v2-v1-1);
                dist.erase(iter);
                int n1 = str - v1;
                int n2 = v2 - str;
                dist.insert(n1);
                dist.insert(n2);
                pp.insert(str);
            }
            multiset<int>::iterator itera = dist.end();
            itera--;
            int aa = *itera;
            ans = max(ans, aa * (next - start));
        }
    }
    cout << ans << endl;
    return 0;
}

