int get_lcp(int row,int col)
{
	int l,r;
	l=0;
	r=n-row+1;
	while (l<r)
	{
		int mid=l+r+1;
		mid/=2;
		long long here1=get_normalized(row,col,mid);
		long long here2=get_normalized(row,col+1,mid);
		if (here1==here2)
			l=mid;
		else
			r=mid-1;
	}
	return l;
}

