	{
		int last = 0;
		for(int j = 1; j < m; j ++)
		{
			if(grid[i][j] == 0)
				con[i][j] = last = 0;
			else
			{
				if(last == 0)
				{
					int k = j;
					for(; k < m && grid[i][k] == 1; k ++);
					con[i][j] = last = k - j;
				}
				else
					con[i][j] = --last;
