typedef unsigned long long ULL;

ULL m[2000][2000 / 64 + 2];
#define BLACK 0ULL
#define WHITE 1ULL
ULL cont[2000 / 64 + 2];

int main() {
  int H, W;
  scanf("%d%d", &H, &W);
  char buf[90005];
  memset(m, 0x00, sizeof(m));
  const int WW = (W - 1) / 64 + 1;
  for (int i = 0; i < H; ++i) {
    scanf("%s", buf);
    ULL t = 0;
    for (int j = 0; j < W; ++j) {
      if (j > 0 && j % 64 == 0) {
        m[i][(j - 1) / 64] = t;
        t = 0;
      }
      t |= (buf[j] == '#' ? BLACK : WHITE) << (j % 64);
    }
    m[i][WW - 1] = t;
  }

  int ans = max(W, H);

  for (int i = 0; i < H; ++i) {
    memset(cont, 0x00, sizeof(ULL) * WW);
    cont[WW - 1] |= (1ULL << ((W - 1) % 64));
    set<int> cont_pos;
    cont_pos.insert(-1);
    cont_pos.insert(W - 1);

    /*
    cont:     00100010000100
    r:        00111000111111
    r_sft:    00011100011111
    r_cont:   00100100100000
    nextcont: 00100110100100
    new cont: 00000100100000
    */
    // printf("Start: %d\n", i);
    vector<int> new_cont_pos;
    for (int j = i + 1; j < H; ++j) {
      new_cont_pos.clear();
      // printf("End: %d\n", j);
      ULL r_next_k = m[i][0] ^ m[j][0];
      int cont_length = 0;
      for (int k = 0; k < WW; ++k) {
        // O(2000 * 1000 * 32)
        ULL r = r_next_k;
        r_next_k = m[i][k + 1] ^ m[j][k + 1];
        ULL r_shift = (r >> 1) | (r_next_k << 63);
        ULL r_cont = r ^ r_shift;

        ULL r_prev_cont = cont[k];
        ULL r_next_cont = r_prev_cont | r_cont;
        cont[k] = r_next_cont;
        ULL r_new_cont = r_next_cont & ~r_prev_cont;
        /*
        for (int x = 0; x < 64 && k * 64 + x < W; ++x) {
          // printf("%d", (r_next_cont & (1ULL << x)) ? 1 : 0);
        }
        */

        // O(2000 * 2000)
        if (r_new_cont) {
          for (int l = 0; r_new_cont && l < 64; ++l) {
            // O(2000 * 2000 * 64)
            if (r_new_cont & (1ULL << l)) {
              r_new_cont &= ~(1ULL << l);
              new_cont_pos.push_back(k * 64 + l);
            }
          }
        }
        // if (r_new_cont)
      }  // for(k)
      // printf("\n");

      for (int new_cont_pos0 : new_cont_pos) {
        auto it4 = cont_pos.insert(new_cont_pos0).first;

        int msb = *std::upper_bound(it4, cont_pos.end(), new_cont_pos0);
        int lsb = *std::lower_bound(cont_pos.begin(), it4, new_cont_pos0);
        int area = (j - i) * (msb - lsb);
        // printf("Rect: %d = (%d-%d) * (%d-%d)\n", area, i, j - 1, lsb, msb);
        ans = max(area, ans);
      }
    }  // for(j)
    int prev = -1;
    for (const int pos : cont_pos) {
      int area = (H - i) * (pos - prev);
      // printf("Rect2: %d = (%d-%d) * (%d-%d)\n", area, i, H-1, prev, pos);
      ans = max(area, ans);
      prev = pos;
    }
  }  // for (i)
  std::cout << ans << endl;
  return 0;
}

