long long max_box_area_in_histogram(vector<int>& a) {
    int N = a.size();

    vector<int> L(N);
    stack<int> st;

    for (int i=0; i<N; ++i) {
        while (!st.empty() && a[st.top()] >= a[i]) {
            st.pop();
        }
        L[i] = (st.empty() ? -1 : st.top())+1;
        st.push(i);
    }

    while (!st.empty()) st.pop();

    vector<int> R(N);
    for (int i=N-1; i>=0; --i) {
        while (!st.empty() && a[st.top()] >= a[i]) {
            st.pop();
        }
        R[i] = (st.empty() ? N : st.top())-1;
        st.push(i);
    }

    long long smax = 0;
    for (int i=0; i<N; ++i) {
        // ll s = (long long)a[i] * (R[i] - L[i] + 1);
        ll s = (long long)(a[i] + 1) * (R[i] - L[i] + 1 + 1);
        smax = max(smax, s);
    }

    return smax;
}


ll solve(int H, int W, vector<string>& s) {
    vvi a(H, vi(W-1, 0));
    rep(r, H) {
        rep(c, W-1) {
            a[r][c] = (s[r][c] == '#') ^ (s[r][c+1] == '#');
        }
    }
    vvi b(H-1, vi(W-1, 0));
    rep(c, W-1) {
        rep(r, H-1) {
            b[r][c] = a[r][c] ^ a[r+1][c];
        }
    }

    ll best = max(W, H);

    vi histo(W-1, 0);
    rep(r, H-1){
        rep(c, W-1) {
            if (b[r][c]) histo[c] = 0;
            else histo[c]++;
        }
        // cerr << histo << endl;
        best = max(best, max_box_area_in_histogram(histo));
    }

    return best;
}

int main() {
    int H, W; cin >> H >> W;
    vector<string> s(H);
    rep(i, H) cin >> s[i];
    cout << solve(H,W,s) << endl;
    return 0;
}

