const int N = 2e3 + 5;

int a[N][N], b[N][N], left[N][N], right[N][N], up[N][N];
char s[N];

int main()
{
	int n = read();
	int m = read();
	int ans = max(n, m);

	for (int i = 1; i <= n; ++i)
	{
		scanf("%s", s + 1);
		for (int j = 1; j <= m; ++j)
			if (s[j] == '#') a[i][j] = 1;		
	}

	for (int i = 1; i < n; ++i)
		for (int j = 1; j < m; ++j)
			if ((a[i][j] + a[i][j + 1] 
			+ a[i + 1][j] + a[i + 1][j + 1]) % 2 == 0)
			{
				b[i][j] = 1;
				left[i][j] = j;
				right[i][j] = j;
				up[i][j] = 1;
			}
	--n;
	--m;

	for (int i = 1; i <= n; ++i)
	{
		for (int j = 2; j <= m; ++j)
			if (b[i][j] == b[i][j - 1] && b[i][j])
				left[i][j] = left[i][j - 1];

		for (int j = m - 1; j >= 1; --j)
			if (b[i][j] == b[i][j + 1] && b[i][j])
				right[i][j] = right[i][j + 1];
	}

	for (int i = 1; i <= n; ++i)
		for (int j = 1; j <= m; ++j)
		{
			if (i > 1 && b[i][j] == b[i - 1][j] && b[i][j])
			{
				left[i][j] = max(left[i][j], left[i - 1][j]);
				right[i][j] = min(right[i][j], right[i - 1][j]);
				up[i][j] = up[i - 1][j] + 1;
			}

			int x = right[i][j] - left[i][j] + 1;
			int y = up[i][j];

			ans = max(ans, (x + 1) * (y + 1));
		}

	printf("%d\n", ans);

	return 0;
}

