{
    cin >> H >> W;
    for(int i = 0; i < H; i++) {
        for(int j = 0; j < W; j++) {
            cin >> C[i][j];
        }
    }

    for(int x = 0; x < W; x++) {
        int h = 1;
        for(int y = 0; y < H; y++) {
            if(x == W-1) {
                HMap[y][x] = y+1;
            } else {
                if(y == 0) {
                    h = 1;
                } else {
                    if(counter(x+1, y)%2 == 0) {
                        h++;
                    } else {
                        h = 1;
                    }
                }
                HMap[y][x] = h;
            }
        }
    }

