                S.push(rect);
            } else { //長方形最大値を求める
                while(S.size() > 0) {
                    Rect r = S.top(); 
                    if(r.height > rect.height) {
                        S.pop();
                        ans = max(ans, r.height * (x-r.pos+1));
                        rect.pos = r.pos;
                    } else {
                        break;
                    }
                }
                S.push(rect);
            }
        }
        while(S.size() > 0) {
            Rect r = S.top(); 
