int largest_rectangle(vector<int>& A){
    int N = A.size()-1;
    int ans = 0;
    stack<P<int,int>> s;
    for(int i=0;i<=N;i++){
        int pos = i;
        while(!s.empty() && s.top().first>=A[i]){
            P<int,int> p = s.top(); s.pop();
            ans = max(ans,p.first*(i-p.second+(i!=N)));
            pos = p.second;
        }
        s.push({A[i],pos});
    }
    return ans;
}

