long long get(vector<int> &v){
	stack<int> st; 
	vector<int> prv(v.size(), -1);
	for(int i = v.size() - 1; i >= 0; --i){
		while(!st.empty()){
			int x = st.top();
			if(v[x] > v[i]){
				prv[x] = i;
				st.pop();
			}else {
				break;
			}
		}
		st.push(i);
	}
	while(!st.empty())st.pop();
	vector<int> nxt(v.size(), -1);
	for(int i = 0; i < v.size(); ++i){
		while(!st.empty()){
			int x = st.top();
			if(v[x] > v[i]){
				nxt[x] = i;
				st.pop();
			}else {
				break;
			}
		}
		st.push(i);
	}
	long long ans = 0;
	for(int i = 0; i < v.size(); ++i){
		int l = prv[i], r = nxt[i];
		if(l == -1 && r == -1){
			ans = max(ans, ((int)v.size() + 1) * (v[i] + 1) * 1LL);
		}else if(l == -1){
			ans = max(ans, (r - l + 1) * (v[i] + 1) * 1LL);
		}else if(r == -1){
			ans = max(ans, (r - l + 1) * (v[i] + 1) * 1LL);
		}else {
			ans = max(ans, (r - l) * (v[i] + 1) * 1LL);
		}
	}
	return ans;
}

