int getLargestRectangle(vector<int>& hight) {
    int w = hight.size(),res = 0;
    stack<P> st;
    for (int i = 0;i < w;++i) {
        if (st.empty()) {
            if (hight[i]) st.push(P(hight[i],i));
        } else {
            int t = st.top().first;
            if (t < hight[i]) st.push(P(hight[i],i));
            else if (t > hight[i]) {
                while (!st.empty() && hight[i] < st.top().first) {
                    P p = st.top();
                    res = max(res,(p.first+1)*(i-p.second+1));
                    st.pop();
                }
                if (st.empty() || st.top().first < hight[i]) st.push(P(hight[i],i));
            }
        }
    }
    return res;
}

int getLargestRectangle(vector<vector<int>>& grid) {
    int h = grid.size(),w = grid[0].size();
    vector<vector<int>> hight(h,vector<int>(w));
    hight = grid;
    for (int j = 0;j < w;++j) for (int i = 1;i < h;++i) if (hight[i][j]) hight[i][j] += hight[i-1][j];
    for (int i = 0;i < h;++i) hight[i].emplace_back(0);
    int res = 0;
    for (int i = 0;i < h;++i) res = max(res,getLargestRectangle(hight[i]));
    return res;
}

