int maxRectangleArea(const vector<int>& heights) {
  const int n = heights.size();
  vector<int> L(n), R(n), stk;
  for (int i = 0; i < n; i++) {
    while (!stk.empty() && heights[stk.back()] >= heights[i]) {
      stk.pop_back();
    }
    L[i] = stk.empty() ? 0 : stk.back() + 1;
    stk.push_back(i);
  }
  stk.clear();
  for (int i = n - 1; i >= 0; i--) {
    while (!stk.empty() && heights[stk.back()] >= heights[i]) {
      stk.pop_back();
    }
    R[i] = stk.empty() ? n : stk.back();
    stk.push_back(i);
  }
  int ans = 0;
  for (int i = 0; i < n; i++) {
    ans = max(ans, heights[i] * (R[i] - L[i] + 1));
  }
  return ans;
}

