//ヒストグラムが覆う最大面積の長方形を求める. その長方形の高さがh, 幅がwのとき、(h + 1) / 2 * (w + 1) / 2を返す.
int maxArea(int height[], int n) {
	stack<int> ls, rs;
	int l[4000], r[4000];
	int i;

	//各iについて, i番目の棒を使う長方形(高さheight[i]の長方形)の, 左端(の番号)を求める.
	for (i = 0; i < n; i++) {
		while (!ls.empty() && height[ls.top()] >= height[i]) { ls.pop(); }
		if (ls.empty()) l[i] = 0;
		else l[i] = ls.top() + 1;
		ls.push(i);
	}

	//右端の番号も同様に
	for (i = n - 1; i >= 0; i--) {
		while (!rs.empty() && height[rs.top()] >= height[i]) { rs.pop(); }
		if (rs.empty()) r[i] = n - 1;
		else r[i] = rs.top() - 1;
		rs.push(i);
	}

	//あとは、高さをnパターン試す
	int ret = 0;
	for (i = 0; i < n; i++) {
		int width = (r[i] - l[i] + 1);
		int area = (width + 1) / 2 * (height[i] + 1) / 2;
		ret = max(ret, area);
	}
	return ret;
}

