int solve() {
	int ret = min(H, W);
	for (int i = 0; i < H - 1; i++) {
		stack<int> st;
		for (int j = 0; j < W - 1; j++) {
			if (col[i][j] == 0) dp[i][j] = (i == 0 ? 2 : dp[i - 1][j] + 1);
			else dp[i][j] = 1;
			if (st.empty() || dp[i][st.top()] < dp[i][j]) st.push(j), ret = max(ret, 2 * dp[i][j]);
			else {
				while (!st.empty() && dp[i][st.top()] >= dp[i][j]) st.pop();
				if (st.empty()) ret = max(ret, dp[i][j] * (j + 2));
