};
//1と0のグリッドにおいて1のマスのみを使って作る長方形の中で面積が最大のものの面積を返す
pair<int, int> LargestRectangle(vector<vector<int> > &s, int h, int w) {
        vector<vector<int> > t(h, vector<int> (w));
        for (int x = 0; x < w; x ++) for (int y = 0; y < h; y ++) {
                if (s[y][x] == 0) t[y][x] = 0;
                else t[y][x] = (y > 0) ? t[y - 1][x] + 1 : 1;
        }
        int res = 0;
        int highest = 0;
        for (int y = 0; y < h; y ++) { 
                stack<Rectangle> st;
                int ma = 0;
                int height = 0;
                t[y].resize(t.size() + 1);
                t[y][w] = 0;
                for (int x = 0; x <= w; x ++) {
                        Rectangle rect(t[y][x], x);
                        if (st.empty()) {
                                st.push(rect);
                        } else {
                                if (st.top().height < rect.height) {
                                        st.push(rect);
                                } else if (st.top().height > rect.height) {
                                        int target = x;
                                        while (!st.empty() && st.top().height >= rect.height) {
                                                Rectangle prev = st.top(); st.pop();
                                                int area = prev.height * (x - prev.pos);
                                                if (ma < area) {
                                                        ma = area;
                                                        height = prev.height;
                                                }
                                                target = prev.pos;
                                        }
                                        rect.pos = target;
                                        st.push(rect);
                                }
                        }
                }
                if (res < ma) {
                        res = ma;
                        highest = height;
                }
        }
        return mp(res, highest);
}

