const int MAXN = 2e3 + 5;

int N, M;
char A[MAXN][MAXN];

void input()
{
    read(N); read(M);
    for (int i = 1; i <= N; ++i) {
        scanf("%s", A[i] + 1);
    }
}

void solve()
{
    static bool forbid[MAXN][MAXN];

    for (int i = 1; i < N; ++i) {
        for (int j = 1; j < M; ++j) {
            forbid[i][j] = (A[i][j] == '#') ^ (A[i + 1][j] == '#') ^ (A[i][j + 1] == '#') ^ (A[i + 1][j + 1] == '#');
        }
    }

    static int up[MAXN];
    int ans = std::max(N, M);

    for (int i = 1; i < N; ++i) {
        for (int j = 1; j < M; ++j) {
            up[j] = (forbid[i][j] ? 0 : up[j] + 1);
        }
        static int st[MAXN];
        static int lbnd[MAXN];
        int top = 0;
        for (int j = 1; j < M; ++j) {
            for (; top > 0 && up[st[top]] > up[j]; --top) {
                chkmax(ans, (up[st[top]] + 1) * (j - lbnd[st[top]] + 1));
            }
            lbnd[j] = st[top] + 1;
            st[++top] = j;
        }
        for (; top > 0; --top) {
            chkmax(ans, (up[st[top]] + 1) * (M - lbnd[st[top]] + 1));
        }
    }

    printf("%d\n", ans);
}

int main()
{
#ifdef __DEBUG
    freopen("F.in", "r", stdin);
    freopen("F.out", "w", stdout);
#endif

    input();
    solve();
}

