using namespace std;
typedef long long ll;

struct rect { ll h, w; };

ll H, W;
char S[2000][2000];
ll f[2000][2000];

rect max_rectangle(ll *h, ll n) {
  struct item { ll h, p; };
  stack<item> stk;
  rect m = (rect) { 0, 0 };

  REP(i, 0, n + 1) {
    item r = (item) { i < n ? h[i] : 0, i };
    if(stk.empty()) {
      stk.push(r);
    } else {
      if(stk.top().h < r.h) stk.push(r);
      if(stk.top().h > r.h) {
        ll t = i;
        while(stk.size() && stk.top().h >= r.h) {
          item s = stk.top();
          stk.pop();
          s.h * (i - s.p);
          if(s.h * (i - s.p) > m.h * m.w) m = (rect) { s.h, i - s.p };
          t = s.p;
        }
        r.p = t;
        stk.push(r);
      }
    }
  }

  return m;
}

int main(void) {
  cin >> H >> W;
  REP(i, 0, H) REP(j, 0, W) cin >> S[i][j];

  REP(i, 0, H - 1) REP(j, 0, W - 1) {
    f[i][j] = ((S[i][j] == '#') + (S[i][j + 1] == '#') + (S[i + 1][j] == '#') + (S[i + 1][j + 1] == '#')) % 2 == 0;
  }
  for(ll i = H - 3; i >= 0; i--) REP(j, 0, W - 1) {
    if(f[i][j] > 0) f[i][j] += f[i + 1][j];
  }

  ll ans = max(H, W);
  REP(i, 0, H - 1) {
    rect m = max_rectangle(&f[i][0], W - 1);
    ans = max(ans, (m.h + 1) * (m.w + 1));
  }
  cout << ans << endl;
}

