ll getmaxrect(int size, ll buffer[]) {
	stack<rect> s;
	ll res = 0;
	buffer[size] = 0;
	for (int i = 0; i <= size; i++) {
		rect rec;
		rec.hei = buffer[i];
		rec.pos = i;
		if (s.empty()) {
			s.push(rec);
		}
		else {
			if (s.top().hei < rec.hei) {
				s.push(rec);
			}
			else if (s.top().hei > rec.hei) {
				int tag = i;
				while (!s.empty() && s.top().hei >= rec.hei) {
					rect pre = s.top(); s.pop();
					ll area = (pre.hei+1)*(i - pre.pos+1);
					res = max(res, area);
					tag = pre.pos;
				}
				rec.pos = tag;
				s.push(rec);
			}
		}
	}
	return res;
}
