int HistogramArea(vector<int>v){
  stack<int>st;
  int sol=0;
  int cur=0;
  while(cur<v.size()){
     if(st.size()&&v[st.top()]>v[cur]){
        int lft=st.top();
        st.pop();
        if(v[lft])
         sol=max(sol,(v[lft]*2-v[lft]+1)*(st.empty()?(cur*2-cur+1):((cur-st.top()-1)*2-(cur-st.top()-1)+1)));
     }
     else{
        st.push(cur++);
     }
  }
  while(st.size()){
      int lft=st.top();
      st.pop();
     if(v[lft])
      sol=max(sol,(v[lft]*2-v[lft]+1)*(st.empty()?(cur*2-cur+1):((cur-st.top()-1)*2-(cur-st.top()-1)+1)));
  }
  return sol;
}
