// max Rectangle in Histogram

int calc(vector<int> v) {
  int n = v.size();
  vector<int> L(n), R(n);

  // decreasing from top
  stack<int> st;
  for(int i=0; i < n; i++) {
    L[i] = i;
    while(st.size() && v[st.top()] >= v[i]) {
      L[i] = st.top();
      if(v[st.top()] > v[i]) st.pop();
      else break;
    }
    if(st.empty() || st.top() != v[i]) st.push(i);
  }
  st = stack<int>();
  for(int i=n-1; i >= 0; i--) {
    R[i] = i;
    while(st.size() && v[st.top()] >= v[i]) {
      R[i] = st.top();
      if(v[st.top()] > v[i]) st.pop();
      else break;
    }
    if(st.empty() || st.top() != v[i]) st.push(i);
  }
  int res = 0;
  for(int i=0; i < n; i++) {
    res = max(res, v[i] * (R[i] - L[i] + 2));
  }
  return res;
}

