			if (sum[i][j] == sum[i][j - 1]) {
				s.pop();
				s.push(j);
				l[j] = l[j - 1];
				continue;
			}
			while (!s.empty() && sum[i][s.top()] > sum[i][j]) {
				s.pop();
			}
			if (s.empty()) {
				l[j] = 0;
			}
			else {
				if (sum[i][s.top()] == sum[i][j]) {
					l[j] = l[s.top()];
					s.pop();
				}
				else {
					l[j] = s.top() + 1;
				}
			}
			s.push(j);
		}
		while (!s.empty())s.pop();
		s.push(W - 1);
		r[W - 1] = W - 1;
		for (int j = W - 2; j >= 0; j--) {
			if (sum[i][j] > sum[i][j + 1]) {
				s.push(j);
				r[j] = j;
				continue;
			}
			if (sum[i][j] == sum[i][j + 1]) {
				s.pop();
				s.push(j);
				r[j] = r[j + 1];
				continue;
			}
			while (!s.empty() && sum[i][s.top()] > sum[i][j]) {
				s.pop();
			}
			if (s.empty()) {
				r[j] = W-1;
			}
			else {
				if (sum[i][s.top()] == sum[i][j]) {
					r[j] = r[s.top()];
					s.pop();
				}
				else {
					r[j] = s.top() - 1;
				}
			}
			s.push(j);
		}
		for (int j = 0; j < W; j++) {
		//	cout << i << " " << j << " " << l[j] << " " << r[j] << " " << sum[i][j] << "  ";
			ans = max(ans, (r[j] - l[j] + 2)*(sum[i][j] + 1));
		}
		//cout << endl;
	}
	cout << ans << endl;
	return 0;
}

