int a[N][N], b[N][N];

int solve(vector<int>& A) {
	int n = sz(A);
	vector<int> L(n, -1), R(n, n);
	stack<int> s;
	FOR (i, 0, n - 1) {
		while (!s.empty() and A[s.top()] >= A[i]) s.pop();
		if (!s.empty()) L[i] = s.top();
		s.push(i);
	}
	while (!s.empty()) s.pop();
	NFOR (i, n - 1, 0) {
		while (!s.empty() and A[s.top()] >= A[i]) s.pop();
		if (!s.empty()) R[i] = s.top();
		s.push(i);
	}
	int ans = 0;
	FOR (i, 0, n - 1) {
		ans = max(ans, (R[i] - L[i]) * A[i]);
	}
	return ans;
}

