static inline void handle(int& top, int& ans, int a, int b, int h)
{
  while (top > 1 && h < stk[top-1].h)
  {
    int w = a - stk[top-2].w;
    int h = stk[top-1].h;
    int s = w * h;
    if (s > ans) ans = s;
    --top;
  }
  stk[top++] = {b, h};
}
