using namespace std;
typedef long long ll;

int solve(vector<int> v)
{
    int n=v.size();
    vector<int> l(n,-1);
    stack<array<int,2>> s;
    s.push({-1,-1});
    for(int i=0;i<n;i++)
    {
        while(s.top()[0]>=v[i]) s.pop();
        l[i]=s.top()[1];
        s.push({v[i],i});
    }
    vector<int> r(n,n);
    while(!s.empty()) s.pop();
    s.push({-1,n});
    for(int i=n-1;i>=0;i--)
    {
        while(s.top()[0]>=v[i]) s.pop();
        r[i]=s.top()[1];
        s.push({v[i],i});
    }
    int res=0;
    for(int i=0;i<n;i++) res=max(res,(v[i]+1)*(r[i]-l[i]));
    return res;
}

int main()
{
