                    while (!st.empty() && st.top().first > v[i]) {
                        int height = st.top().first;
                        int pos = st.top().second;
                        st.pop();
                        lint s = height * (i - pos);

                        if (s > max_size) {
                            max_size = s;
                            ret.clear();
                            ret.push_back( {height, i - pos} );
                        }
                        else if (s == max_size) {
                            ret.push_back( {height, i - pos} );
                        }

                        if (!st.empty() && st.top().first < v[i]) {
                            st.push( {v[i], pos} );
                        }
                    }
                }
            }
            else {
                st.push( {v[i], i} );
            }
        }
        return ret;
    };

    lint ans = 0;
    vector<pair<int, int>> rects;
    repeat(i, h - 1) {
        auto v = maximum_rectangle(board[i]);
        rects.insert(rects.end(), v.begin(), v.end());
    }

    for(auto rect: rects) {
        ans = max(ans, (lint)(rect.first + 1) * (rect.second + 1));
    }
    cout << ans << endl;
}

