ll maxRectangleInHistogram(vector<int> &v) {
    int n = v.size();
    stack<int> s;
    vector<int> L(n), R(n);
    rep(i, 0, n) {
        while (s.size() && v[s.top()] >= v[i]) s.pop();
        L[i] = s.size() ? (s.top() + 1) : 0;
        s.push(i);
    }
    while (s.size()) s.pop();
    rrep(i, n - 1, 0) {
        while (s.size() > 0 && v[s.top()] >= v[i]) s.pop();
        R[i] = s.size() ? s.top() : n;
        s.push(i);
    }
    ll res = 0;
    rep(i, 0, n) res = max(res, 1LL * (v[i] + 1) * (R[i] - L[i] + 1));
    return res;
}
ll maxRectangle(vector<vector<int>> &v) { // 0:can use, 1:can't use
    int h = v.size();
    int w = v[0].size();

    ll res = 0;
    vector<int> vv(w, 0);
    rep(y, 0, h) {
        rep(x, 0, w) {
            if (v[y][x]) vv[x] = 0;
            else vv[x]++;
        }
        res = max(res, maxRectangleInHistogram(vv));
    }
    return res;
}
