int solve(vector<int>U) {
	for (int i = 0; i < U.size(); i++) {
		while (!T.empty() && U[T.top()] >= U[i])T.pop();
		if (T.size() >= 1)L[i] = (T.top() + 1); else L[i] = 0;
		T.push(i);
	}
	while (!T.empty())T.pop();
	for (int i = U.size() - 1; i >= 0; i--) {
		while (!T.empty() && U[T.top()] >= U[i])T.pop();
		if (T.size() >= 1)R[i] = (T.top()); else R[i] = U.size();
		T.push(i);
	}
	int maxn = 0;
	for (int i = 0; i < U.size(); i++)maxn = max(maxn, U[i] * (R[i] - L[i] + 1));
	return maxn;
}
