//        S.push(h1);
//        wid.push(Wid);
//        Wid=0;
        while(!S.empty()&&h2<=S.top()){
            Wid+=wid.top(); wid.pop();
            int x=S.top(); S.pop();
            ret=max(ret,x*Wid);
        }
//        ret=max(ret,h2*(Wid+1));
        S.push(h2);
        wid.push(Wid+1);
    }
