            int x=cal(i,j)+cal(i,j+1)+cal(i+1,j)+cal(i+1,j+1);
            mark[i][j]=(x&1);
        }
    }
    for(int i=1;i<=h;i++){
        for(int j=1;j<=w;j++){
            if(i==1) b[i][j]=1;
