            else if(mark[i-1][j]) c[i][j]=i;
            else c[i][j]=c[i-1][j];
        }
    }
    int ans=0;
    for(int i=1;i<=h;i++){
        ans=max(ans,solve(i));
    }
    printf("%d\n",ans);
}

