bool is_badpoint(ll i, ll j) {
	return grid[i][j] ^ grid[i + 1][j] ^ grid[i][j - 1] ^ grid[i + 1][j - 1];
}

ll a[MAX] = {};
void roof(ll x) {
	REP(j, 1, w) {
		while (a[j] <= x || !bad_point[a[j]][j]) {
			a[j]++;
		}
	}
}

rect c[MAX * 2];

ll make_rect(ll x) {
	ll ans = 0;
	stack<rect> st;
	REP(i, 1, w) {
		c[i * 2 - 1] = { a[i] - x,i };
		c[i * 2] = { h - x,i };
	}
	c[2 * w + 1] = { 0,w + 1 };

	REP(j, 1, 2 * w + 1) {
		if (st.empty()) {
			st.push(c[j]);
		}
		else {
			ll cur = c[j].pos;
			while (st.top().hei > c[j].hei) {
				rect c_rec = st.top();
				st.pop();
				ans = max(ans, c_rec.hei*(c[j].pos - c_rec.pos));
				//cout << c_rec.hei*(c[j].pos - c_rec.pos) << endl;
				cur = c_rec.pos;
				if (st.empty())break;
			}
			if (st.empty()) {
				st.push({ c[j].hei,cur });
			}
			else if (st.top().hei < c[j].hei) {
				st.push({ c[j].hei,cur });
			}
		}
	}
	return ans;
}

