		for(j = 1; j <= m; j++)
			arr[i][j] = (s[j - 1] == '.');
	}
	for(j = 1; j <= m; j++){
		for(i = 1; i <= n; i++){
			if(j == 1){
				suff[i][j][0] = i;
				suff[i][j][1] = i;
				continue;
			}
			suff[i][j][0] = (suff[i - 1][j][0] + 1) * (arr[i][j] == arr[i][j - 1]);
			suff[i][j][1] = (suff[i - 1][j][1] + 1) * (arr[i][j] != arr[i][j - 1]);
		}
	}
    for(i = 1; i <= n; i++){
    	hist.clear();
    	for(j = 2; j <= m; j++)
    		hist.push_back(suff[i][j][arr[i][j] != arr[i][j - 1]]);
    	ans = max(ans, getMaxArea());
    }
    ans = max(ans, max(n, m));
    printf("%d\n", ans);

    return 0;
}

