int get (int n, int a[]) {
    stack < int > left, right;
    int width[n + 1];
    for (int i = 0; i < n; i++) width[i] = 1;
    for (int i = 0; i < n; i++) {
        while (!left.empty() && a[i] <= a[left.top()]) left.pop();
        if (left.empty()) {
            width[i] += i;
        } else {
            width[i] += i - left.top() - 1;
        }
        left.push(i);
    }
    for (int i = n - 1; i >= 0; i--) {
        while (!right.empty() && a[i] <= a[right.top()]) right.pop();
        if (right.empty()) {
            width[i] += n - i - 1;
        } else {
            width[i] += right.top() - i - 1;
        }
        right.push(i);
    }
    int mx = -inf;
    for (int i = 0; i < n; i++) {
        mx = max(mx, (a[i] + 1) * (width[i] + 1));
    }
    return mx;
}

