			ppp[i][j] = -1;
			next[i][j] = -1;
		}
	}
    for (int i=0; i < w; i++){
		for (int j=0; j < h; j++){
			cin >> matrix[i][j];
		}
    }
    for (int i=1; i < w; i++){
        for (int j=1; j < h; j++){
			int summ = 0;
			if (matrix[i-1][j-1] == '#') summ++;
			if (matrix[i-1][j] == '#') summ++;
			if (matrix[i][j-1] == '#') summ++;
			if (matrix[i][j] == '#') summ++;
			if (summ % 2 != 0){
                ppp[i][j] = 1;
			}
        }
    }
    int ans = 0;
    for (int i=0; i <= w; i++){
		next[i][h] = -1;
		for (int j=h-1;j >= 0; j--){
			if (ppp[i][j] != -1) next[i][j] = j;
			else next[i][j] = next[i][j+1];
		}
    }
    for (int start = 0; start < h; start++){
		for (int j=0; j <= w; j++){
			del[j] = 0;
		}
        vector<pair<int, int> > np;
        for (int j=0; j <= w; j++){
			if (next[j][start+1] == -1) continue;
			np.push_back(make_pair(next[j][start+1], j));
        }
        sort(np.begin(), np.end());
        set<int> pp;
        pp.insert(0);
        pp.insert(w);
        priority_queue<int> dist;
        dist.push(w);
        int u = 0;
        for (int next=start+1; next <= h; next++){
            while (u < np.size() && np[u].first < next){
                int str = np[u].second;
                u++;
                set<int>::iterator ii = pp.upper_bound(str);
                set<int>::iterator i1 = ii;
                i1--;
                int v1 = *i1;
                int v2 = *ii;
                del[v2-v1]++;
                int n1 = str - v1;
                int n2 = v2 - str;
                dist.push(n1);
                dist.push(n2);
                pp.insert(str);
            }
            int aa;
            while (true){
				int el = dist.top();
				if (del[el] > 0){
					del[el]--;
					dist.pop();
				}
				else{
                    aa = el;
                    break;
				}
            }
            ans = max(ans, aa * (next - start));
        }
    }
    cout << ans << endl;
    return 0;
}

