void solve() {
  int h, w; cin >> h >> w;
  vector<string> s(h); cin >> s;

  vector<set<int>> g(h-1);
  rep(i,h-1) {
    g[i].emplace(0);
    bool comp = s[i][0] == s[i+1][0];
    rep1(j,w) {
      if (comp != (s[i][j] == s[i+1][j])) {
        g[i].emplace_hint(g[i].end(), j);
        comp ^= true;
      }
    }
    g[i].emplace_hint(g[i].end(), w);
  }

  vector<set<int>> add(h-1);
  rep1(i,h-1) {
    for (auto &n : g[i]) {
      if (!g[i-1].count(n)) {
        add[i].emplace_hint(add[i].end(), n);
      }
    }
  }

  int ans = max(h, w);

  rrep(i,h-1) {
    REP(j,i+1,h-2) {
      vi dec;
      for (auto &n : add[j]) {
        auto itr = g[i].lower_bound(n);
        if (*itr == n) {
          dec.emplace_back(n);
        } else {
          int right = *itr;
          int left = *(--itr);
          chmax(ans, (right - left) * (j - i + 1));
          g[i].emplace(n);
        }
      }
      for (auto &n : dec) {
        add[j].erase(n);
      }
    }
    int left = 0;
    for (auto itr=++g[i].begin(); itr!=g[i].end(); ++itr) {
      chmax(ans, (*itr - left) * (h - i));
      left = *itr;
    }
  }

  cout << ans << endl;
}


