int rectangle(int H, int W, const vector<vector<int>> &field) {
    const int empty = 0;    // 塗れるマス

    vector<vector<int>> dp(H, vector<int>(W, 0));
    for(int x = 0; x < W; ++x) {
        for(int y = 0; y < H; ++y) {
            if (y == 0) {
                dp[y][x] = field[y][x] == empty ? 1 : 0;
                continue;
            }

            if (field[y][x] == empty) {
                dp[y][x] = dp[y - 1][x] + 1;
            } else {
                dp[y][x] = 0;
            }
        }
    }

    int ans = 0;
    for(int y = 0; y < H; ++y) {
        for(int x = 0; x < W; ++x) {
            int h = INT_MAX;
            for (int w = 0; w < W - x; ++w) {
                h = min(h, dp[y][x + w]);
//                ans = max(ans, h * (w + 1));
                ans = max(ans, (h + 1) * (w + 2));
            }
        }
    }

    return ans;
}

