int rect(int x0, int  y0, int  x1, int  y1)
{
    return (x1 - x0 + 1) * (y1 - y0 + 1);
}

int solve(int x0, int y0, int x1, int y1)
{
    if (x1 < x0 || y1 < y0)
        return 0;

    if (x0 == x1 || y0 == y1)
        return rect(x0, y0, x1, y1);

    int mx = (x0 + x1) / 2;
    int my = (y0 + y1) / 2;

    l[my] = x0;
    r[my] = x1;
    for (int y = y0; y <= y1; y++)
    {
        l[y] = mx;
        while (l[y] >= x0 &&
               (t[mx][my] + t[l[y]][y] + t[mx][y] + t[l[y]][my]) % 2 == 0)
            l[y]--;
        l[y]++;

        r[y] = mx;
        while (r[y] <= x1 &&
               (t[mx][my] + t[r[y]][y] + t[mx][y] + t[r[y]][my]) % 2 == 0)
            r[y]++;
        r[y]--;
    }

    int ans = 0;

    for (int i = y0; i <= y1; i++)
        for (int j = i; j <= y1; j++)
        {
            int ll = max(l[i], l[j]);
            int rr = min(r[i], r[j]);
            ans = max(ans, rect(ll, i, rr, j));
        }

    ans = max(solve(x0, y0, mx - 1, y1), ans);
    ans = max(solve(x0, y0, x1, my - 1), ans);
    ans = max(solve(mx + 1, y0, x1, y1), ans);
    ans = max(solve(x0, my + 1, x1, y1), ans);

    return ans;
}


