// ---------------------- template ----------------------

int GetMaxHistRect(vector<int> hist) {
	int res = 0;
	stack<pii> st;
	REP(i, hist.size()) {
		if (st.empty()) st.emplace(hist[i], i);
		else if (st.top().first < hist[i]) st.emplace(hist[i], i);
		else {
			while (not st.empty() and st.top().first > hist[i]) {
				int width = i - st.top().second + 1;
				int height = st.top().first + 1;
				st.pop();
				res = max(res, width*height);
			}
		}
	}
	while (not st.empty()) {
		int width = hist.size() - st.top().second;
		int height = st.top().first;
		++width;
		++height;
		st.pop();
		res = max(res, width*height);
	}
	return res;
}

int GetMaxRect(vector<vector<bool> > field) {
	vector<vector<int> > hists(field.size(), vector<int>(field[0].size()));
	REP(j, field[0].size()) {
		if (field[0][j]) hists[0][j] = 1;
		else hists[0][j] = 0;
	}
	int res = GetMaxHistRect(hists[0]);
	FOR(i, 1, field.size()) {
		REP(j, field[i].size()) {
			if (field[i][j] != 0) {
				hists[i][j] += hists[i - 1][j] + 1;
			}
		}
		res = max(res, GetMaxHistRect(hists[i]));
	}
	return res;
}

