            v[x].push_back({j, j + 1});
        }
        int s = 1;
        for (int j = n; j > i; j--)
        {
            for (int k = 0; k < v[j].size(); k++)
            {
                int R = v[j][k].first;
                int L = v[j][k].second;
                int RR = r[L];
                int LL = l[R];
                int len = RR - LL + 1;
                s = max(s, len);
                l[RR] = LL;
                r[LL] = RR;
            }
            //cout << i << " " << j << " " << s * (j - i) << "\n";
            ans = max(ans, s * (j - i));
        }
    }
    cout << ans;
}

