stack<int> S;
stack<int> wid;

int solve(int i){
    int ret=0;
    while(!S.empty()) S.pop();
    while(!wid.empty()) wid.pop();
    for(int j=1;j<=w+1;j++){
        int h1=(j==w+1) ? 0 : i-b[i][j]+1;
        int h2=(j==w+1) ? 0 : i-c[i][j]+1;
        int Wid=0;
        while(!S.empty()&&S.top()>=h1){
            Wid+=wid.top(); wid.pop();
            int x=S.top(); S.pop();
            ret=max(ret,x*Wid);
        }
        ret=max(ret,h1*(Wid+1));
        S.push(h1);
        wid.push(Wid);
        Wid=0;
        while(!S.empty()&&S.top()>=h2){
            Wid+=wid.top(); wid.pop();
            int x=S.top(); S.pop();
            ret=max(ret,x*Wid);
        }
        ret=max(ret,h2*(Wid+1));
        S.push(h2);
        wid.push(Wid+1);
    }
//    printf("i = %d : ret = %d\n",i,ret);
    return ret;
}

