long long largestRectangle(const vector<int> &histogram) {
    long long res = 0;
    const int n = (int)histogram.size();
    stack<int> stk;
    vector<int> toLight(n), toRight(n);
    for (int i = 0; i < n; ++i) {
        while (!stk.empty() && histogram[stk.top()] >= histogram[i])
            stk.pop();
        toLight[i] = stk.empty() ? 0 : stk.top() + 1;
        stk.push(i);
    }
    while (!stk.empty())stk.pop();
    for (int i = n - 1; i >= 0; --i) {
        while (!stk.empty() && histogram[stk.top()] >= histogram[i])
            stk.pop();
        toRight[i] = stk.empty() ? n : stk.top();
        stk.push(i);
        long long width = toRight[i] - toLight[i];
        res = max(res, (width + 1)*(histogram[i] + 1));
    }
    return res;
}

/*
0と1からなるグリッドで
1のみからなる長方形の最大の面積を返す
O(HW)
*/
int largestRectangle(vector<vector<int> > a) {
    int h = (int)a.size();
    int w = (int)a[0].size();
    for (int i = 1; i < h; ++i)for (int j = 0; j < w; ++j)
        if (a[i][j])a[i][j] = a[i - 1][j] + 1;
    int res = 0;
    for (int i = 0; i < h; ++i)
        res = max(res, (int)largestRectangle(a[i]));
    return res;
}

