long double insx(pii a, pii b) {
	return ((long double)(b.second - a.second))/(a.first - b.first);
}

int solve(int n) {
	fill(S, S+maxn, mp(0,0)); int hd = 0, idx = 0; int ans = -20;
	for (int i = 1; i <= n; i++) {
		int pos = i;
		while (hd > 0 && S[hd].first >= b[i]) { pos = min(pos, posn[hd]); hd--; }
		pii ln = mp(b[i], -(pos-2)*b[i]);
		while (hd > 1 && insx(ln,S[hd]) < insx(S[hd], S[hd-1])) hd--;
		hd++; posn[hd] = pos; S[hd] = ln;
		idx = min(idx, hd);
		while (idx < hd && insx(S[idx],S[idx+1]) < i) idx++;
		ans = max(ans, S[idx].first * i + S[idx].second);

	}
	return ans;
}


