// 1-indexed
int GetMaxRectange(const vector<vector<int>>& xs) {
  int h = xs.size() - 1;
  int w = xs[0].size() - 1;
  int ans = max(h, w);
  rep(i, 1, h - 1) {
    stack<P> s;
    rep(j, 1, w - 1) {
      int lj = j;
      while (!s.empty() && s.top().first > xs[i][j]) {
        ans = max(ans, (s.top().first + 1) * (j - s.top().second + 1));
        lj = s.top().second;
        s.pop();
      }
      if (xs[i][j]) s.emplace(xs[i][j], lj);
    }
    while (!s.empty()) {
      ans = max(ans, (s.top().first + 1) * (w - s.top().second + 1));
      s.pop();
    }
  }
  return ans;
}

