bool read() {
    if (!(cin >> n >> m))
        return false;

    for (int i = 0; i < n; ++i)
        cin >> s[i];

    return true;
}

void solve() {
    auto ans = 1;

    for (int i = 0; i < n; ++i) {
        b[i][0] = 0;

        for (int j = 1; j < m; ++j)
            b[i][j] = (s[i][j] != s[i][j - 1]);

        for (int j = 0; j < m; ++j) {
            if (i == 0)
                w[i][j] = 1;
            else
                w[i][j] = (b[i][j] ^ b[i - 1][j]);

            if (w[i][j] == 1)
                f[j] = i;
        }

        vector<int> s;

        for (int j = 0; j < m; s.emplace_back(j++)) {
            for (; !s.empty() && f[s.back()] <= f[j]; s.pop_back()) { }
            g[j] = s.empty() ? 0 : s.back();
        }

        s.clear();

        for (int j = m - 1; j >= 0; s.emplace_back(j--)) {
            for (; !s.empty() && f[s.back()] <= f[j]; s.pop_back()) { }
            h[j] = s.empty() ? m : s.back();
            ans = max(ans, (i - f[j] + 1) * (h[j] - g[j]));
        }
    }

    cout << ans << endl;
}

