	stack<int> st;
	for(int i=0;i<v.size();i++){
		while(!st.empty()&&v[st.top()]>=v[i])st.pop();
		if(st.empty())L[i]=-1;
		else L[i]=st.top();
		st.push(i);
	}
	while(!st.empty())st.pop();
	for(int i=v.size()-1;i>=0;i--){
		while(!st.empty()&&v[st.top()]>=v[i])st.pop();
		if(st.empty())R[i]=v.size();
		else R[i]=st.top();
		st.push(i);
	}
	int res = 0;
	for(int i=0;i<v.size();i++){
		if(L[i]==-1)res = max(res,(R[i]-L[i]-1)*v[i]);
		else res = max(res,(R[i]-L[i])*v[i]);
	}
	return res;
}
