int append_range(map<ii,int>& r_next, map<ii,int>& r_prev, vector<ii>& r){
    int stopped = -1;

    int L = r.size();
    rep(i, L) {
        ii k = r[i];
        r_next[k] = max(r_next[k], 1);
        stopped = 2 * (k.second - k.first + 1);
    }

    for (auto p : r_prev) {
        ii x = p.first;
        int ph = p.second, phs = (ph + 1) * (x.second - x.first + 1);
        // [x.first, x.second)
        int lo = lower_bound(ALL(r), ii(x.first, 0)) - r.begin();
        int hi = upper_bound(ALL(r), ii(x.second, 0)) - r.begin();
        lo = 0; hi = r.size();
        for (int i=lo; i<hi; ++i) {
            ii y = r[i];

            if (x.second <= y.first) {
                ;
            } else if (y.second <= x.first) {
                ;
            } else {
                if (x.first <= y.first && y.second <= x.second) {
                    // y部分だけ
                    r_next[y] = max(r_next[y], ph+1);
                } else if (y.first <= x.first && y.second <= x.second) {
                    ii k(x.first, y.second);
                    r_next[k] = max(r_next[k], ph+1);
                } else if (x.first <= y.first && x.second <= y.second) {
                    ii k(y.first, x.second);
                    r_next[k] = max(r_next[k], ph+1);
                } else if (y.first <= x.first && x.second <= y.second) {
                    r_next[x] = max(r_next[x], ph+1);
                }
            }
        }
    }

    return stopped;
}

int solve(int H, int W, vector<string>& s) {
    // fprintf(stderr, "H=%d, W=%d\n", H, W);
    vector<int> d(W);
    map<ii,int> r_prev;
    int best = 0;

    for (int i=0; i<H-1; ++i) {
        // 順
        rep(c, W) {
            d[c] = (s[i][c] == s[i+1][c]);
        }
        vector<int> e(W-1, 0);
        rep(i, W-1) {
            e[i] = d[i] & d[i+1];
        }
        vector<ii> r0 = ranges(W-1, e);
        // 逆
        rep(i, W) d[i] ^= 1;
        rep(i, W-1) {
            e[i] = d[i] & d[i+1];
        }
        // vector<ii> r1 = rev_ranges(W-1, r0);
        vector<ii> r1 = ranges(W-1, e);

#ifdef DEBUG
        cerr << i << ") " << r_prev << endl;
        cerr << "  + " << r0 << endl;
        cerr << "  + " << r1 << endl;
#endif

        map<ii,int> r_next;
        int stop = 0;
        stop = append_range(r_next, r_prev, r0);
        best = max(best, stop);
        stop = append_range(r_next, r_prev, r1);
        best = max(best, stop);
#ifdef DEBUG
        cerr << " => " << r_next << endl;
#endif

        r_prev = r_next;

        for (auto p : r_prev) {
            ii x = p.first;
            int ph = p.second;
            best = max(best, (ph+1) * (x.second - x.first + 1));
        }

    }

    for (auto p : r_prev) {
        ii x = p.first;
        int ph = p.second;
        best = max(best, (ph+1) * (x.second - x.first + 1));
    }

    return best;
}

