    for(int i = n; i >= 1; i--)
        for(int j = 1; j <= m; j++)
            if(ma[i][j] == 1)
                lg[i][j] = 0;
            else
                lg[i][j] = lg[i + 1][j] + 1;
    int ans = 0;
    for(int i = 1; i <= n; i++)
    {
        for(int j = 1; j <= m; j++)
            v[j] = lg[i][j];
        for(int j = 1; j <= m; j++)
