            while(!st.empty() && v[st.top()] > v[j])
            {
                mxl[j] = j - st.top();
                st.pop();
            }
            if(!st.empty() && v[st.top()] == v[j])
                mxl[j] = j - st.top();
            else
                st.push(j);
        }
        while(!st.empty())
            st.pop();
        for(int j = m; j >= 1; j--)
        {
