void solve() {
	int H, W; cin >> H >> W;
	vector<string> S(H); REP(i, H) cin >> S[i];
	vector<vector<int> > field(H - 1, vector<int>(W-1));
	REP(y, H-1) {
		REP(x, W-1) {
			int cnt = 0;
			REP(i, 2) REP(j, 2) {
				if (S[y+i][x+j] == '#') ++cnt;
			}
			field[y][x] = (cnt % 2 == 0);
		}
	}
	REP(x, W - 1) {
		FOR(y, 1, H - 1) {
			if (field[y][x] != 0) {
				field[y][x] += field[y - 1][x];
			}
		}
	}

	int res = max(H, W);
	REP(y, H-1) {
		int maxRect = 0;
		stack<pii> st;
		REP(x, W - 1) {
			while (not st.empty() and st.top().first > field[y][x]) {
				int width = x - st.top().second;
				int height = st.top().first;
				st.pop();
				++width; ++height;
				maxRect = max(maxRect, width*height);
			}
			if (st.empty() or st.top().first < field[y][x]) {
				st.emplace(field[y][x], x);
			}
		}
		if (not st.empty()){
			int width = W-1 - st.top().second;
			int height = st.top().first;
			st.pop();
			++width; ++height;
			maxRect = max(maxRect, width*height);
		}
		res = max(res, maxRect);
	}
	cout << res << endl;
}

