    for (int i = 0; i < (int)height.size(); ++i) {
        while (!st.empty() && height[st.top()] >= height[i]) st.pop();
        left[i] = !st.empty() ? st.top() + 1 : 0;
        st.push(i);
    }
    while (!st.empty()) st.pop();
    for (int i = (int)height.size() - 1; i >= 0; --i) {
        while (!st.empty() && height[st.top()] >= height[i]) st.pop();
        right[i] = !st.empty() ? st.top() : height.size();
