struct LargestRectangle{
  vector<vector<int>> a;
  int n, m;
  void init(int arg_n, int arg_m){
    n = arg_n;
    m = arg_m;
    a.assign(n, vector<int>(m+1, 0));
  }
  void put(int i, int j){
    // (i, j) can be a part of the rectangle
    a.at(i).at(j) = 1;
  }
  int query(){
    vector<int> b(m+1, 0);
    int ans = max(n, m); // 0;
    REP(i, n){
      stack<pair<int, int>> st;
      st.emplace(-1, -1);
      REP(j, m+1){
        b[j] += a[i][j];
        if(a[i][j] == 0){
          b[j] = 0;
        }
        int p = j;
        while(st.top().first >= b[j]){
          p = st.top().second;
          // ans = max(ans, st.top().first * (j - p));
          ans = max(ans, (st.top().first + 1) * ((int)j - p + 1));
          st.pop();
        }
        st.emplace(b[j], p);
      }
    }
    return ans;
  }
};

