const int N = 2e3 + 7;

struct KMR {
    char *s;
    vector < pair < PII, int > > akt;
    vector < vector < int > > id;
    vector < int > last;
    KMR(char *S) : s(S)
    {
        int n = strlen(s);
        for(int i = 0; i < n; i++)
            last.push_back(s[i]);
        id.push_back(last);
        for(int p = 2; p <= n; p <<= 1)
        {
            last.clear(), last.resize(n - p + 1, 0);
            akt.resize(n - p + 1);
            for(int i = 0; i <= n - p; i++)
                akt[i] = {{id.back()[i], id.back()[i + p / 2]}, i};
            sort(all(akt));
            int cnt = 0;
            for(int i = 1; i <= n - p; i++)
                last[akt[i].second] = (akt[i].first == akt[i - 1].first ? cnt : ++cnt);
            id.push_back(last);
        }
    }
    inline PII hash(int l, int r)
    {
        int lg = 31 - __builtin_clz(r - l + 1);
        return {id[lg][l], id[lg][r + 1 - (1 << lg)]};
    }
    bool equal(int l1, int r1, int l2, int r2)
    {
        if(r1 - l1 != r2 - l2) return false;
        return hash(l1, r1) == hash(l2, r2);
    }
    bool smaller(int l1, int r1, int l2, int r2)
    {
        if(r1 - l1 != r2 - l2) return (r1 - l1) < (r2 - l2);
        return hash(l1, r1) < hash(l1, r1);
    }
};

