#include<boost/multi_array.hpp>
#include<boost/optional.hpp>
#include<boost/range/irange.hpp>
#include<boost/range/algorithm.hpp>
#include<boost/range/adaptors.hpp>

namespace adaptor = boost::adaptors;

int answer(std::vector<std::string>const& field, int H, int W)
{
	boost::multi_array<bool, 2> count(boost::extents[H - 1][W - 1]);
	for (int i : boost::irange(0, H - 1))
	{
		for (int j : boost::irange(0, W - 1))
		{
			for (int a : {i, i + 1})
			{
				for (int b : {j, j + 1})
				{
					count[i][j] ^= field[a][b] == '#';
				}
			}
		}
	}
	boost::multi_array<int, 2> dp0(boost::extents[H][W]);
	boost::multi_array<int, 2> dp1(boost::extents[H][W]);
	for (int i : boost::irange(0, H))
	{
		dp0[i][W - 1] = dp1[i][W - 1] = 1;
		for (int k : boost::irange(0, W - 1) | adaptor::reversed)
		{
			dp0[i][k] = ((i != 0 && count[i - 1][k]) ? 0 : dp0[i][k + 1]) + 1;
			dp1[i][k] = ((i != H - 1 && count[i][k]) ? 0 : dp1[i][k + 1]) + 1;
		}
	}

	int max = 0;
	for (int k : boost::irange(0, W))
	{
		int local = dp0[0][k];
		std::stack<std::pair<int, int>> stack;
		std::vector<std::pair<int, int>>for_debug;
		auto emplace = [&](int i, int j)
		{
			stack.emplace(i, j);
			for_debug.emplace_back(i, j);
		};
		emplace(0, dp1[0][k]);
		for (int i : boost::irange(1, H))
		{
			auto left = stack.top().first;
			auto height = stack.top().second;
			local = std::max(local, (left - i + 1) * std::min(height, dp0[0][k]));
			if (height < dp1[i][k])
			{
				emplace(i, dp1[i][k]);
			}
			else if (dp1[i][k] < stack.top().second)
			{
				int last = left;
				while (stack.size() && dp1[i][k] < stack.top().second)
				{
					auto left = stack.top().first;
					auto height = stack.top().second;
					last = left;
					local = std::max(local, (i - left + 1) * height);
					stack.pop();
				}
				emplace(last, std::min(dp1[i][k], dp0[i][k]));
			}
		}
		while(stack.size())
		{
			auto left = stack.top().first;
			auto height = stack.top().second;
			local = std::max(local, (H - left) * std::min(height, dp1[H - 1][k]));
			stack.pop();
		}
		max = std::max(max, local);
	}
	return max;
}

void Main()
{
	int H, W;
	std::cin >> H >> W;
	std::vector<std::string> field(H);
	for (auto& str : field)
	{
		std::cin >> str;
	}
	std::cout << answer(field, H, W) << std::endl;
}

