                }
                if (sta.empty() or A[i][j] > sta.back().first) {
                    sta.emplace_back(A[i][j],pos);
                }
            }
            while (!sta.empty()) {
                auto[h,x] = sta.back(); sta.pop_back();
                chmax(ret,h*(M-1-x+1));
            }
        }

        return ret;
    };

