    bool found; // 条件を満たす範囲が見つかったか。falseの場合、begin,endは意味を持たない。
    int128_t begin; // [begin, end]で条件が成り立つ。
    int128_t end;

    BSR(bool found_in, int128_t begin_in, int128_t end_in) : found(found_in), begin(begin_in), end(end_in) {}
};

template<class Fn> BSR binary_search(int128_t L, int128_t R, Fn func) {
    const bool res_L = func(L);
    const bool res_R = func(R);
    if (res_L && res_R) {
        return BSR(true, L, R);
    } else if (!res_L && !res_R) {
        return BSR(false, 0, 0);
    } else {
        int128_t lb = L;
        int128_t ub = R;
        while (lb + 1 < ub) {
            int128_t mid = (lb + ub) / 2;
            if (res_L == func(mid)) {
                lb = mid;
            } else {
                ub = mid;
            }
        }
        return res_L ? BSR(true, L, lb) : BSR(true, ub, R);
    }
}

int128_t largest_rectangle(const std::vector<int128_t>& h) {
    std::vector<int128_t> st, L, R;
    L.resize(h.size()); R.resize(h.size());
    for (int i = 0; i < h.size(); i++) {
        while (0 < st.size() && h[i] <= h[st.back()]) { st.pop_back(); }
        L[i] = (st.size() == 0) ? 0 : st.back() + 1;
        st.push_back(i);
    }

    st.clear();
    for (int i = h.size() - 1; 0 <= i; i--) {
        while (0 < st.size() && h[i] <= h[st.back()]) { st.pop_back(); }
        R[i] = (st.size() == 0) ? h.size() : st.back();
        st.push_back(i);
    }

    int128_t res = 0;
    for (int i = 0; i < h.size(); i++) {
        //res = std::max(res, h[i] * (R[i] - L[i]));
        res = std::max(res, (h[i] + 1) * (R[i] - L[i] + 1));
    }
    return res;
}

