vector<vector<int>> grid_max_square(const vector<string> &s, char wall='#', char path='.'){
  assert(s.size()!=0);
  int n = (int)s.size();
  int m = (int)s[0].size();
  //dp[i][j]:= (i, j) からの辺の最大長
  //dp[i][j] = min(dp[i+1][j], dp[i+1][j+1], dp[i][j+1]) + 1
  vector<vector<int>> dp(n, vector<int>(m, 0));
  for(int i=n-1;i>=0;i--){
    for(int j=m-1;j>=0;j--){
      if(s[i][j]==wall) continue;
      int ans = 1000000000;
      if(i+1<n) ans = min(ans, dp[i+1][j]);
      if(j+1<m) ans = min(ans, dp[i][j+1]);
      if(i+1<n&&j+1<m) ans = min(ans, dp[i+1][j+1]);
      dp[i][j] = min({ans + 1, n-i, m-j});
    }
  }
  return dp;
}

#include <stack>
//L[i]/R[i] h[i]が最小値となる最大区間(閉区間)
pair<vll, vll> histogram_max_rectangle(const vector<ll>& h){
  int n = (int)h.size();
  vector<ll> L(n), R(n);
  stack<int> st;
  for(int i=0;i<n;i++){
    while(true){
      if(st.empty()){
        L[i] = 0;
        break;
      }
      int tmp = st.top();
      if(h[tmp]>=h[i]) {
        st.pop();
        continue;
      }
      L[i] = tmp + 1;
      break;
    }
    st.push(i);
  }
  st = stack<int>();
  for(int i=n-1;i>=0;i--){
    while(true){
      if(st.empty()){
        R[i] = n-1;
        break;
      }
      int tmp = st.top();
      if(h[tmp]>=h[i]) {
        st.pop();
        continue;
      }
      R[i] = tmp - 1;
      break;
    }
    st.push(i);
  }
  return {L, R};
}

