        if (st.sz()) Left[i] = st.top();
        else Left[i] = -1;
        st.push(i);
    }
    while (st.sz()) st.pop();
    REPD(i, p.sz()) {
        while (st.sz() && p[st.top()]>=p[i]) st.pop();
        if (st.sz()) Right[i] = st.top();
        else Right[i] = p.sz();
        st.push(i);
