int E[MAXN];

int LCP[MAXN];
int L[MAXN];
int R[MAXN];

int getHash(int v, int col, int i, int j) {
	return (H[v][j][col] - (LL) H[v][i - 1][col] * E[j - i + 1] + (LL) MOD * MOD) % MOD;
}

int computeLCP(int i, int j, int x, int y) {
	int l = 1, r = i, f = 0;
	while (l <= r) {
		int mid = (l + r) >> 1;
		if (getHash(x, j - 1, i - mid + 1, i) == getHash(y, j, i - mid + 1, i)) {
			f = mid;
			l = mid + 1;
		}
		else r = mid - 1;
	}
	return f;
}

int Compute(int i) {
	for (int j = 2; j <= m; ++j) LCP[j] = computeLCP(i, j, a[i][j - 1], a[i][j]);
	for (int j = 1; j <= m; ++j) {
		L[j] = j;
		while (1 < L[j] && LCP[L[j] - 1] >= LCP[j]) L[j] = L[L[j] - 1];
	}
	for (int j = m; j >= 1; --j) {
		R[j] = j;
		while (R[j] < m && LCP[R[j] + 1] >= LCP[j]) R[j] = R[R[j] + 1];
	}
	int ans = i;
	for (int j = 1; j <= m; ++j)
		ans = max(ans, LCP[j] * (R[j] - L[j] + 2));
	return ans;
}

