typedef long long lint;

int solve(const vector<int> &height) {
  int n = height.size();
  vector<int> to_left(n), to_right(n);
  {
    stack<int> st;
    for (int i = 0; i < n; ++i) {
      while (!st.empty() && height[st.top()] >= height[i])
        st.pop();
      if (st.empty()) to_left[i] = 0;
      else to_left[i] = st.top() + 1;
      st.push(i);
    }
  }
  {
    stack<int> st;
    for (int i = n - 1; i >= 0; --i) {
      while (!st.empty() && height[st.top()] >= height[i])
        st.pop();
      if (st.empty()) to_right[i] = n - 1;
      else to_right[i] = st.top() - 1;
      st.push(i);
    }
  }
  int result = 0;
  for (int i = 0; i < n; ++i)
    result = max(result, (to_right[i] - to_left[i] + 1 + 1) * height[i]);
  return result;
}

int main() {
  int nr, nc;
  scanf("%d %d", &nr, &nc);
  vector<vector<int>> field(nr, vector<int>(nc));
  for (int y = 0; y < nr; ++y) {
    string line(nc, ' ');
    scanf("%s", &line[0]);
    for (int x = 0; x < nc; ++x)
      field[y][x] = (line[x] == '#');
  }
  array<vector<int>, 2> lcp_down = {vector<int>(nr - 1), vector<int>(nr - 1)};
  int result = 0;
  for (int x = nc - 1; x >= 0; --x) {
    for (int y = 0; y + 1 < nr; ++y)
      for (int inv = 0; inv < 2; ++inv)
        if ((field[y][x] == field[y + 1][x]) ^ inv) ++lcp_down[inv][y];
        else lcp_down[inv][y] = 0;
    vector<int> lcps;
    for (int y = 0; y + 1 < nr; ++y) {
      int invy = field[y][x], invy1 = field[y + 1][x];
      lcps.push_back(lcp_down[invy ^ invy1][y]);
    }
    result = max(result, nc - x);
    result = max(result, solve(lcps));
  }
