struct RollingHash {
    const V<ll> bases;
    const V<ll> mods;
    VV<ll> pows;
    VV<ll> hashs;
    RollingHash(const V<ll> &s, const V<ll> bases = { 1007, 1009 }, const V<ll> mods = { (ll)1e9 + 7, (ll)1e9 + 9 }) 
        : bases(bases), mods(mods) 
    {
        assert(bases.size() == mods.size());
        for(ll i = 0; i < mods.size(); i++) {
            ll mod = mods[i];
            ll base = bases[i];
            V<ll> hash(s.size() + 1, 0);
            V<ll> _pow(s.size() + 1, 1);
            for(ll j = 0; j < s.size(); j++) {
                hash[j + 1] = (hash[j] + s[j]) * base % mod;
                _pow[j + 1] = _pow[j] * base % mod;
            }
            hashs.push_back(move(hash));
            pows.push_back(move(_pow));
        }
    }
    RollingHash() : RollingHash(V<ll>(0)) {}

    // [l, r)
    V<ll> get_hash(ll l, ll r) {
        V<ll> ret;
        for(ll i = 0; i < mods.size(); i++) {
            ll h = hashs[i][r] - hashs[i][l] * pows[i][r - l] % mods[i];
            h += mods[i];
            h %= mods[i];
            ret.push_back(h);
        }
        return move(ret);
    }
};

class UnionFind{
    using vec = vector<ll>;
    public:
        vec rank;
        vec parent;
        vec size;
        ll max_size;

        UnionFind(ll N){
            rank = vec(N, 0);
            parent = vec(N);
            size = vec(N, 1);
            max_size = 1;
            iota(parent.begin(), parent.end(), 0ll);
        }

        ~UnionFind(){
        }

        ll find(ll child){
            return (child == parent[child] ? child : parent[child] = find(parent[child]));
        }

        void unit(ll x, ll y){
            ll px = find(x);
            ll py = find(y);
            if(px == py){
                return;
            }
            if(rank[px] < rank[py]){
                swap(px, py);
            }
            parent[py] = px;
            size[px] += size[py];
            chmax(max_size, size[px]);
            rank[px] += (rank[px] == rank[py]);
        }

        ll get_max_size() { return max_size; }

        bool same(ll x, ll y){
            return (find(x) == find(y));
        }

};

