template <int n, int m>
int maximumRectangle(const int (&arr)[n][m], int w, int h){
    for(int i=0;i<w-1;++i){
        for(int j=0,k=0;j<h-1;j=k){
            while(k < h - 1 && arr[k][i] == 1){++k;}
            j = k;
            while(k < h - 1 && arr[k][i] == 0){
                acc[k][i] = k - j + 1;
                ++k;
            }
        }
    }

    // for(int i=0;i<=10;++i){
    //     for(int j=0;j<=8;++j){
    //         std::cout << std::setw(2) << acc[i][j];
    //     }
    //     std::cout << std::endl;
    // }

    int res = 0;
    for(int i=0;i<h-1;++i){
        std::stack<std::tuple<int, int>> st;
        st.emplace(0, acc[i][0]);
        for(int j=1;j<w;++j){
            int p, h;
            std::tie(p, h) = st.top();

            if(h < acc[i][j]){
                st.emplace(j, acc[i][j]);
            }else if(h > acc[i][j]){
                while(h >= acc[i][j]){
                    res = std::max(res, (j - p + 1) * (h + 1));
                    st.pop();
                    if(st.empty()){break;}
                    std::tie(p, h) = st.top();
                }

                st.emplace(p, acc[i][j]);
            }
        }
    }

    return res;
}

