      if (mp[i + 1][j] == '#')
        sum++;
      if (mp[i][j + 1] == '#')
        sum++;
      if (mp[i + 1][j + 1] == '#')
        sum++;
      if (sum % 2 == 1)
        ng[i + 1][j + 1] = true;
    }
  vector<vector<int>> table(h);
  for (int i = 0; i < h; i++) {
    table[i].resize(w);
    for (int j = 0; j < w; j++)
      table[i][j] = 1;
  }
