    for (int j = 0; j < w; j++) {
      v.push_back(table[i][j]);
      if (ng[i][j + 1] && ng[i + 1][j + 1]) {
        ans = max(ans, largestRectangleFromHist(v));
        v.clear();
      }
    }
  }
  cout << ans << endl;
  return 0;
}

