using namespace std;
const int maxn = 2020;
struct histogram_solver{
    static const int factor_h = 1;
    static const int factor_w = 1;
    static long long solve(vector<int> values){
        stack<int> s;
        int i = 0;
        long long ans = 0;
        while(i < values.size()){
            if(s.empty() || values[s.top()] <= values[i]) s.push(i++);
            else{
                int tp = s.top(); s.pop();
                long long area = 1ll * (values[tp] + factor_h) *
                    ((s.empty() ? i : i - s.top() - 1) + factor_w);
                ans = max(ans, area);
            }
        }
        while(!s.empty()){
            int tp = s.top(); s.pop();
            long long area = 1ll * (values[tp] + factor_h) *
                ((s.empty() ? i : i - s.top() - 1) + factor_w);.
            ans = max(ans, area);
        }
        return ans;
    }
};
