rect max_rectangle(ll *h, ll n) {
  struct item { ll h, p; };
  stack<item> stk;
  rect m = (rect) { 0, 0 };

  REP(i, 0, n + 1) {
    item r = (item) { i < n ? h[i] : 0, i };
    if(stk.empty()) {
      stk.push(r);
    } else {
      if(stk.top().h < r.h) stk.push(r);
      if(stk.top().h > r.h) {
        ll t = i;
        while(stk.size() && stk.top().h >= r.h) {
          item s = stk.top();
          stk.pop();
          s.h * (i - s.p);
          if(s.h * (i - s.p) > m.h * m.w) m = (rect) { s.h, i - s.p };
          t = s.p;
        }
        r.p = t;
        stk.push(r);
      }
    }
  }

  return m;
}

