  for(int i=0;i<badlocs.size();++i){
    //cout<<badlocs[i].x<<","<<badlocs[i].y<<endl;
  }

  // 最大長方形アルゴリズムの準備
  // http://algorithms.blog55.fc2.com/blog-entry-133.html
  int hists[H-1][W-1];

  for(int j=0;j<W-1;++j){
    int seq = 0;
    for(int i=0;i<H-1;++i){
      loc2d l;
      l.x = j;
      l.y = i;
      bool block = binary_search(badlocs.begin(),badlocs.end(),l,comp_loc2d);
      if(block){
	//cout<<"b"<<j<<","<<i<<endl;
	hists[i][j]=0;
	for(int l=0;l<seq;++l){
	  hists[i-1-l][j] = l+1;
	}
	seq = 0;
      }else{
	seq++;
	if(i == H-2){
	  for(int l=0;l<seq;++l){
	    hists[i-l][j] = l+1;
	  }
	}
      }
    }
  }
  for(int i=0;i<H-1;++i){
    for(int j=0;j<W-1;++j){
      //cout<<hists[i][j]<<",";
    }
    //cout<<endl;
  }

  // ヒストグラムの最大を取る
  stack<achist> acs;
  int maxv = -1;
  for(int i=0;i<H-1;++i){
    for(int j=0;j<W;++j){
      achist ac;
      if(j!=W-1){
	ac.id = j;
	ac.height = hists[i][j];
      }else{
	ac.id = W-1;
	ac.height = 0;
      }
      if(acs.empty()){
	acs.push(ac);
      }else{
	if(acs.top().height < ac.height){
	  acs.push(ac);
	}else if(acs.top().height > ac.height){
	  achist ac2;
	  ac2.height = ac.height;
	  while(!acs.empty() && acs.top().height >= ac.height){
	    const int v = (ac.id - acs.top().id+1) * (acs.top().height+1);
	    maxv = max(maxv,v);
	    ac2.id = acs.top().id;
	    acs.pop();
	  }
	  if(acs.empty()){
	    ac2.id = 0;
	  }
	  acs.push(ac2);

	}
      }
    }
  }
  cout<<maxv<<endl;
  return 0;
}

