	stack<ii> S;
	S.push(mp(vec[0],0));
	for(int i=1;i<n;i++)
	{
		while(!S.empty()&&S.top().fi>=vec[i])
		{
			S.pop();
		}
		if(S.empty()) L[i]=0;
		else L[i]=S.top().se+1;
		S.push(mp(vec[i],i));
	}
	while(!S.empty()) S.pop();
	S.push(mp(vec[n-1],n-1));
	R[n-1]=n-1;
	for(int i=n-2;i>=0;i--)
	{
		while(!S.empty()&&S.top().fi>=vec[i])
		{
			S.pop();
		}
		if(S.empty()) R[i]=n-1;
		else R[i]=S.top().se-1;
		S.push(mp(vec[i],i));
	}
	int ans=0;
	for(int i=0;i<n;i++)
	{
		ans=max(ans,(R[i]-L[i]+2)*vec[i]);
	}
	return ans;
}

