        h[1][i][1] = 0;
        if ( a[1][i] == b[1][i+1] ){
            h[1][i][1] = 1;
        }
    }
    for ( int i = 2; i <= n; i++ ){
        for ( int j = 1; j <= m - 1; j++ ){
            h[i][j][0] = 0;
            if ( a[i][j] == a[i][j+1] ){
                h[i][j][0] = 1 + h[i-1][j][0];
            }
            h[i][j][1] = 0;
            if ( a[i][j] == b[i][j+1] ){
                h[i][j][1] = 1 + h[i-1][j][1];
            }
        }
    }
    for ( int i = 1; i <= n; i++ ){
        int curMn = i;
        vector < pair < int, int > > st;
        st.pb( mp( 1, curMn ) );
        ans = max( ans, i );
        for ( int j = 1; j <= m - 1; j++ ){
            int curVal = max( h[i][j][0], h[i][j][1] );
            while( !st.empty() && ( ( st.back() ).se >= curVal ) ){
                ans = max( ans, ( st.back().se * ( j - st.back().fi + 1 ) ) );
                st.pop_back();
            }
            int prv = 0;
            if ( !st.empty() ){
                prv = ( st.back() ).fi;
            }
            prv++;
            ans = max( ans, ( j + 2 - prv ) * curVal );
            st.pb( mp( j, curVal ) );
        }
        for ( int j = 0; j < size(st); j++ ){
            ans = max( ans, st[j].se * ( m - st[j].fi + 1 ) );
        }
    }
    printf("%d\n",ans);
    return 0;
