            else mem[i][j] = mem[i][j - 1] + 1;
        }
    }
    for(int i = 1; i < W; i++)
    {
        stack<pii> S;
        for(int j = 1; j <= H; j++)
        {
            if(S.size() == 0)S.push(mk(j,mem[j][i]));
            else
            {
                if(S.top().se < mem[j][i])S.push(mk(j,mem[j][i]));
                else if(S.top().se > mem[j][i])
                {
                    int now1 = j;
                    while(S.size() && S.top().se >= mem[j][i])
                    {
                        pii now2 = S.top();
                        S.pop();
                        ans = max(ans,(now2.se + 1) * (j - now2.fi + 1));
                        now1 = now2.fi;
                    }
                    S.push(mk(now1,mem[j][i]));
                }
            }
        }
    }
    printf("%d\n",ans);
    return 0;
}

