		else Pos[i][j] = Pos[i - 1][j];
	}
	int ans = 0;
	For(i,1,n - 1) {
		int top = 0;
		sta[top] = (node){0,0};
		For(j,1,m - 1) {
			while(top && sta[top].y >= i - Pos[i][j]) top--;
			L[j] = j - sta[top].x;
			sta[++top] = (node){j,i - Pos[i][j]};
		}
		top = 0;
		sta[top] = (node){m,0};
		Fordown(j,m - 1,1) {
			while(top && sta[top].y >= i - Pos[i][j]) top--;
			R[j] = sta[top].x - j;
			sta[++top] = (node){j,i - Pos[i][j]};
		}
		For(j,1,m - 1) chkmax(ans,(i - Pos[i][j] + 1) * (L[j] + R[j]));
	}

	printf("%d\n",ans);

