ll max_rect(vector<ll> h){
  ll N = h.size();
  ll L[N], R[N];
  //L[i], j <= i かつh_(j-1) < h_iとなる最大のj
  //R[i], i < j かつh_j > h_iとなる最小のj
  //[L, R)
  stack<ll> sta;
  rep(i, N){
    while(!sta.empty() && h[sta.top()] >= h[i]) sta.pop();
    if(sta.empty()) L[i] = 0;
    else{
      L[i] = sta.top() + 1;//[)にするため
    }
    sta.push(i);
  }

  while(!sta.empty()) sta.pop();
  revrep(i, N){
    while(!sta.empty() && h[sta.top()] >= h[i]) sta.pop();
    if(sta.empty()) R[i] = N;
    else{
      R[i] = sta.top();
    }
    sta.push(i);
  }

  ll res = 0;
  rep(i, N){
    if(h[i] == 0 || R[i] == L[i]) continue;
    res = max(res, (h[i] + 1) * (R[i] - L[i] + 1));
  }
  return res;
}

