int find_maxArea(int idx, int h) {
   vector<int> stack;
   hist_size[1][idx] = -1;
   stack.push_back(1);
   for (int i = 2 ; i <= h ; ++i) {
      while (hist_size[stack.back()][idx] >= hist_size[i][idx]) {
         stack.pop_back();
      }
      b1[i] = stack.back();
      stack.push_back(i);
   } 

   stack.clear();
   hist_size[h + 1][idx] = -1;
   stack.push_back(h + 1);
   for (int i = h ; i > 1 ; --i) {
      while (hist_size[stack.back()][idx] >= hist_size[i][idx]) {
         stack.pop_back();
      }
      b2[i] = stack.back();
      stack.push_back(i);
   } 
   int ret = 0;
   for (int i = 2 ; i <= h ; ++i) {
      ret = max(ret, (b2[i] - b1[i]) * (hist_size[i][idx] + 1));
   }
   return ret;
}

int find_maxRect (int h, int w) {
   for (int i = h ; i > 1 ; --i) {
      hist_size[i][w] = !S1[i][w];
      for (int j = w - 1 ; j > 1 ; --j) {
         hist_size[i][j] = (!S1[i][j] ? hist_size[i][j + 1] + 1 : 0);
      }
   }
   int ret = 0;
   for (int j = 2 ; j <= w ; ++j) {
      ret = max(ret, find_maxArea(j, h));
   }
   return ret;
}

