   } 

   for (int i = 2 ; i <= h ; ++i) {
      S2[i] = S1[i - 1] ^ S1[i]; 
   }
   for (int j = 2 ; j <= w ; ++j) {
      for (int i = 1 ; i <= h ; ++i) {
         S1[i][j] = S2[i][j - 1] ^ S2[i][j];
      }
