#include <iostream>
#include <cstdio>
using namespace std;

int h, w;
char input[2001][2002];
int rl[2001][2000];
struct Rect{
	int h, w;
	Rect() {}
	Rect(int x, int y)
		: h(x), w(y)
	{}
}s[1999];


int main()
{
	int front, rear, pos, w_now, ans(0), t;

	scanf("%d%d", &h, &w);
	for (int i = 1; i <= h; ++i)
		scanf("%s", input[i] + 1);
	if (h == 1 || w == 1) {
		printf("%d\n", h * w);
		return 0;
	}
	for (int i = 1; i <= h; ++i)
		for (int j = 1; j < w; ++j) {
			input[i][j] = input[i][j] != input[i][j + 1];
			input[i][j] ^= input[i - 1][j];
		}
	for (int i = h; i > 2; --i)
		for (int j = 1; j < w; ++j)
			input[i][j] ^= input[i - 2][j];
	for (int i = 2; i <= h; ++i) {
		front = rear = 1;
		while (rear < w) {
			while (rear < w && !input[i][rear])
				++rear;
			while (front < rear) {
				rl[i][front] = rear - front;
				++front;
			}
			++rear, ++front;
		}
	}
	for (int j = 1; j < w; ++j) {
		pos = 0;
		s[pos++] = Rect(rl[2][j], 1);
		for (int i = 3; i <= h; ++i) {
			if (rl[i][j] > s[pos - 1].h)
				s[pos++] = Rect(rl[i][j], 1);
			else {
				w_now = 0;
				while (pos && rl[i][j] <= s[pos - 1].h) {
					w_now += s[pos - 1].w;
					ans < (t = (s[pos - 1].h + 1) * (w_now + 1)) && (ans = t);
					--pos;
				}
				s[pos++] = Rect(rl[i][j], w_now + 1);
			}
		}
		w_now = 0;
		while (pos) {
			w_now += s[pos - 1].w;
			ans < (t = (s[pos - 1].h + 1) * (w_now + 1)) && (ans = t);
			--pos;
		}
	}
	printf("%d\n", ans);
	return 0;
}

