const int MAXM = (int) 1e5+10;

///--------------------START-------------------------
int h,w;
char a[MAXN][MAXN];
int mark[MAXN][MAXN];
int b[MAXN][MAXN],c[MAXN][MAXN];

int cal(int i,int j){
//    printf("(%d,%d) : %c\n",i,j,a[i][j]);
    return a[i][j]=='.';
}

stack<int> S;
stack<int> wid;

int solve(int i){
    int ret=0;
    while(!S.empty()) S.pop();
    while(!wid.empty()) wid.pop();
    for(int j=1;j<=w+1;j++){
        int h1=(j==w+1) ? 0 : i-b[i][j]+1;
        int h2=(j==w+1) ? 0 : i-c[i][j]+1;
        int Wid=0;
        while(!S.empty()&&S.top()>=h1){
            Wid+=wid.top(); wid.pop();
            int x=S.top(); S.pop();
            ret=max(ret,x*Wid);
        }
        ret=max(ret,h1*(Wid+1));
        S.push(h1);
        wid.push(Wid);
        Wid=0;
        while(!S.empty()&&S.top()>=h2){
            Wid+=wid.top(); wid.pop();
            int x=S.top(); S.pop();
            ret=max(ret,x*Wid);
        }
        ret=max(ret,h2*(Wid+1));
        S.push(h2);
        wid.push(Wid+1);
    }
//    printf("i = %d : ret = %d\n",i,ret);
    return ret;
}

void work(){
    scanf("%d%d",&h,&w);
    for(int i=1;i<=h;i++) scanf("%s",a[i]+1);
    for(int i=1;i<=h;i++){
        for(int j=1;j<=w;j++){
            int x=cal(i,j)+cal(i,j+1)+cal(i+1,j)+cal(i+1,j+1);
            mark[i][j]=(x&1);
        }
    }
    for(int i=1;i<=h;i++){
        for(int j=1;j<=w;j++){
            if(i==1) b[i][j]=1;
            else if(mark[i-1][j-1]) b[i][j]=i;
            else b[i][j]=b[i-1][j];

            if(i==1) c[i][j]=1;
            else if(mark[i-1][j]) c[i][j]=i;
            else c[i][j]=c[i-1][j];
        }
    }
    int ans=0;
    for(int i=1;i<=h;i++){
        ans=max(ans,solve(i));
    }
    printf("%d\n",ans);
}

