    rep (i, h) {
        string tmp; CIN(tmp);
        grid.pb(tmp);
    }

    S ll hs[4] = {0, 0, 1, 1};
    S ll ws[4] = {0, 1, 0, 1};
    S bool ngs[2010][2010];
    memset(ngs, 0, sizeof(ngs));
    rep (hh, h-1) rep (ww, w-1) {
        ll cnt = 0;
        rep (i, 4) cnt += (grid[hh+hs[i]][ww+ws[i]] == '#');
        if (cnt & 1LL) ngs[hh][ww] = true;
    }

#if DEBUG
    debug_printf("---- ngs\n");
    rep (hh, h-1) {
        rep (ww, w-1) {
            debug_printf("%d ", ngs[hh][ww]);
        }
        debug_printf("\n");
    }
#endif // DEBUG

    S V<ll> ptss_wh[2010];
    rep (hh, h) rep (ww, w) if (ngs[hh][ww]) ptss_wh[ww].pb(hh);

    ll ans = 0;
    ll id = 0;
    set<ll> ptsset_orig; ptsset_orig.insert(-1); ptsset_orig.insert(w-1);
    set<t2> m_lenset_orig; m_lenset_orig.insert(t2(-w, id++));

    rep (hs, h) {
        set<ll> ptsset = ptsset_orig;
        set<t2> m_lenset = m_lenset_orig;

        S V<ll> pts_hw_wait[2010];
        rep (ww, w) pts_hw_wait[ww].clear();
        rep (ww, w) {
            auto iter = lower_bound(ALL(ptss_wh[ww]), hs);
            if (iter == ptss_wh[ww].end()) continue;
            pts_hw_wait[*iter].pb(ww);
        }

        srep (he, hs+1, h+1) {
            auto ml = *(m_lenset.begin());
            ll len = -get<0>(ml);
            ans = max(ans, (he-hs) * len);

            for (auto ww : pts_hw_wait[he-1]) {
                auto iter = ptsset.lower_bound(ww);
                ll w2 = *iter;
                iter--;
                ll w1 = *iter;
                auto to_delete = m_lenset.lower_bound(t2(-(w2-w1), -1));
                m_lenset.erase(to_delete);
                ptsset.insert(ww);
                m_lenset.insert(t2(-(ww-w1), id++));
                m_lenset.insert(t2(-(w2-ww), id++));
            }
        }
    }

    debug_printf("---- ans\n");
    cout << ans << endl;
}

