std::pair<int, int> getMaxRectangleArea(const std::vector<int>& v) {
	std::pair<int, int> res(0, 0);
	int max = 0;
	int w = v.size();
	struct P { int pos, height; };
	std::stack<P> st;
	for (int i = 0; i < w; ++i) {
		if (st.empty()) {
			st.push(P{ i, v[i] });
		}
		else if (st.top().height < v[i]) {
			st.push(P{ i, v[i] });
		}
		else if (st.top().height > v[i]) {
			while (!st.empty() && st.top().height > v[i]) {
				int area = st.top().height * (i - st.top().pos);
				if (max < area) {
					max = area;
					res = std::make_pair(st.top().height, i - st.top().pos);
				}
				st.pop();
			}
			st.push(P{ i, v[i] });
		}
	}
	while (!st.empty()) {
		int area = st.top().height * (w - st.top().pos);
		if (max < area) {
			max = area;
			res = std::make_pair(st.top().height, w - st.top().pos);
		}
		st.pop();
	}
	return res;
}

