#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int max_n=2005;
int n,m;
char s[max_n][max_n];
int h[max_n];
int l[max_n],r[max_n];
int main(){
    scanf("%d%d",&n,&m);
    for(int i=1;i<=n;i++)scanf(" %s",s[i]+1);
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++)s[i][j]=s[i][j]=='#';
    }
    int ans=0;
    for(int i=1;i<=n;i++){
        if(i==1){
            for(int j=2;j<=m;j++)h[j]=1;
        }
        else{
            for(int j=2;j<=m;j++){
                int x=s[i][j]^s[i-1][j]^s[i][j-1]^s[i-1][j-1];
                if(x==1)h[j]=1;
                else h[j]++;
            }
        }
        stack<int> stk;
        for(int j=2;j<=m;j++){
            while(!stk.empty()&&h[stk.top()]>=h[j])stk.pop();
            l[j]=stk.empty()?1:stk.top();
            stk.push(j);
        }
        while(!stk.empty())stk.pop();
        for(int j=m;j>=2;j--){
            while(!stk.empty()&&h[stk.top()]>=h[j])stk.pop();
            r[j]=stk.empty()?m+1:stk.top();
            stk.push(j);
        }
        for(int j=2;j<=m;j++)ans=max(ans,h[j]*(r[j]-l[j]));
    }
    printf("%d\n",ans);
    return 0;
}

