	//ヒストグラムの最大長方形
	ll ans=0;
	sp=0;
	rep(j,0,w){
		if(sp==0||ss[base][stac[sp-1]]<ss[base][j]){
			stac[sp++]=j;
		}else{
			while(sp>0&&ss[base][stac[sp-1]]>ss[base][j]){
				ll jj=stac[sp-1];
				ll menseki=(ss[base][jj]+1)*(j-jj+1);//<--面積の計算が違う
				ans=max(ans,menseki);
				sp--;
			}
		}
	}
	while(sp>0){
		ll jj=stac[sp-1];
		ll menseki=(ss[base][jj]+1)*(w-jj+1);
