ll sp,sh[2010],si[2010];
ll f(int base){
	//ヒストグラムの最大長方形
	ll ans=0;
	sp=0;
	rep(j,0,w){
		if(sp==0||sh[sp-1]<ss[base][j]){
			si[sp]=j;
			sh[sp]=ss[base][j];
			sp++;
		}else{
			int jj=-1;
			while(sp>0&&sh[sp-1]>=ss[base][j]){
				jj=si[sp-1];
				ll menseki=(sh[sp-1]+1)*(j-jj+1);//<--面積の計算が違う
				ans=max(ans,menseki);
				sp--;
			}
			if(jj!=-1){
				si[sp]=jj;
				sh[sp]=ss[base][j];
				sp++;
			}
		}
	}
	while(sp>0){
		ll jj=si[sp-1];
		ll menseki=(sh[sp-1]+1)*(w-jj+1);
		ans=max(ans,menseki);
		sp--;
	}
	return ans;
}

