fun solve() {
    val (h, w) = inf.readLine().split(' ').map(String::toInt)
    val s = Array(h) { inf.readLine().toCharArray() }
    val cm = Array(h - 1) { i -> IntArray(w + 1) { j -> if (j == 0 || s[i][j - 1] == s[i + 1][j - 1]) 0 else 1 } }
    cm.forEach { a -> for (i in 1 until a.size) a[i] += a[i - 1] }
    var ans = 0
    for (i in 0 until w) {
        for (j in i until w) {
            ans = Math.max(ans, j - i + 1)
            var pr = 0
            for (k in 1 until h) {
                val cc = cm[k - 1][j + 1] - cm[k - 1][i]
                if (cc == 0 || cc == j - i + 1) {
                    ans = Math.max(ans, (j - i + 1) * (k - pr + 1))
                } else {
                    pr = k
                }
            }
        }
    }
    ouf.println(ans)
}

