          if (i==0) {
            hist[i][j]=1;
          } else {
            hist[i][j]=hist[i-1][j]+1;
          }
        } else {
          hist[i][j]=0;
        }
      }
    }

    Stack<int[]> stack = new Stack<>();
    for (int i=0; i<h-1; i++) {
      if (!stack.isEmpty()) {
        for (int[] tmp: stack) {
          max = Math.max(max, (long)(tmp[0]+1)*(w-tmp[1]));
        }
        stack.clear();
      }

      for (int j=0; j<w-1; j++) {
        int th = hist[i][j];
        if (th==0) {
          for (int[] tmp: stack) {
            max = Math.max(max, (long)(tmp[0]+1)*(j-tmp[1]+1));
          }
          stack.clear();
          continue;
        }

        if (stack.isEmpty()) {
          stack.push(new int[]{th,j});
        } else {
          Stack<int[]> mini = new Stack<>();
          while (!stack.isEmpty()) {
            int[] tmp = stack.pop();
            if (tmp[0]<th) {
              stack.push(tmp);
              stack.push(new int[]{th,j});
              break;
            } else if (tmp[0]==th) {
              stack.push(tmp);
              break;
            } else {
              mini.push(tmp);
            }
          }
          if (!mini.isEmpty()) {
            int tw = mini.peek()[1];
            stack.push(new int[]{th,tw});
            for (int[] tmp: mini) {
              max = Math.max(max, (long)(tmp[0]+1)*(j-tmp[1]+1));
            }
            mini.clear();
          }
        }
      }
    }
    if (!stack.isEmpty()) {
      for (int[] tmp: stack) {
        max = Math.max(max, (long)(tmp[0]+1)*(w-tmp[1]));
      }
      stack.clear();
    }

    System.out.println(max);
  }
}

