import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int h = In.ni();
        int w = In.ni();
        boolean[][] g = In.grid(h, w, '#');
        for (int i = h - 1; i > 0; i--) for (int j = 0; j < w; j++) {
            g[i][j] = !(g[i][j] ^ g[i - 1][j]);
        }
        for (int j = 0; j < w; j++) g[0][j] = true;
        for (int j = w - 1; j > 0; j--) for (int i = 0; i < h; i++) {
            g[i][j] = !(g[i][j] ^ g[i][j - 1]);
        }
        for (int i = 0; i < h; i++) g[i][0] = false;
        int[][] hst = new int[h][w];
        for (int j = 0; j < w; j++) hst[h - 1][j] = g[h - 1][j] ? 1 : 0;
        for (int i = h - 2; i >= 0; i--) for (int j = 0; j < w; j++) {
            hst[i][j] = g[i][j] ? hst[i + 1][j] + 1 : 0;
        }
        int max = 0;
        for (int i = 0; i < h; i++) {
            if (i < h - 1) {
                for (int j = 1; j < w; j++) hst[i][j] = hst[i + 1][j] + 1;
            }
            max = Math.max(max, histRectMax(hst[i]));
        }
        int m = Math.max(h, w);
        out.append(Math.max(m, max));
    }

    public static int histRectMax(int[] h) {
        final int n = h.length;
        Stack<int[]> s = new Stack<>();
        int max = 0;
        for (int j = 0; j < n; j++) {
            int hj = h[j];
            if (s.size() == 0) {
                s.add(new int[]{j, hj});
            } else {
                int[] top = s.peek();
                if (top[1] < hj) {
                    s.add(new int[]{j, hj});
                } else if (top[1] > hj) {
                    while (s.size() > 0 && s.peek()[1] >= hj) {
                        top = s.poll();
                        max = Math.max(max, top[1] * (j - top[0] + 1));
                    }
                    s.add(new int[]{top[0], hj});
                }
            }
        }
        int[] top;
        while (s.size() > 0) {
            top = s.poll();
            max = Math.max(max, top[1] * (n - top[0] + 1));
        }
        return max;
    }
}


