public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni(), m = ni();
		char[][] map = nm(n,m);
		int[][] imap = new int[n][m];
		for(int i = 0;i < n;i++){
			for(int j = 0;j < m;j++){
				imap[i][j] = map[i][j] == '#' ? 1 : 0;
			}
		}

		int[][][] h = new int[2][n][m-1];
		for(int i = 0;i < m-1;i++){
			for(int k = 0;k < 2;k++){
				int p = 0;
				for(int j = 0;j < n;j++){
					if(imap[j][i] == (imap[j][i+1]^k)){
						h[k][j][i] = ++p;
					}else{
						h[k][j][i] = 0;
					}
				}
			}
		}

		long ans = 0;
		for(int i = 0;i < n;i++){
			int[] lcp = new int[m-1];
			for(int j = 0;j < m-1;j++){
				lcp[j] = h[imap[i][j]^imap[i][j+1]][i][j];
			}
			ans = Math.max(ans, maxRect(lcp));
		}
		out.println(ans);
	}

	public static long maxRect(int[] a)
	{
		int n = a.length;
		int[] stack = new int[n];
		int[] left = new int[n];
		int p = 0;
		long max = 0;
		for(int i = 0;i < n;i++){
			int o = p;
			while(p > 0 && stack[p-1] >= a[i]){
				p--;
				max = Math.max(max, (long)(i-1-left[p]+1+1)*stack[p]);
			}
			if(o == p)left[p] = i;
			stack[p++] = a[i];
		}
		while(p > 0){
			p--;
			max = Math.max(max, (long)(n-1-left[p]+1+1)*stack[p]);
		}
		return max;
	}


	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

