import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskF solver = new TaskF();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskF {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int height = in.nextInt();
			int width = in.nextInt();
			char[][] s = new char[height][];
			for (int r = 0; r < height; r++) {
				s[r] = in.next().toCharArray();
			}
			boolean[][] a = new boolean[height - 1][width - 1];
			for (int r = 1; r < height; r++) {
				for (int c = 1; c < width; c++) {
					int k = 0;
					for (int dr = -1; dr <= 0; dr++) {
						for (int dc = -1; dc <= 0; dc++) {
							if (s[r + dr][c + dc] == '.') {
								++k;
							}
						}
					}
					if (k % 2 == 0) {
						a[r - 1][c - 1] = true;
					}
				}
			}
			out.println(maxRectangleOfOnes(a));
		}

		private int maxRectangleOfOnes(boolean[][] a) {
			// false for 0, true for 1
			int height = a.length;
			int width = a[0].length;
			int[] prevMaxUp = new int[width];
			int[] maxUp = new int[width];
			int[] stack = new int[width];
			int[] left = new int[width];
			int[] right = new int[width];
			int maxArea = 0;
			for (int r = 0; r < height; r++) {
				for (int c = 0; c < width; c++) {
					if (a[r][c]) {
						maxUp[c] = 1;
						if (r > 0) {
							maxUp[c] += prevMaxUp[c];
						}
					} else {
						maxUp[c] = 0;
					}
				}

				int sp = 0;
				for (int c = 0; c < width; c++) {
					while (sp > 0) {
						if (maxUp[c] <= maxUp[stack[sp - 1]]) {
							--sp;
						} else {
							break;
						}
					}
					if (sp == 0) {
						left[c] = 0;
					} else {
						left[c] = stack[sp - 1] + 1;
					}
					stack[sp++] = c;
				}

				sp = 0;
				for (int c = width - 1; c >= 0; c--) {
					while (sp > 0) {
						if (maxUp[c] <= maxUp[stack[sp - 1]]) {
							--sp;
						} else {
							break;
						}
					}
					if (sp == 0) {
						right[c] = width - 1;
					} else {
						right[c] = stack[sp - 1] - 1;
					}
					stack[sp++] = c;
				}

				for (int c = 0; c < width; c++) {
//				maxArea = Math.max(maxArea, (right[c] - left[c] + 1) * maxUp[c]);
					maxArea = Math.max(maxArea, (right[c] - left[c] + 2) * (maxUp[c] + 1));
				}
				int[] tmp = maxUp;
				maxUp = prevMaxUp;
				prevMaxUp = tmp;
			}
			return maxArea;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					st = new StringTokenizer(in.readLine());
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;


public class Main {
    public static void main(String[] args) {
        StringBuilder out = new StringBuilder();
        solve(out);
        PrintWriter pw = new PrintWriter(System.out);
        pw.println(out);
        pw.flush();
        pw.close();
    }

    public static void solve(StringBuilder out) {
        int h = In.ni();
        int w = In.ni();
        boolean[][] g = In.grid(h, w, '#');
        for (int i = h - 1; i > 0; i--) for (int j = 0; j < w; j++) {
            g[i][j] = !(g[i][j] ^ g[i - 1][j]);
        }
        for (int j = 0; j < w; j++) g[0][j] = true;
        for (int j = w - 1; j > 0; j--) for (int i = 0; i < h; i++) {
            g[i][j] = !(g[i][j] ^ g[i][j - 1]);
        }
        for (int i = 0; i < h; i++) g[i][0] = false;
        int[][] hst = new int[h][w];
        for (int j = 0; j < w; j++) hst[h - 1][j] = g[h - 1][j] ? 1 : 0;
        for (int i = h - 2; i >= 0; i--) for (int j = 0; j < w; j++) {
            hst[i][j] = g[i][j] ? hst[i + 1][j] + 1 : 0;
        }
        int max = 0;
        for (int i = 0; i < h; i++) {
            if (i < h - 1) {
                for (int j = 1; j < w; j++) hst[i][j] = hst[i + 1][j] + 1;
            }
            max = Math.max(max, histRectMax(hst[i]));
        }
        out.append(max);
    }

    public static int histRectMax(int[] h) {
        final int n = h.length;
        Stack<int[]> s = new Stack<>();
        int max = 0;
        for (int j = 0; j < n; j++) {
            int hj = h[j];
            if (s.size() == 0) {
                s.add(new int[]{j, hj});
            } else {
                int[] top = s.peek();
                if (top[1] < hj) {
                    s.add(new int[]{j, hj});
                } else if (top[1] > hj) {
                    while (s.size() > 0 && s.peek()[1] >= hj) {
                        top = s.poll();
                        max = Math.max(max, top[1] * (j - top[0] + 1));
                    }
                    s.add(new int[]{top[0], hj});
                }
            }
        }
        int[] top;
        while (s.size() > 0) {
            top = s.poll();
            max = Math.max(max, top[1] * (n - top[0] + 1));
        }
        return max;
    }
}


