final class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) return true;
        ptr = 0;
        try {buflen = in.read(buffer);}
        catch (final IOException e) {e.printStackTrace();}
        return buflen > 0;
    }
    private int readByte() {return hasNextByte() ? buffer[ptr++] : -1;}
    public boolean hasNext() {
        while (hasNextByte() && !(33 <= buffer[ptr] && buffer[ptr] <= 126)) ptr++;
        return hasNextByte();
    }
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        final StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (33 <= b && b <= 126) {sb.appendCodePoint(b); b = readByte();}
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {minus = true; b = readByte();}
        if (b < '0' || '9' < b) throw new NumberFormatException();
        for (; ; b = readByte()) {
            if ('0' <= b && b <= '9') n = n * 10 + b - '0';
            else if (b == -1 || !(33 <= b && b <= 126)) return minus ? -n : n;
            else throw new NumberFormatException();
        }
    }
    public int nextInt() {return Math.toIntExact(nextLong());}
    public double nextDouble() {return Double.parseDouble(next());}
}


@SuppressWarnings("unchecked")
class Stack<T> {
    private static final int DEFAULT_SIZE = 64;
    private T[] s;
    private int size;
    private int tail = 0;
    public Stack(final int capacity) {this.s = (T[]) new Object[capacity];this.size = capacity;}
    public Stack() {this(DEFAULT_SIZE);}
    public T peek() {
        if (tail == 0) throw new NoSuchElementException("No Elements.");
        return s[tail - 1];
    }
    public T getFromHead(int index) {
        if (index >= tail || index < 0) throw new NoSuchElementException("index out of Bounds.");
        return s[index];
    }
    public T getFromTail(int index) {
        if (index >= tail || index < 0) throw new NoSuchElementException("index out of Bounds.");
        return s[tail - 1 - index];
    }
    public void add(final T v) {
        if (tail == size) grow();
        s[tail++] = v;
    }
    public void add(final T... vals) {for (T v : vals) add(v);}
    public T poll() {
        if (tail == 0) throw new NoSuchElementException("No Elements.");
        return s[--tail];
    }
    public int size() {return tail;}
    private void grow() {
        final T[] grown = (T[]) new Object[size << 1];
        System.arraycopy(s, 0, grown, 0, tail);
        s = grown;
        size <<= 1;
    }
    public Iterator<T> iterator() {return new StackIterator();}
    private class StackIterator implements Iterator<T> {
        private int i = tail - 1;
        public boolean hasNext() {return i >= 0;}
        public T next() {return s[i--];}
    }
}

import java.util.Scanner;
import java.util.Stack;

public class Main {
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int h = sc.nextInt();
    int w = sc.nextInt();
    int[][] mat = new int[h][w];
    int max = Math.max(h, w);

    for (int i=0; i<h; i++) {
      char[] tmp = sc.next().toCharArray();
      for (int j=0; j<w; j++) {
        if (tmp[j]=='#')
          mat[i][j] = 1;
        else
          mat[i][j] = 0;
      }
    }
    sc.close();

    boolean[][] n_mat = new boolean[h-1][w-1];
    for (int i=0; i<h-1; i++) {
      for (int j=0; j<w-1; j++) {
        if ((mat[i][j]+mat[i+1][j]+mat[i][j+1]+mat[i+1][j+1])%2==0)
          n_mat[i][j]=true;
        else
          n_mat[i][j]=false;
      }
    }

    int[][] hist = new int[h-1][w-1];
    for (int i=0; i<h-1; i++) {
      for (int j=0; j<w-1; j++) {
        if (n_mat[i][j]) {
          if (i==0) {
            hist[i][j]=1;
          } else {
            hist[i][j]=hist[i-1][j]+1;
          }
        } else {
          hist[i][j]=0;
        }
      }
    }

    Stack<int[]> stack = new Stack<>();
    for (int i=1; i<h-1; i++) {
      if (!stack.isEmpty()) {
        for (int[] tmp: stack) {
          max = Math.max(max, (tmp[0]+1)*(w-tmp[1]));
        }
        stack.clear();
      }

      for (int j=0; j<w-1; j++) {
        if (!n_mat[i][j]) {
          for (int[] tmp: stack) {
            max = Math.max(max, (tmp[0]+1)*(j-tmp[1]+1));
          }
          stack.clear();
          continue;
        }

        int th = hist[i][j];
        if (stack.isEmpty()) {
          stack.push(new int[]{th,j});
        } else {
          Stack<int[]> mini = new Stack<>();
          while (!stack.isEmpty()) {
            int[] tmp = stack.pop();
            if (tmp[0]<th) {
              stack.push(tmp);
              stack.push(new int[]{th,j});
              break;
            } else if (tmp[0]==th) {
              stack.push(tmp);
              break;
            } else {
              mini.push(tmp);
            }
          }
          if (!mini.isEmpty()) {
            int tw = mini.peek()[1];
            stack.push(new int[]{th,tw});
            for (int[] tmp: mini) {
              max = Math.max(max, (tmp[0]+1)*(j-tmp[1]+1));
            }
          }
        }
      }
    }
    if (!stack.isEmpty()) {
      for (int[] tmp: stack) {
        max = Math.max(max, (tmp[0]+1)*(w-tmp[1]));
      }
      stack.clear();
    }

    System.out.println(max);
  }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.Function;

public class Main {

    static int H, W;
    static char[][] C;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        C = new char[H][];
        for (int i = 0; i < H; i++) {
            C[i] = sc.next().toCharArray();
        }

        System.out.println(solve());
    }

    static long solve() {
        int[][] D = new int[H-1][W-1];

        for (int h = 0; h < H-1; h++) {
            for (int w = 0; w < W-1; w++) {
                D[h][w] = isOk(h, w) ? 1 : 0;
            }
        }

        // 1 1 0 1 1 -> 1 2 0 1 2
        // 縦に
        for (int w = 0; w < W-1; w++) {
            for (int h = 0; h < H-1; h++) {
                if( D[h][w] == 1 ) {
                    D[h][w] += h == 0 ? 0 : D[h-1][w];
                }
            }
        }

        long ans = Math.max(H, W); // 最悪でも一列(行)は確保できる
        for (int h = 0; h < H-1; h++) {
            ans = Math.max(maxRectPlus(D[h]), ans);
        }
        return ans;
    }

    static int[] DH = {0, 1, 0, 1};
    static int[] DW = {0, 0, 1, 1};

    static boolean isOk(int h, int w) {
        // h, wは左上
        int cnt = 0;
        for (int i = 0; i < 4; i++) {
            if( C[h + DH[i]][w + DW[i]] == '#' ) cnt++;
        }
        return cnt % 2 == 0;
    }

    static long maxRectPlus(int[] a) {
        int n = a.length;
        int[] stack = new int[n];
        int[] left = new int[n];
        int p = 0;
        long max = 0;
        for(int i = 0; i < n; i++){
            int o = p;
            while(p > 0 && stack[p-1] >= a[i]) {
                p--;
                int w = i-1-left[p]+1;
                int h = stack[p];
                max = Math.max(max, (long)(w+1)*(h+1));
            }
            if(o == p) left[p] = i;
            stack[p++] = a[i];
        }
        while(p > 0) {
            p--;
            int w = n-1-left[p]+1;
            int h = stack[p];
            max = Math.max(max, (long)(w+1)*(h+1));
        }
        return max;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
