	private static final int maxN = (int) 2e3 + 5;
	private static final int maxM = (int) 1e6 + 5;
	private static final int inf = (int) 1e9 + 7;

	private static int N, M;
	private static String[] s = new String[maxN];
	private static int[] h = new int[maxN];
	private static int[] stack = new int[maxN];
	private static int top;
	private static int[] lef = new int[maxN];
	private static int[] rig = new int[maxN];

	private static void init() {

	}

	private static void enter() throws IOException {
		N = nextInt(); M = nextInt();
		for (int i = 1; i <= N; ++i) {
			s[i] = nextLine();
			s[i] = '!' + s[i];
		}
	}

	private static boolean ok(int i, int j) {
		if (j > M) return true;
		if (i == 1) return true;
		int num = ((s[i - 1].charAt(j - 1) - '#') + (s[i - 1].charAt(j) - '#')
		+ (s[i].charAt(j - 1) - '#') + (s[i].charAt(j) - '#'));
		return num % 2 == 0;
	}

	private static void solve() throws IOException {
		int res = 0;
		for (int i = 1; i <= N; ++i) {
			h[1] = h[1] + 1;
			for (int j = 2; j <= M + 1; ++j) {
				if (ok(i, j)) {
					h[j] += 1;
				}
				else {
					h[j] = 1;
				}
			}

			top = 0;

			for (int j = 1; j <= M + 1; ++j) {
				while (top > 0 && h[stack[top]] >= h[j]) --top;
				if (top == 0) lef[j] = 1;
				else lef[j] = stack[top];
				stack[++top] = j;
			}

			top = 0;

			for (int j = M + 1; j >= 1; --j) {
				while (top > 0 && h[stack[top]] >= h[j]) --top;
				if (top == 0) rig[j] = M + 1;
				else rig[j] = stack[top];
				stack[++top] = j;
			}

			for (int j = 1; j <= M + 1; ++j) {
				res = Math.max(res, h[j] * (rig[j] - lef[j]));
			}
		}

		output.println(res);
	}

	public static void main(String[] args) throws IOException {
		openFile();
		init();
		enter();
		solve();
		output.close();
	}
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		int h = sc.nextInt();
		int w = sc.nextInt();
		int[][] s = new int[h][w];
		for (int i = 0; i < h; ++i) {
			char[] S = new char[w];
			S = sc.next().toCharArray();
			for (int j = 0; j < w; ++j) {
				if (S[j] == '#') {
					s[i][j] = 1;
				}
			}
		}
		int[][] map = new int[h - 1][w - 1];
		for (int i = 0; i + 1 < h; ++i) {
			for (int j = 0; j + 1 < w; ++j) {
				if ((s[i][j] + s[i + 1][j] + s[i + 1][j + 1] + s[i][j + 1]) % 2 != 0) {
					++map[i][j];
				}
			}
		}
		int ans = solver(map);
		ans = Math.max(ans, h);
		ans = Math.max(ans, w);
		System.out.println(ans);
	}

	int solver(int[][] map) {
		int h = map.length;
		int w = map[0].length;
		int[][] cum = new int[2][w];
		int ans = 2;
		for (int i = 0; i < h; ++i) {
			for (int j = 0; j < w; ++j) {
				int c = map[i][j];// c==0で使用可能
				if (c == 0) {
					cum[i % 2][j] = (i > 0 ? cum[(i - 1) % 2][j] : 0) + 1;
				} else {
					cum[i % 2][j] = 0;
				}
			}
			ans = Math.max(ans, calc(cum[i % 2], w));

		}
		return ans;
	}

	int calc(int[] cum, int w) {
		int ans = 2;
		ArrayDeque<List<Integer>> stack = new ArrayDeque<>();
		for (int j = 0; j < w; ++j) {
			ans = Math.max(ans, cum[j]);
			int d = j;
			while (!stack.isEmpty() && (cum[j] == 0 || stack.peekLast().get(0) > cum[j])) {
				List<Integer> pair = stack.pollLast();
				ans = Math.max(ans, (pair.get(0) + 1) * (j - pair.get(1) + 1));
				d = Math.min(d, pair.get(1));
			}
			if (cum[j] == 0)
				continue;
			stack.addLast(Arrays.asList(cum[j], d));
		}
		while (!stack.isEmpty()) {
			List<Integer> pair = stack.pollLast();
			ans = Math.max(ans, (pair.get(0) + 1) * (w - pair.get(1) + 1));
		}
		return ans;
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.util.Scanner;
import java.util.Stack;

public class Main {
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int h = sc.nextInt();
    int w = sc.nextInt();
    int[][] mat = new int[h][w];
    int max = Math.max(h, w);

    for (int i=0; i<h; i++) {
      char[] tmp = sc.next().toCharArray();
      for (int j=0; j<w; j++) {
        if (tmp[j]=='#')
          mat[i][j] = 1;
        else
          mat[i][j] = 0;
      }
    }
    sc.close();

    boolean[][] n_mat = new boolean[h-1][w-1];
    for (int i=0; i<h-1; i++) {
      for (int j=0; j<w-1; j++) {
        if ((mat[i][j]+mat[i+1][j]+mat[i][j+1]+mat[i+1][j+1])%2==0)
          n_mat[i][j]=true;
        else
          n_mat[i][j]=false;
      }
    }

    int[][] hist = new int[h-1][w-1];
    for (int i=0; i<h-1; i++) {
      for (int j=0; j<w-1; j++) {
        if (n_mat[i][j]) {
          if (i==0) {
            hist[i][j]=1;
          } else {
            hist[i][j]=hist[i-1][j]+1;
          }
        } else {
          hist[i][j]=0;
        }
      }
    }

    Stack<int[]> stack = new Stack<>();
    for (int i=0; i<h-1; i++) {
      if (!stack.isEmpty()) {
        for (int[] tmp: stack) {
          max = Math.max(max, (tmp[0]+1)*(w-tmp[1]));
        }
        stack.clear();
      }

      for (int j=0; j<w-1; j++) {
        if (n_mat[i][j]) {
          int th = hist[i][j];
          if (stack.isEmpty()) {
            stack.push(new int[]{th,j});
          } else {
            Stack<int[]> mini = new Stack<>();
            while (!stack.isEmpty()) {
              int[] tmp = stack.pop();
              if (tmp[0]<th) {
                stack.push(tmp);
                stack.push(new int[]{th,j});
                break;
              } else if (tmp[0]==th) {
                stack.push(tmp);
                break;
              } else {
                mini.push(tmp);
              }
            }

            if (!mini.isEmpty()) {
              int tw = mini.peek()[1];
              stack.push(new int[]{th,tw});
              for (int[] tmp: mini) {
                max = Math.max(max, (tmp[0]+1)*(j-tmp[1]+1));
              }
            }
          }

        } else {
          if (!stack.isEmpty()) {
            for (int[] tmp: stack) {
              max = Math.max(max, (tmp[0]+1)*(j-tmp[1]+1));
            }
            stack.clear();
          }
        }
      }
    }
    if (!stack.isEmpty()) {
      for (int[] tmp: stack) {
        max = Math.max(max, (tmp[0]+1)*(w-tmp[1]));
      }
      stack.clear();
    }

    System.out.println(max);
  }
}

