    static class TaskC {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int m = in.readInt();
            int[][] boards = new int[n + 1][m + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (in.readChar() == '#') {
                        boards[i][j] = 1;
                    }
                }
            }

            int ans = Math.max(n, m);

            int[][] upRight = new int[n + 1][m + 1];
            for (int j = 1; j <= m; j++) {
                upRight[1][j] = m - j + 1;
            }
            for (int i = 2; i <= n; i++) {
                upRight[i][m] = 1;
                for (int j = m - 1; j >= 1; j--) {
                    upRight[i][j] = DigitUtils
                                    .isEven(boards[i][j] + boards[i - 1][j] + boards[i][j + 1] + boards[i - 1][j + 1])
                                                    ? upRight[i][j + 1] + 1
                                                    : 1;
                }
            }


            int[][] botRight = new int[n + 1][m + 1];
            for (int j = 1; j <= m; j++) {
                botRight[n][j] = m - j + 1;
            }
            for (int i = 1; i < n; i++) {
                botRight[i][m] = 1;
                for (int j = m - 1; j >= 1; j--) {
                    botRight[i][j] = DigitUtils
                                    .isEven(boards[i][j] + boards[i + 1][j] + boards[i][j + 1] + boards[i + 1][j + 1])
                                                    ? botRight[i][j + 1] + 1
                                                    : 1;
                }
            }

            int[][] upUntil = new int[n + 1][m + 1];
            int[][] botUntil = new int[n + 1][m + 1];

            IntDeque deque = new IntDeque(n);
            for (int j = 1; j <= m; j++) {
                deque.clear();
                for (int i = 1; i <= n; i++) {
                    while (!deque.isEmpty() && upRight[deque.peekLast()][j] >= upRight[i][j]) {
                        deque.removeLast();
                    }
                    if (deque.isEmpty()) {
                        upUntil[i][j] = 1;
                    } else {
                        upUntil[i][j] = deque.peekLast();
                    }
                    deque.addLast(i);
                }
            }

            for (int j = 1; j <= m; j++) {
                deque.clear();
                for (int i = n; i >= 1; i--) {
                    while (!deque.isEmpty() && botRight[deque.peekFirst()][j] >= botRight[i][j]) {
                        deque.removeFirst();
                    }
                    if (deque.isEmpty()) {
                        botUntil[i][j] = n;
                    } else {
                        botUntil[i][j] = deque.peekFirst();
                    }
                    deque.addFirst(i);
                }
            }

            for (int i = 2; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    int area1 = (botUntil[i - 1][j] - upUntil[i][j] + 1) * upRight[i][j];
                    int area2 = (botUntil[i - 1][j] - (i - 1) + 1) * upRight[i][j];
                    int area3 = (i - upUntil[i][j] + 1) * upRight[i][j];

                    ans = Math.max(ans, area1);
                    ans = Math.max(ans, area2);
                    ans = Math.max(ans, area3);
                }
            }

            out.println(ans);
        }

    }
    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public char readChar() {
            skipBlank();
            char c = (char) next;
            next = read();
            return c;
        }

    }
    static class FastOutput implements AutoCloseable, Closeable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput println(int c) {
            cache.append(c).append('\n');
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

    }
    static class DigitUtils {
        private static final long[] DIGIT_VALUES = new long[19];
        static {
            DIGIT_VALUES[0] = 1;
            for (int i = 1; i < 19; i++) {
                DIGIT_VALUES[i] = DIGIT_VALUES[i - 1] * 10;
            }
        }

        private DigitUtils() {}

        public static boolean isEven(int x) {
            return (x & 1) == 0;
        }

    }
    static class IntDeque {
        int[] data;
        int bpos;
        int epos;
        int cap;

        public IntDeque(int cap) {
            this.cap = cap + 1;
            this.data = new int[this.cap];
        }

        public boolean isEmpty() {
            return epos == bpos;
        }

        public int peekFirst() {
            return data[bpos];
        }

        private int last(int i) {
            return (i == 0 ? cap : i) - 1;
        }

        private int next(int i) {
            int n = i + 1;
            return n == cap ? 0 : n;
        }

        public int peekLast() {
            return data[last(epos)];
        }

        public int removeFirst() {
            int t = bpos;
            bpos = next(bpos);
            return data[t];
        }

        public int removeLast() {
            return data[epos = last(epos)];
        }

        public void addLast(int val) {
            data[epos] = val;
            epos = next(epos);
        }

        public void addFirst(int val) {
            data[bpos = last(bpos)] = val;
        }

        public void clear() {
            bpos = epos = 0;
        }

        public String toString() {
            StringBuilder builder = new StringBuilder();
            for (int i = bpos; i != epos; i = next(i)) {
                builder.append(data[i]).append(' ');
            }
            return builder.toString();
        }

    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		int h = sc.nextInt();
		int w = sc.nextInt();
		int[][] s = new int[h][w];
		for (int i = 0; i < h; ++i) {
			char[] S = new char[w];
			S = sc.next().toCharArray();
			for (int j = 0; j < w; ++j) {
				if (S[j] == '#') {
					s[i][j] = 1;
				}
			}
		}
		int[][] map = new int[h - 1][w - 1];
		for (int i = 0; i + 1 < h; ++i) {
			for (int j = 0; j + 1 < w; ++j) {
				if ((s[i][j] + s[i + 1][j] + s[i + 1][j + 1] + s[i][j + 1]) % 2 != 0) {
					++map[i][j];
				}
			}
		}
		System.out.println(solver(map));
	}

	int solver(int[][] map) {
		Scanner sc = new Scanner(System.in);
		int h = map.length;
		int w = map[0].length;
		int[][] cum = new int[2][w];
		int ans = 0;
		for (int i = 0; i < h; ++i) {
			for (int j = 0; j < w; ++j) {
				int c = map[i][j];// c==0で使用可能
				if (c == 0) {
					cum[i % 2][j] = (i > 0 ? cum[(i - 1) % 2][j] : 0) + 1;
				} else {
					cum[i % 2][j] = 0;
				}
			}
			ans = Math.max(ans, calc(cum[i % 2], w));

		}
		return ans;
	}

	int calc(int[] cum, int w) {
		int ans = 2;
		ArrayDeque<List<Integer>> stack = new ArrayDeque<>();
		for (int j = 0; j < w; ++j) {
			ans = Math.max(ans, cum[j]);
			int d = j;
			while (!stack.isEmpty() && (cum[j] == 0 || stack.peekLast().get(0) > cum[j])) {
				List<Integer> pair = stack.pollLast();
				ans = Math.max(ans, (pair.get(0) + 1) * (j - pair.get(1) + 1));
				d = Math.min(d, pair.get(1));
			}
			if (cum[j] == 0)
				continue;
			stack.addLast(Arrays.asList(cum[j], d));
		}
		while (!stack.isEmpty()) {
			List<Integer> pair = stack.pollLast();
			ans = Math.max(ans, (pair.get(0) + 1) * (w - pair.get(1) + 1));
		}
		return ans;
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

