class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int h = int.Parse(input[0]);
		int w = int.Parse(input[1]);
    string[] strings = new string[h];
    for(int i = 0; i < h; i++) strings[i] = Console.ReadLine();
    long[,] matrix = new long[h-1,w-1];//行列

    for(int i = 0; i < h-1; i++)//それぞれの行
    {
    	for(int j = 0; j < w-1; j++)
      {
        int countMemo = 0;
        if(strings[i][j] == '#') countMemo++;
        if(strings[i][j+1] == '#') countMemo++;
        if(strings[i+1][j] == '#') countMemo++;
        if(strings[i+1][j+1] == '#') countMemo++;
        if(countMemo % 2 == 0) matrix[i,j] = 1;
      }
    }

		Console.WriteLine(LargestRectangleArea(matrix));
	}

  static long LargestRectangleArea(long[,] uses)
  {//長方形上で1の書かれたマスだけを用いた長方形の最大面積をO(HW)で返す
    int h = uses.GetLength(0);
    int w = uses.GetLength(1);
    long answer = Math.Max(h+1,w);
    long[] heights = new long[w];
    for(int i = 0; i < h; i++)
    {
      for(int j = 0; j < w; j++)
      {
        if(uses[i,j] == 1) heights[j]++;
        else heights[j] = 0;
      }
      answer = Math.Max(answer,LargestRectangle(heights));
    }

    return answer;
  }

  static long LargestRectangle(long[] lengths)
  {//x軸に接する底辺1、高さlengthsの長方形を繋げた時、最大長方形の面積をO(n)で返す
    if(lengths.Length == 0) return 0;
    long answer = 2*(lengths[0]+1);
    int n = lengths.Length;
    var rectangleStack = new Stack<long[]>();//x座標と高さ
    rectangleStack.Push(new long[2]{0,lengths[0]});
    long[] topMemo = new long[2];

    for(int i = 1; i < n; i++)
    {
      if(rectangleStack.Count() > 0) topMemo = rectangleStack.Peek();

      if(topMemo[1] < lengths[i]) rectangleStack.Push(new long[2]{i,lengths[i]});
      else if(topMemo[1] > lengths[i])
      {
        long memo = 0;
        while(rectangleStack.Count() > 0)
        {
          if(rectangleStack.Peek()[1] > lengths[i])
          {
            answer = Math.Max(answer, (rectangleStack.Peek()[1]+1)*(i+1-rectangleStack.Peek()[0]));
            memo = rectangleStack.Peek()[0];

            if(rectangleStack.Count() == 1)
            {
              rectangleStack.Pop();
              rectangleStack.Push(new long[2]{memo, lengths[i]});
              break;
            }
            else rectangleStack.Pop();
          }else
          {
            rectangleStack.Push(new long[2]{memo, lengths[i]});
            break;
          }
        }
      }

      if(i == n-1 && rectangleStack.Count() > 0)
      {
        while(rectangleStack.Count() > 0)
        {
          answer = Math.Max(answer, (rectangleStack.Peek()[1]+1)*(i-rectangleStack.Peek()[0]+2));
          rectangleStack.Pop();
        }
      }
    }

    return answer;
  }

}

