fn maximal_rectangles(a: &[usize]) -> Vec<(usize, usize, usize)> {
    let mut ans = Vec::new();
    let mut stack = Vec::<(usize, usize)>::new();
    for (x1, y1) in std::iter::once(0)
        .chain(a.iter().copied().chain(std::iter::once(0)))
        .enumerate()
    {
        let mut x = x1;
        while let Some((x0, y0)) = stack.pop() {
            match y0.cmp(&y1) {
                Ordering::Less => {
                    stack.push((x0, y0));
                    stack.push((x, y1));
                    break;
                }
                Ordering::Equal => {
                    stack.push((x0, y0));
                    break;
                }
                Ordering::Greater => {
                    ans.push((x0, x1, y0));
                }
            }
            x = x0;
        }
        if stack.is_empty() {
            stack.push((x1, y1));
        }
    }
    ans
}

fn max_area(a: &[usize]) -> Option<usize> {
    maximal_rectangles(a)
        .iter()
        .map(|(start, end, y)| (end - start + 1) * y)
        .max()
}

