    let mut a = vec![vec![1; w - 1]; h - 1];
    for i in 0..h - 1 {
        for j in 0..w - 1 {
            if !g[i][j] {
                a[i][j] = i.checked_sub(1).map(|im1| a[im1][j] + 1).unwrap_or(2);
            }
        }
    }

    println!(
        "{}",
        a.iter()
            .map(|v| max_area(v.as_slice()).unwrap_or(0))
            .max()
            .unwrap()
    );
}

