fn solve() {
    let (h, w) = get!(usize, usize);
    let s: Vec<Vec<char>> = (0..h).map(|_| util::chars()).collect();

    if h == 1 || w == 1 {
        println!("{}", h * w);
        return;
    }

    let mut map = vec![vec![false; w - 1]; h - 1];

    for i in 0..h - 1 {
        for j in 0..w - 1 {
            let cnt = [s[i + 1][j + 1], s[i][j + 1], s[i + 1][j], s[i][j]]
                .into_iter()
                .filter(|&&c| c == '#')
                .count();

            if cnt % 2 == 1 {
                map[i][j] = true;
            }
        }
    }

    let mut hists = vec![vec![0; w]; h - 1];

    for i in 0..h - 1 {
        for j in 0..w - 1 {
            if map[i][j] {
                hists[i][j] = 0;
            } else {
                if i > 0 {
                    hists[i][j] = hists[i - 1][j] + 1;
                } else {
                    hists[i][j] = 1;
                }
            }
        }
    }

    let ans = hists
        .into_iter()
        .map(|hs| {
            let mut maxv = 0;
            let mut stack = Vec::new();

            for (i, h) in hs.into_iter().enumerate() {
                let h = h + 1;

                if let Some((_, last)) = stack.last().cloned() {
                    match h.cmp(&last) {
                        Ordering::Equal => (),
                        Ordering::Greater => {
                            stack.push((i, h));
                        }
                        Ordering::Less => {
                            let mut t = 0;
                            while !stack.is_empty() && h < stack.last().unwrap().1 {
                                let (j, k) = stack.pop().unwrap();
                                maxv = max(maxv, k * (i - j + 1));
                                t = j;
                            }
                            stack.push((t, h));
                        }
                    }
                } else {
                    stack.push((i, h));
                }
            }
            maxv
        })
        .max()
        .unwrap_or(0);

    println!("{}", max(ans, max(h, w)));
}

