    let ans = largest_rectangle_in_grid(h - 1, w - 1, |i, j| t[i][j]);
    println!("{}", ans);
}
pub fn largest_rectangle(hist: &[usize]) -> usize {
    let mut stack = Vec::<(_, _)>::new();
    let mut res = 0;
    for (i, h) in hist.iter().cloned().enumerate() {
        let mut j = i;
        while stack.last().map_or(false, |x| x.1 > h) {
            let (k, p) = stack.pop().unwrap();
            res = res.max((i - k + 1) * (p + 1));
            j = k;
        }
        if stack.last().map_or(true, |x| x.1 < h) {
            stack.push((j, h));
        }
    }
    while let Some((i, h)) = stack.pop() {
        res = res.max((hist.len() - i + 1) * (h + 1));
    }
    res
}
pub fn largest_rectangle_in_grid(h: usize, w: usize, ok: impl Fn(usize, usize) -> bool) -> usize {
    let mut hist = vec![0; w];
    let mut res = 0;
    for i in 0..h {
        for j in 0..w {
            hist[j] = if ok(i, j) { hist[j] + 1 } else { 0 };
        }
        res = res.max(largest_rectangle(&hist));
    }
    res
}

