use std::cmp;

fn main() {
    input!(h: usize, w: usize, s: [chars; h]);
    let mut rectangle = vec![vec![false; w - 1]; h - 1];
    for h in 0..(h - 1) {
        for w in 0..(w - 1) {
            let mut count = 0;
            for h in h..(h + 2) {
                for w in w..(w + 2) {
                    if s[h][w] == '#' {
                        count += 1;
                    }
                }
            }
            rectangle[h][w] = count % 2 == 0;
        }
    }

    let mut ans = max_rectangle::maximize(&rectangle);
    ans = cmp::max(ans, h);
    ans = cmp::max(ans, w);

    println!("{}", ans);
}

pub mod max_rectangle {
    use std::cmp;
    use std::collections::VecDeque;

    fn calc_area(h: usize, w: usize) -> usize {
        (h + 1) * (w + 1)
    }

    fn calc(hist: &Vec<usize>) -> usize {
        let n = hist.len();
        let mut ans = 0;
        let mut q: VecDeque<(usize, usize)> = VecDeque::new();

        for i in 0..n {
            let mut reachable_min = i;
            while let Some((pos, height)) = q.pop_front() {
                if height <= hist[i] {
                    q.push_front((pos, height));
                    break;
                }
                reachable_min = pos;
                ans = cmp::max(
                    ans,
                    /* (i - reachable_min) * height */ calc_area(i - reachable_min, height),
                );
            }

            if q.is_empty() || q.iter().next().unwrap().1 < hist[i] {
                q.push_front((reachable_min, hist[i]));
            }
        }
        while let Some((pos, height)) = q.pop_front() {
            ans = cmp::max(
                ans,
                /* (n - pos) * height */ calc_area(n - pos, height),
            );
        }
        ans
    }

    pub fn maximize(map: &Vec<Vec<bool>>) -> usize {
        let h = map.len();
        let w = map[0].len();
        let mut hist = vec![vec![0; w]; h];
        for i in 0..h {
            for j in 0..w {
                if !map[i][j] {
                    continue;
                }
                if i == 0 {
                    hist[i][j] = 1;
                } else {
                    hist[i][j] = hist[i - 1][j] + 1;
                }
            }
        }

        let mut ans = 0;
        for i in 0..h {
            ans = cmp::max(ans, calc(&hist[i]));
        }
        ans
    }
}

// ---------- begin chmin, chmax ----------
trait ChangeMinMax {
    fn chmin(&mut self, x: Self) -> bool;
    fn chmax(&mut self, x: Self) -> bool;
}

impl<T: PartialOrd> ChangeMinMax for T {
    fn chmin(&mut self, x: Self) -> bool {
        *self > x && {
            *self = x;
            true
        }
    }
    fn chmax(&mut self, x: Self) -> bool {
        *self < x && {
            *self = x;
            true
        }
    }
}
// ---------- end chmin, chmax ----------

use proconio::*;
use proconio::marker::*;

fn run() {
    input! {
        h: usize,
        w: usize,
        s: [Bytes; h],
    }
    let mut ans = std::cmp::max(h, w);
    let mut height = vec![1; w];
    height[w - 1] = 0;
    let mut stack: Vec<(usize, usize)> = vec![];
    for i in 1..h {
        stack.clear();
        for j in 0..w {
            if j + 1 < w {
                let mut cnt = 0;
                for (x, y) in [(!0, 0), (!0, 1), (0, 0), (0, 1)].iter() {
                    cnt += (s[i + x][j + y] == b'#') as usize;
                }
                if cnt & 1 == 0 {
                    height[j] += 1;
                } else {
                    height[j] = 1;
                }
            }
            let mut p = j;
            while stack.last().map_or(false, |p| p.0 > height[j]) {
                let (x, y) = stack.pop().unwrap();
                p = y;
                ans.chmax(x * (j + 1 - y));
            }
            stack.push((height[j], p));
        }
    }
    println!("{}", ans);
}

fn main() {
    run();
}

