fn max_rectangle(v: &Vec<u64>) -> u64 {
    // let mut stack =  Vec::new();
    let f = |stack: &mut Vec<_>, (ind, x)| {
        let ind = ind+1;
        let mut y = 0;
        while let Some((top_val, pre_ind)) = stack.pop()  {
            if top_val < x {
                stack.push((top_val, pre_ind));
                y = pre_ind;
                break;
            }
        }
        stack.push((x, ind));
        Some((ind-y) as u64)
    };
    let l: Vec<_> = v.iter().cloned().enumerate()
        .scan(Vec::new(), &f).collect();
    let r: Vec<_> = v.iter().cloned().rev().enumerate()
        .scan(Vec::new(), &f).collect();
    let res = v.iter().zip(l.iter().zip(r.iter().rev())).enumerate()
        .map(|(i, (&x, (&l, &r)) )| {
            if i as u64 + 1 - l == 0 {
                (l+r-1)*x
            } else {
                (l+r)*x
            }
        }).max().unwrap();
    res
}

