fn solve(h: usize, w: usize, s: Vec<Vec<bool>>) -> u64 {
    let mut d = vec![vec![false; w+1]; h+1];
    for i in 0..h {
        for j in 0..w {
            if s[i][j] {
                d[i][j] ^= true;
                d[i+1][j] ^= true;
                d[i][j+1] ^= true;
                d[i+1][j+1] ^= true;
            }
        }
    }
    debug!(0);
    // d.iter().for_each(|x| println!("{}", show(x.iter().map(|&x| if x {1} else {0}))));


    let mut vec = vec![0; w];
    let mut ans = 0;
    for row in d.iter().take(h) {
        for i in 0..w {
            if row[i] {
                vec[i] = 1;
            } else {
                vec[i] += 1;
            }
        }
        ans = max(ans, max_rectangle(&vec));
    }
    max(max(h, w) as u64, ans)
