        self.t = self.x^(self.x << 11);
        self.x = self.y;
        self.y = self.z;
        self.z = self.w;
        self.w = (self.w ^ (self.w>>19)) ^ (self.t ^ (self.t>>8));
        self.w&0x7fffffff
    }
}


fn generater(rnd: &mut Random) -> (usize, usize, Vec<Vec<bool>>) {
    let h = (rnd.next()%5) as usize + 1;
    let w = (rnd.next()%5) as usize + 1;
    let mut s = vec![vec![false; w]; h];
    for row in &mut s {
        for e in row {
            if rnd.next()%2 == 0 {
                *e = true;
            }
        }
    }
    (h, w, s)
}

