    let mut ans = max(w, h);


    let mut height: Vec<usize> = vec![0; w-1];
    for i in 0..h {
        for j in 0..w-1 {
            let f = diff[i][j];
            if height[j] == i {
                while height[j] < h && diff[height[j]][j] == f {
                    height[j] += 1;
                }
            }
        }

        let mut h: Vec<usize> = vec![0; w-1];
        for j in 0..w-1 {
            h[j] = height[j] - i;
        }

