fn doit(a: Vec<usize>) -> usize {
    let n = a.len();
    let mut right: Vec<usize> = vec![0; n];
    {
        let mut stk: Vec<usize> = vec![];
        for i in (0..n).rev() {
            let mut last_removed = i;
            while stk.len() >= 1 && a[i] <= a[stk[stk.len()-1]] {
                last_removed = stk.pop().unwrap();
            }
            right[i] = last_removed;
            stk.push(i);
        }
    }

    let mut left: Vec<usize> = vec![0; n];
    {
        let mut stk: Vec<usize> = vec![];
        for i in 0..n {
            let mut last_removed = i;
            while stk.len() >= 1 && a[i] <= a[stk[stk.len()-1]] {
                last_removed = stk.pop().unwrap();
            }
            left[i] = last_removed;
            stk.push(i);
        }
    }

    let mut ans = 0;
    for i in 0..n {
        ans = max(ans, (right[i] - left[i] + 2) * a[i]);
    }
    ans
}

