            let mut stack = Vec::new();

            for (i, h) in hs.into_iter().enumerate() {
                if let Some((_, last)) = stack.last().cloned() {
                    match h.cmp(&last) {
                        Ordering::Equal => (),
                        Ordering::Greater => {
                            stack.push((i, h));
                        }
                        Ordering::Less => {
                            let mut t = 0;
                            while !stack.is_empty() && h < stack.last().unwrap().1 {
                                let (j, k) = stack.pop().unwrap();
                                maxv = max(maxv, (k + 1) * (i - j + 1));
                                t = j;
                            }
                            stack.push((t, h));
                        }
                    }
                } else {
                    stack.push((i, h));
                }
            }
            maxv
        })
        .max()
        .unwrap_or(0);

    println!("{}", ans);
}

