        for i in 0..n {
            while stk.len() >= 1 && a[i] <= a[stk[stk.len()-1]] {
                stk.pop();
            }
            left[i] = if stk.len() >= 1 { stk[stk.len()-1]+1 } else { 0 };
            stk.push(i);
        }
    }

    let mut ans = 0;
    for i in 0..n {
        ans = max(ans, (right[i] - left[i] + 1) * a[i]);
    }
    ans
}

