        }
    }

    let mut hists = vec![vec![0; w]; h - 1];

    for i in 0..h - 1 {
        for j in 0..w - 1 {
            if map[i][j] {
                hists[i][j] = 0;
            } else {
                if i > 0 {
                    hists[i][j] = hists[i - 1][j] + 1;
                } else {
                    hists[i][j] = 1;
                }
            }
        }
    }

    let ans = hists
        .into_iter()
        .map(|hs| {
            let mut maxv = 0;
            let mut stack = Vec::new();

            for (i, h) in hs.into_iter().enumerate() {
                let h = h + 1;

                if let Some((_, last)) = stack.last().cloned() {
                    match h.cmp(&last) {
                        Ordering::Equal => (),
                        Ordering::Greater => {
                            stack.push((i, h));
                        }
                        Ordering::Less => {
                            let mut t = 0;
                            while !stack.is_empty() && h < stack.last().unwrap().1 {
                                let (j, k) = stack.pop().unwrap();
                                maxv = max(maxv, k * (i - j + 1));
                                t = j;
                            }
                            stack.push((t, h));
                        }
                    }
                } else {
                    stack.push((i, h));
                }
            }
            maxv
        })
        .max()
        .unwrap_or(0);

    println!("{}", ans);
}

// ---------- begin chmin, chmax ----------
trait ChangeMinMax {
    fn chmin(&mut self, x: Self) -> bool;
    fn chmax(&mut self, x: Self) -> bool;
}

impl<T: PartialOrd> ChangeMinMax for T {
    fn chmin(&mut self, x: Self) -> bool {
        *self > x && {
            *self = x;
            true
        }
    }
    fn chmax(&mut self, x: Self) -> bool {
        *self < x && {
            *self = x;
            true
        }
    }
}
// ---------- end chmin, chmax ----------

use proconio::*;
use proconio::marker::*;

fn run() {
    input! {
        h: usize,
        w: usize,
        s: [Bytes; h],
    }
    let mut height = vec![vec![0; w + 1]; h];
    for i in 1..h {
        for j in 1..w {
            let mut cnt = 0;
            for &(x, y) in [(!0, !0), (0, !0), (!0, 0), (0, 0)].iter() {
                cnt += (s[i + x][j + y] == b'#') as usize;
            }
            height[i][j] = (cnt & 1) ^ 1;
        }
    }
    for i in 1..h {
        for j in 1..w {
            if height[i][j] > 0 {
                height[i][j] += height[i - 1][j];
            }
        }
    }
    let mut ans = std::cmp::max(h, w);
    for height in height.iter().skip(1) {
        let mut stack = vec![(0, 0)];
        for (i, &h) in height.iter().enumerate() {
            let i = i + 1;
            while stack.last().unwrap().0 > h {
                let (h, x) = stack.pop().unwrap();
                ans.chmax((h + 1) * (i - x + 1));
            }
            if stack.last().unwrap().0 < h {
                stack.push((h, i));
            }
        }
        assert!(stack == vec![(0, 0)]);
    }
    println!("{}", ans);
}

fn main() {
    run();
}
